    -- ═══════════════════════════════════
    -- MythicTracker Nomes EJ (2.9.10)
    -- ═══════════════════════════════════
    -- ═══════════════════════════════════
    -- Correção CD PartyFrame + Desempenho (2.9.12)
    -- ═══════════════════════════════════
    -- ═══════════════════════════════════
    -- Installer Overhaul & AB Toggle (2.9.17)
    -- ═══════════════════════════════════
    -- Objective Tracker Quest Buckets (2.9.18)
    -- ═══════════════════════════════════
    -- Smart Waypoint (2.9.20)
    -- ═══════════════════════════════════
    ["wn_2920_waypoint_redirect"]       = "Smart Waypoint — cross-zone redirect: the waypoint now tracks the next path step on your current map (portal, dungeon entrance) via C_SuperTrack.GetNextWaypointForMap(), updated on SUPER_TRACKING_PATH_UPDATED and zone changes.",
    ["wn_2920_waypoint_blob"]           = "Smart Waypoint — stuck 0 m fix: the beacon now hides automatically when the player is inside the quest objective area (C_Minimap.IsInsideQuestBlob), preventing the waypoint from freezing at 0 m.",
    ["wn_2920_waypoint_label"]          = "Smart Waypoint — dynamic label: the destination now shows the redirect step description (e.g. 'Travel to Durotar') or the tracked quest title instead of a blank field.",
    -- Objective Tracker Stability (2.9.19)
    -- ═══════════════════════════════════
    ["wn_2919_antiflicker"]             = "Anti-flicker — eliminated the visible 'trembling' of the Objective Tracker caused by a feedback loop between TomoMod's bucket layout and Blizzard's native Update / MarkDirty hooks. New re-entry guard, deferred pump coalescing, and a 0.20 s post-layout silence window break the recursion.",
    ["wn_2919_collapsed_persist"]       = "Collapsed bucket persistence — quest blocks under a collapsed bucket header no longer reappear when Blizzard re-runs its layout; each block gets a one-time Show hook that re-hides it while its bucket is folded.",
    ["wn_2919_header_detection"]        = "Module header detection — accent- and case-insensitive matching (Métier / métier / MÉTIER all resolve to the same keyword) and added singular variants. Quest titles and objective lines are now explicitly excluded so the full quest description is never accidentally hidden.",
    ["wn_2919_recipe_height"]           = "Recipe block height — Profession recipe blocks no longer overlap the next quest. The deepest-descendant measurement now runs unconditionally and walks 8 levels deep to reach reagent FontStrings (TrackedRecipe → Lines → Line[i]).",
    ["wn_2919_reward_preview"]          = "Reward preview exclusion — Delves (e.g. 'La Sombrevoie'), M+ scenarios, world quest reward popups and weekly vault reward blocks (e.g. 'Halte de l'Ombre-Garde' with ilvl preview) are now skipped from the bucket system. They stay in Blizzard's native location and no longer overlap our quests.",
    ["wn_2918_buckets"]                 = "Objective Tracker quest buckets — quests, world quests, weeklies, dailies, dungeons, raids, professions and achievements are now grouped into collapsible categories with colored headers and live count badges.",
    ["wn_2918_bucket_toggle"]           = "New 'Group quests into collapsible categories' checkbox in Config → Skins → Objective Tracker; disabling it instantly restores Blizzard's native module layout, no /reload required.",
    ["wn_2918_tracker_width"]           = "Tracker panel widened by 10 px so quest item icons no longer clip against the right edge.",
    ["wn_2918_layout_fix"]              = "Re-parented quest blocks now anchor both TOPLEFT and TOPRIGHT to prevent width collapse, and stale heights after collapse/expand are corrected via multi-pass layout.",

    ["wn_2917_ab_master_toggle"]        = "Action Bar master toggle — a new checkbox lets you fully disable bar management; after /reload, Blizzard's default action bars are fully restored.",
    ["wn_2917_installer_raid"]          = "Installer step 5 — Raid Frames: enable/disable, hide Blizzard frames, dispel highlights, HoT tracking, debuff and defensive icons, grid/list layout.",
    ["wn_2917_installer_coverage"]      = "Installer expanded — Skins step adds Objective Tracker, Mail, Reputation Bar; QOL step adds Auto Summon, Auto Quest, Class Reminder, Leveling Bar, Waypoint, World Quests, Frame Anchors, Profession Helper.",
    ["wn_2917_chat_skin_fix"]           = "Chat Skin fix — installer wrote to orphan key instead of the actual chatFrameSkin key.",
    ["wn_2917_talking_head_fix"]        = "HideTalkingHead fix — module now checks its DB toggle before suppressing the TalkingHead frame.",
    ["wn_2917_minimal_style"]           = "Action Bar Minimal style — the 5th skin style was missing from the Installer dropdown; now selectable.",

    -- AuctionRecipeTracker (2.9.15)
    -- ═══════════════════════════════════
    ["wn_2916_layout_fix"]              = "Falha silenciosa do botão Layout corrigida — em uma instalação nova, clicar em 'Layout' não fazia nada porque o sistema de movers não concluía a inicialização. Toggle agora faz inicialização tardia via pcall e exibe qualquer erro no chat em vez de falhar silenciosamente.",
    ["wn_2916_safe_init"]               = "Reforço da cadeia de init dos módulos — toda chamada Initialize() dos módulos TomoMod agora é envolvida em xpcall via um helper safeInit; um módulo com falha não quebra mais os ~45 módulos que inicializam depois dele, e o módulo culpado é reportado no chat.",
    ["wn_2916_art_total"]               = "AuctionRecipeTracker — cada cabeçalho de receita rastreada agora mostra o custo total global de seus reagentes à direita; se ao menos um reagente não tem preço registrado, um (~) cinza indica que o total é uma estimativa parcial.",
    ["wn_2916_avr_gui"]                 = "GUI Auto Vendedor / Reparo — duas novas caixas em Config → QOL → Automações permitem ativar independentemente o reparo automático no comerciante e a venda automática de itens cinzas (pobres); as configurações são persistidas em TomoModDB e se aplicam ao vivo sem /reload.",
    ["wn_2915_art_module"]              = "Novo módulo QOL — AuctionRecipeTracker: uma GUI abre automaticamente no leiloeiro quando ao menos uma receita de profissão está sendo rastreada; as linhas mostram '14x ícone Nome do item preço', clique para buscar na CL e um botão de escaneamento completo manual.",
    ["wn_2915_art_tooltip"]             = "Linha TomoHDV nas tooltips — após um escaneamento, cada item (mochilas, banco, links no chat, equipamento) mostra o preço unitário registrado, mais o preço total da pilha se stack > 1, e há quanto tempo o escaneamento foi feito.",
    ["wn_2915_art_scrollbar"]           = "Barra de rolagem moderna TomoMod — substitui a barra padrão da Blizzard por uma trilha fina de 4 px com um polegar em cor de destaque dimensionado proporcionalmente ao conteúdo; suporta arrastar, clique na trilha para pular, roda do mouse, e oculta-se automaticamente quando o conteúdo cabe.",
    ["wn_2915_art_anchor"]              = "Ancoragem padrão do AuctionRecipeTracker — a janela se cola na borda direita da janela da Casa de Leilões (TOPLEFT, AuctionHouseFrame, TOPRIGHT, 8, 0); posições personalizadas por arrasto permanecem persistentes e têm prioridade.",
    ["wn_2915_art_scan_fix"]            = "Confiabilidade do botão de escaneamento — OnShow agora reinicia scanInProgress, reativa o botão e restaura seu rótulo; retornos antecipados silenciosos (escaneamento em andamento, CL fechada, API ausente) agora exibem uma mensagem vermelha em vez de não fazer nada.",

    -- ═══════════════════════════════════
    -- MythicTracker Boss Names Fix (2.9.13)
    -- ═══════════════════════════════════
    ["wn_2913_boss_names"]               = "MythicTracker: os nomes dos chefes agora são exibidos corretamente em vez de \"Boss 1\", \"Boss 2\" etc. — no WoW 12.x o campo de critérios do cenário foi renomeado de criteriaString para description; o TomoMod agora lê description primeiro com criteriaString como fallback.",
    ["wn_2913_boss_checkmark"]           = "MythicTracker: o prefixo de marca de verificação da Blizzard (adicionado aos objetivos de chefe concluídos no 12.x) agora é removido antes da exibição.",
    ["wn_2913_ej_pcall"]                 = "MythicTracker: a chamada EncounterJournal_OpenJournal em FetchEJBossNames agora está envolvida em pcall para evitar possível taint no 12.x.",

    ["wn_2912_party_cd_fix"]             = "PartyFrame: o rastreamento de CD de interrupt e resurreicião de combate agora usa UNIT_SPELLCAST_SUCCEEDED com resolução segura de spellID (string.format); COMBAT_LOG_EVENT_UNFILTERED removido — registrá-lo de um addon causa taint no 12.x.",
    ["wn_2912_healer_interrupt"]         = "PartyFrame: o ícone do rastreador de interrupt agora está oculto para curandeiros — desde o patch 12.x os curandeiros não possuem mais habilidade de interrupt.",
    ["wn_2912_perf_cdm"]                 = "CooldownManager: UpdateButtonState agora armazena em cache GetCooldownTimes, GetCachedCooldownID e GetCooldownViewerCooldownInfo uma vez por botão por tick em vez de duas; ~50% menos chamadas de API no loop principal.",
    ["wn_2912_perf_aura"]                = "AuraTracker: taxa de atualização reduzida de 10 fps (0,1 s) para 5 fps (0,2 s); nenhuma diferença visível, overhead do ticker reduzido à metade.",
    ["wn_2912_perf_resbars"]             = "ResourceBars: limite OnUpdate para runas DK / stagger Monge aumentado de 50 ms para 100 ms; frequência de execução reduzida à metade sem impacto perceptível na exibição.",

    -- ═══════════════════════════════════
    -- Correções CooldownManager / ProcGlow / BuffSkin (2.9.11)
    -- ═══════════════════════════════════
    ["wn_2911_cdm_hooks"]                = "CooldownManager: cores de swipe e ocultação do GCD unificadas em um único hook por botão; a detecção do GCD agora usa o cache do Scanner em vez de pcall(C_CooldownViewer).",
    ["wn_2911_procglow_fixes"]           = "CDMProcGlow: o glow é aplicado de forma síncrona no ShowAlert para evitar uma race condition com o HideAlert no mesmo frame; timers por frame substituídos por um único ticker global de persistência; RefreshAll agora filtra corretamente os procs ativos.",
    ["wn_2911_buffskin_fixes"]           = "BuffSkin: SkinButton agora reaaplica âncoras e máscaras de ícone em frames reciclados pela Blizzard; hooks instalados uma única vez via hooksInstalled (ativar/desativar agora funciona corretamente); TemporaryEnchantFrame conectado para atualizações de encantamentos de arma; hooks instalados imediatamente.",

    -- ═══════════════════════════════════
    -- MythicTracker Nomes EJ (2.9.10)
    -- ═══════════════════════════════════
    ["wn_2910_ej_boss_names"]            = "MythicTracker: nomes dos chefes agora resolvidos via o Diário de encontros — localizados, compatíveis com acentos, cobrindo todas as masmorras de Cata até The War Within.",
    ["wn_2910_ej_fallback"]              = "MythicTracker: resolução de nomes em 3 níveis — dungeonEncounterID > índice EJ > criteriaString filtrada como alternativa, com retry automático (×5) se o EJ ainda não estiver carregado.",

    -- Player Auras Mover (v2.9.5)
    ["mover_player_auras"]       = "Auras do jogador",
    ["opt_auras_spacing"]        = "Espaçamento entre ícones",
    ["btn_reset_aura_position"]  = "Redefinir posição das auras",

    -- Module Reload Safety (v2.9.21)
    ["msg_module_reload"]        = "Esta alteração requer recarregar a interface.\nRecarregar agora?",
    ["info_module_reload"]       = "Requer /reload para ter efeito.",
    ["wn_2921_aura_mover"]       = "As auras do jogador agora têm seu próprio mover no modo Layout (overlay colorido, etiqueta, arrastar e soltar independente).",
    ["wn_2921_aura_gui"]         = "Novo controle de espaçamento de auras e botão de redefinição de posição na aba Auras da configuração.",
    ["wn_2921_reload_safety"]    = "Ativar/desativar um módulo principal (UnitFrames, Nameplates, Castbars, ActionBars, Party, Raid) agora oferece /reload automático.",

    -- Waypoint Arrow Reversed (v2.9.22)
    ["wn_2922_waypoint_arrow"]    = "A seta do navegador fora da tela do waypoint agora fica no lado oposto da órbita: quando o objetivo está à frente, a seta aparece na parte inferior e aponta para cima.",

    -- 3.0.3
    -- 3.0.4
    ["wn_304_consumable_bar"]    = "ConsumableBar — novo módulo QOL exibindo ícones do Frasco e Bem Alimentado com temporizador de contagem regressiva. Totalmente configurável (tamanho, espaçamento, orientação, posição do timer) e movível no Modo de Layout.",
    ["wn_304_cursor_textures"]   = "Anel do cursor — duas novas texturas adicionadas (Cygle e Coração). Seletor de textura disponível em Geral → Anel do cursor.",
    ["wn_304_mythichub_tp"]      = "Teleporte do MythicHub corrigido — sem mais taint (ADDON_ACTION_FORBIDDEN) ou erros de ancoragem ao clicar nas linhas de masmorra. IDs de feitiço para Maisara Caverns e Windrunner Spire também corrigidos.",

    -- 3.0.3
    ["wn_303_tracking_panel"]    = "Painel de rastreamento personalizado — clicar no botão de rastreamento agora abre um painel no estilo TomoMod à esquerda do minimapa em vez do menu suspenso nativo do Blizzard.",
    ["wn_303_collector_panel"]   = "Redesign do painel coletor — os botões de addon são agrupados em um painel TomoMod (fundo escuro, título em verde-azulado, borda na cor da classe) ancorado à esquerda do minimapa.",
    ["wn_303_collector_autoclose"] = "O coletor fecha automaticamente 0,5 s após o login/recarregamento assim que os botões são capturados — abre normalmente ao clicar.",
    ["wn_303_tooltip_fix"]       = "Correção do skin de tooltip — resolvido o grande retângulo preto que aparecia ao passar o mouse sobre unidades ou magias.",
    ["wn_303_coords_pos"]        = "As coordenadas do minimapa foram movidas para o centro inferior para melhor legibilidade.",

    -- 3.0.0
    ["wn_300_installer"]  = "Assistente de configuração totalmente novo — presets primeiro: escolha Recomendado, Tank, Curandeiro, DPS, Mínimo ou Personalizado e fique pronto em segundos.",
    ["wn_300_presets"]    = "Presets de configuração — um clique aplica uma configuração coerente e ajustada ao papel em todos os módulos; reutilizável quando quiser pelo /tm.",
    ["wn_300_dashboard"]  = "Novo painel Início no /tm — alternâncias rápidas de módulos, relançar o assistente, aplicar um preset, trocar de perfil e redefinir, tudo em um só lugar.",
    ["wn_300_search"]     = "Barra lateral com busca — filtre as categorias por nome ou palavra-chave (digite 'heal', 'cd', 'bag'…).",
    ["wn_300_locales"]    = "Localização completa de todos os novos textos 3.0 nos 6 idiomas suportados.",

    -- 3.0.5
    ["wn_305_rare_alert"]           = "Alerta de Raro — novo módulo QOL: reproduz um som e exibe um banner quando um NPC raro entra no alcance do minimapa. Clique esquerdo: marcar alvo + marcador de caveira + waypoint. Clique direito: fechar.",

    -- =====================
    -- Extra Action Button (v3.0.6)
    -- =====================
    ["mover_ab_extra"] = "Ação extra",
    ["mover_ab_pet"] = "Barra do familiar",
    ["mover_ab_stance"] = "Barra de posturas",
    ["section_extra_button"] = "Botão de ação extra",
    ["opt_extra_enabled"] = "Gerenciar o botão de ação extra (recarregar para liberar)",
    ["opt_extra_scale"] = "Escala do botão extra",
    ["btn_extra_reset_pos"] = "Redefinir posição",
    ["info_extra_button"] = "Posicione o botão de ação extra no Modo de Layout. Ele aparece durante missões e encontros. Ao desativar, ele volta para a Blizzard após um /reload.",
    ["wn_306_extra_button"] = "Novo — o botão de ação extra agora faz parte do sistema de barras de ação do TomoMod.",
    ["wn_306_extra_mover"] = "Novo — reposicione o botão de ação extra (e o botão de habilidade de zona) no Modo de Layout, como qualquer outra barra. Posição e escala são salvas no seu perfil.",
    ["wn_306_extra_scale"] = "Novo — opções do botão de ação extra em Barras de ação, aba Gerenciamento de barras: ativar, escala e redefinir posição.",
    ["wn_306_compass"] = "Correção — BúSSola: corrigido um erro de Lua frequente (x417) na conversão de coordenadas mundo (C_Map.GetWorldPosFromMapPos retorna continentID + worldPosition; o continentID é agora descartado corretamente).",
    ["wn_306_bagskin"] = "BagSkin — os slots agora usam ContainerFrameItemButtonTemplate da Blizzard: clique, uso, pegar e dividir são gerenciados por código seguro nativo (sem mais PreClick propenso a taint). Slots adiados durante o combate são reproduzidos automaticamente após o combate.",
    -- 3.0.7
    ["wn_307_objective_tracker"] = "Rastreador de objetivos — Os blocos de missões mundiais agora são classificados no grupo Missões Mundiais em vez de flutuar acima do rastreador. As barras de progresso (forças inimigas, % semanal) são ocultadas quando o grupo está recolhido.",
    ["wn_307_guardian_rage"]     = "Barras de recursos — Druidas Guardiões agora veem sua barra de Fúria centralizada na tela por padrão. O Mana permanece como barra secundária. A barra de poder no painel de unidade é ocultada automaticamente.",
    ["wn_307_resource_bars"]     = "Barras de recursos — Corrigido: os controles de altura para poder de classe e mana de druida agora se aplicam corretamente (conflito de nome de frame global resolvido). Novo controle para a altura da barra central. Nova caixa de seleção em Painéis de unidade › Jogador › Dimensões.",
    ["wn_310_brez_counter"]       = "Contador de Ressurreição de Combate — Novo HUD móvel mostrando quantas ressurreições de combate estão disponíveis e o tempo até a próxima carga. Lê o pool compartilhado, funciona em qualquer classe. Configure em Frames de Raid → Funcionalidades.",
    ["wn_310_resurrect"]          = "Indicador de ressurreição — Um ícone de rez agora aparece em um membro do grupo ou raid enquanto uma ressurreição está sendo lançada nele.",
    ["wn_310_raid_sizes"]         = "Frames de Raid — Novos layouts opcionais por tamanho (10 / 25 / 40): largura e altura dos frames se adaptam automaticamente ao tamanho atual do grupo. Configure em Frames de Raid → Funcionalidades.",
    ["wn_310_brez_fix"]           = "Frames de Grupo — Corrigido: o rastreador de cooldown de ressurreição de combate agora exibe corretamente o ícone acinzentado e o cronômetro de recarga quando um brez é consumido por alguém na instância.",

    -- 3.1.1
    ["art_searching"]        = "Pesquisando: %s",
    ["art_searching_qty"]    = "Pesquisando: %s × %d",
    ["wn_311_icicles"]        = "Mago do Gelo: novo rastreador de Icicles na barra de recursos (5 segmentos + brilho de Pico Glacial ao máximo). Cor personalizável em CD & Recursos → Cores.",
    ["wn_311_taint_money"]   = "Corrigido um erro de taint (Midnight): passar o mouse sobre itens no Compêndio de Masmorras não causa mais o erro de 'número secreto' no valor em ouro — o TomoMod não contamina mais as dicas de comparação.",
    ["wn_311_art_qty"]       = "AuctionRecipeTracker: clicar em um reagente pesquisa o item na Casa de Leilões e exibe a quantidade necessária na barra de status (ex. Pesquisando: Fogo Desperto × 14).",

    -- 3.1.2
    ["wn_312_brand"]         = "Cor de destaque atualizada de #0cd29f para #2ed884 (verde menta) em toda a interface — barra de título, painéis, mensagens do chat, popups e valores de cor padrão.",
    ["wn_312_brand_api"]     = "Novas constantes TomoMod_Utils.BRAND / BRAND_DARK / BRAND_HOVER centralizam a cor de destaque: os painéis de configuração e o tema de Widgets agora leem de uma única fonte.",
    ["wn_312_companion_fix"] = "CompanionStatus: corrigido um vazamento de variável global (UpdateIcon era declarada sem 'local').",

    -- 3.1.3
    ["wn_313_nav"]        = "Interface de configuração redesenhada: 16 painéis consolidados em 6 categorias agrupadas (Interface, Unidades, Combate, Conforto, Ferramentas), cada uma com cor de destaque e cabeçalho próprios.",
    ["wn_313_accent"]     = "Os widgets agora adotam automaticamente a cor de destaque do painel hospedeiro — cartões, cabeçalhos, separadores, caixas de seleção, botões e abas reagem ao contexto de categoria ativo.",
    ["wn_313_segmented"]  = "Novo widget SegmentedControl substitui menus suspensos curtos (Barra de bolsas, Menu Micro, Estilo de chat, Layout de bolsas, Classificação, Canal de áudio).",
    ["wn_313_dashboard"]  = "Painel Accueil completamente refeito: banner hero com status de diagnóstico ao vivo, atalhos rápidos (Instalador, Perfis, Diagnósticos, Recarregar) e botões de módulo redesenhados.",
    ["wn_313_np_preview"] = "Nameplates: novo painel de pré-visualização ao vivo no topo da configuração — mostra aliado, hostil e chefe, atualiza em tempo real ao ajustar largura, altura, barra de conjuro e tamanho da fonte.",
    ["wn_313_loot_filter"] = "Correção do filtro de classe de saque: itens ausentes do IDB (ex. drops de novos raids) agora usam o tipo de armadura como alternativa em vez de serem exibidos para todas as classes.",
    ["wn_313_sporefall"]   = "Dados de saque: raid Sporefall (ejEncounterID 2711) adicionado com 15 itens do dataset KeystoneLoot build 12.0.7.",
    ["wn_313_diag"]       = "Diagnósticos: 7 novas palavras-chave de exclusão UIError (comerciante, montaria, inventário, excluir, aprimoramento, aparência, duelo) + o console agora sempre aparece acima do menu de configuração.",
    ["wn_313_tooltip_anchor"] = "Posição do tooltip: novo sistema de ancoragem com 4 modos — Padrão, Cursor (segue o mouse), Canto (fixado em um canto da tela) e Personalizado (quadro arrastável).",

    -- Ancoragem do tooltip
    ["opt_tooltip_anchor"]        = "Posição do tooltip",
    ["tooltip_anchor_default"]    = "Padrão",
    ["tooltip_anchor_cursor"]     = "Cursor",
    ["tooltip_anchor_corner"]     = "Canto da tela",
    ["tooltip_anchor_custom"]     = "Personalizado",
    ["opt_tooltip_anchor_corner"] = "Canto (modo Canto)",
    ["corner_br"]                 = "Inferior direito",
    ["corner_bl"]                 = "Inferior esquerdo",
    ["corner_tr"]                 = "Superior direito",
    ["corner_tl"]                 = "Superior esquerdo",
    ["info_tooltip_anchor"]       = "Personalizado: selecione este modo e arraste o quadro teal para a posição desejada.",
    ["btn_tooltip_toggle_anchor"] = "Mostrar/Ocultar a âncora",
    ["mover_tooltip_anchor"]      = "Âncora da dica de ferramenta",

    -- Nameplates preview
    ["np_preview_title"]   = "Pré-visualização de placas",
    ["np_preview_hint"]    = "Legibilidade rápida: cor, conjuro, auras e ameaça em um só lugar.",
    ["preview_np_friendly"] = "Aliado",
    ["preview_np_target"]  = "Alvo hostil",
    ["preview_np_boss"]    = "Chefe marcado",

    -- 3.1.4
    ["wn_314_tooltip_anchor"] = "Posição do tooltip: novo sistema de 4 modos — Padrão, Cursor (segue o mouse), Canto (canto da tela) e Personalizado (quadro arrastável). Configurável em Skins → Tooltip.",
    ["wn_314_locale_fix"]     = "Corrigidas as etiquetas de cor do tooltip ausentes: os seletores de cor de fundo e borda em Skins → Tooltip agora são exibidos corretamente.",

    -- 3.1.5
    ["wn_315_ot_itembutton"] = "Rastreador de Objetivos: os botões de item de missão agora se ocultam corretamente quando seu bucket é recolhido (o botão é filho do tracker nativo, não do bloco — antes permanecia visível acima dos buckets recolhidos).",
    ["wn_315_talkinghead"] = "QOL: a opção «Ocultar Talking Head» voltou à GUI de configuração (QOL → Automações). Agora é aplicada instantaneamente sem /reload e é reversível — desmarcá-la restaura os diálogos de rolagem.",

    -- 3.1.6
    ["wn_316_party_combat"] = "Quadros de grupo: corrigidos bugs de visibilidade quando um membro entra, sai, ou o grupo se transforma em raide em pleno combate — os quadros agora aparecem/desaparecem de forma confiável em qualquer situação.",
    ["wn_316_raid_combat"] = "Quadros de raide: corrigido o problema de quadros ficarem presos visíveis ou ocultos quando membros do raide entravam ou saíam durante o combate — a visibilidade agora é controlada por um sistema seguro e compatível com combate.",
    ["wn_316_roster_repaint"] = "Quadros de grupo e raide: corrigidas informações desatualizadas (cor de classe, absorções, destaque de dispersão) que mostravam brevemente o jogador errado após uma mudança na composição, mesmo em combate.",
    ["wn_317_cdm_holders"] = "Cooldown Manager: novo sistema de 'Holders' — mova e trave livremente cada visualizador de cooldown (Essencial, Utilidade, Ícones de buff, Barras de buff) independentemente da grade do Modo de Edição da Blizzard, com pré-visualização ao vivo de ícones/barras enquanto vazios.",
    ["wn_317_resourcebars_health"] = "Barras de recursos: nova barra de vida opcional — altura configurável, formato (%, valor ou ambos), preenchimento colorido por classe, animação suave e um limite de cor para vida baixa.",
    ["wn_317_config_cards"] = "Interface de configuração: o painel Cooldown & Recursos agora tem um layout em cartões e uma nova aba Barras agrupando todas as configurações da barra de vida.",
    ["wn_316_locale_cdm"] = "Corrigido: a aba Barras, os cartões de posicionamento/pré-visualização ao vivo e a seção de barra de vida & animações exibiam chaves brutas em vez de texto traduzido — traduzido nos 6 idiomas.",
    ["wn_316_taint_chat"] = "Corrigido um erro de taint ('secret string value') no skin do chat ao receber mensagens de canal.",
    ["wn_316_taint_skyride"] = "Corrigido um erro de taint ('secret number value') na barra de velocidade do Skyriding, causado pelos valores protegidos de velocidade de voo/planeio do jogo.",
    ["wn_316_durability_pos"] = "Minimapa: a posição do texto de durabilidade agora é configurável (canto + deslocamento X/Y) em Interface → Geral → Info Panel — útil para evitar sobreposição com o novo botão de expansão do patch 12.0.7.",

    -- 3.1.7
    ["wn_317_libserialize_namespace"] = "Perfis: a biblioteca LibSerialize incorporada agora usa um namespace privado ('TomoSerialize-1.0') em vez do nome compartilhado 'LibSerialize', evitando conflitos de exportação/importação com outros addons que também incorporam LibSerialize.",
    ["wn_317_drag_absolute_coords"] = "Quadros móveis: corrigido o desvio ou inversão das posições salvas após arrastar na Barra de nível, Movers, AuctionRecipeTracker, Mythic+ Tracker, TomoScore, Frame Anchors, Bag Skin, barras de conjuração, âncoras de quadros de grupo/raide, Bússola, Barra de consumíveis, Navegador de Loot, Minimapa, Rastreador de Objetivos, barra de Skyriding, Barras de recursos e UnitFrames — as posições agora são salvas como coordenadas absolutas de tela, estáveis.",
    ["wn_317_ot_combat_taint"] = "Rastreador de Objetivos: corrigido um possível erro de taint quando a Blizzard reexibe um bloco de bucket de missão recolhido durante uma atualização de missão em combate.",
    ["wn_317_deadcode_cleanup"] = "Limpeza interna: vários módulos não utilizados/desativados foram removidos para reduzir o tamanho do addon — nenhuma funcionalidade visível ao usuário foi afetada.",
    ["wn_317_raidmanager_fix"] = "Quadros de raide: corrigido o painel padrão do líder de grupo da Blizzard (ready check, marcadores de alvo de raide, converter em raide, limite de pings, sair do grupo) que era ocultado junto com os quadros de raide ao ativar «Ocultar quadros de raide da Blizzard» — agora apenas o contêiner dos quadros de membros é suprimido, a barra de ferramentas do líder continua disponível.",
    ["wn_317_groupmanager_skin"] = "Quadros de raide: a opção «Personalizar o painel do líder de grupo» agora aplica uma reformulação completa à barra de ferramentas da Blizzard com o tema escuro/verde-menta do TomoMod — menus suspensos de modo e limite de pings, filtros de função/grupo, botões da barra de ferramentas (modo de edição, configurações, ready check, votação de função, contagem regressiva), botões de marcadores de raide com suas abas Unidade/Chão, e botões de sair do grupo com estilo vermelho — tudo isso sem alterar nenhum ícone da Blizzard, com alternância ao vivo sem precisar recarregar a interface.",
    ["wn_317_groupmanager_collapsetab"] = "Quadros de raide: corrigido o botão de recolher do painel do líder de grupo que deixava uma faixa residual na borda da tela, agora substituído por uma verdadeira aba verde-menta em vez de um simples botão personalizado.",

    -- 3.1.8
    ["wn_318_bagskin_itemclass_enum"] = "Bag Skin: a correspondência de categorias agora usa as constantes Enum.ItemClass da Blizzard (com fallback numérico) em vez de números de classe de item fixos no código, mantendo a categorização correta em todos os clientes.",
    ["wn_318_bagskin_cat_order"] = "Bag Skin: ordem padrão das categorias atualizada — Itens de missão agora são agrupados logo após Equipamento, antes de Consumíveis e Materiais.",
    ["wn_318_bagskin_cat_foundation"] = "Bag Skin: adicionada a base interna para uma futura opção de ocultar/reordenar categorias — Diversos e Espaços livres sempre permanecem visíveis para que nenhum item possa desaparecer.",

    -- 3.1.9
    ["wn_3110_actionbar_spelldrag"] = "Barras de ação: a correção de espaços vazios da 3.1.9 ainda não funcionava para uma magia, macro ou montaria já presente em uma barra (com «Mostrar espaços vazios» desativado) — movê-la para um espaço vazio agora funciona durante qualquer arraste, sem abrir o Livro de magias/Talentos.",
    ["wn_3110_skyride_taint"] = "Voo com planador: corrigido um erro de corrupção recorrente na exibição da velocidade em solo, que ainda podia ocorrer centenas de vezes por sessão apesar de uma correção anterior — o cálculo de velocidade agora conta com uma proteção extra para que não possa mais gerar um erro.",
    ["wn_3110_diag_exclusions"] = "Diagnóstico: adicionadas duas novas palavras-chave de exclusão (comerciante recusando comprar um item, saque bloqueado enquanto o modo Desafio está ativo) para que essas mensagens normais do jogo não sejam mais registradas como bugs.",
    ["wn_319_actionbar_dragfix"] = "Barras de ação: corrigido não ser possível arrastar uma magia para um espaço vazio (com «Mostrar espaços vazios» desativado) a menos que o Livro de magias/Talentos estivesse aberto — os espaços vazios agora se revelam durante qualquer arraste.",
    ["wn_319_ot_mover_fix"] = "Rastreador de Objetivos: corrigido o posicionamento da âncora que às vezes se resetava sozinho (o Modo de Edição da Blizzard podia sobrescrevê-lo silenciosamente) — arrastar agora permanece confiável.",
    ["wn_319_ot_quest_limit"] = "Rastreador de Objetivos: corrigido o controle «Máx. de missões exibidas» que não tinha nenhum efeito no layout padrão por Categorias.",
    ["wn_319_minimap_drift"] = "Minimapa: corrigido o minimapa que se movia sozinho para outra posição após um /reload (um erro de cálculo de escala aplicava o fator de escala duas vezes à posição salva).",
    ["wn_319_minimap_collector"] = "Minimapa: corrigido o coletor de botões que continuava ocultando os botões de outros addons após um reload mesmo estando desativado.",
    ["wn_319_minimap_tracking"] = "Minimapa: corrigido o botão de rastreamento que às vezes desaparecia, e o botão de rastreamento nativo da Blizzard que ficava impossível de clicar após ser revelado novamente.",
    ["wn_319_repbar_hide"] = "Barra de Reputação: corrigida a barra de reputação/honra própria da Blizzard que às vezes continuava aparecendo mesmo com a opção «Ocultar barra de reputação da Blizzard» ativada.",
    ["wn_319_tooltip_bg"] = "Dica de ferramenta: fundo padrão menos transparente (opacidade 92% → 97%) — ainda totalmente ajustável pelo controle de opacidade do fundo.",
    ["wn_319_tooltip_anchor"] = "Dica de ferramenta: a âncora de posição «Personalizado» não fica mais visível na tela fora do modo Layout, e um novo botão «Mostrar/Ocultar a âncora» foi adicionado em Skins → Tooltip.",
    ["wn_319_diag_copy"] = "Diagnóstico: corrigido o botão «Copy Report» que parecia não fazer nada — a janela de exportação podia abrir escondida atrás do console.",

    -- 3.1.11
    ["wn_3111_castbar_deathstuck"] = "Barra de lançamento: corrigido o problema em que a barra de lançamento de alvo, foco, chefe e outras unidades que não o jogador ficava travada visível na tela se a unidade morresse ou desaparecesse sem que nenhum evento de término correspondente fosse disparado.",
    ["wn_3111_castbar_targetreset"] = "Barra de lançamento: trocar de alvo ou foco agora redefine completamente a barra de lançamento em vez de apenas limpar seu temporizador de falha, evitando que um lançamento residual da unidade anterior continue sendo exibido na unidade recém-selecionada.",
    ["wn_3111_ot_lfgbutton"] = "Rastreador de Objetivos: recolher uma categoria de missões agora também oculta seu botão «Procurar grupo», não apenas o botão de item — ambos são restaurados corretamente ao expandir a categoria novamente.",
    ["wn_3112_score_taint"] = "Placar Mítico+: corrigida uma série de erros de corrupção (taint) que podiam impedir o placar de fim de masmorra de ser exibido/posicionado corretamente se o jogador ainda estivesse em combate no momento em que a masmorra terminou.",
    ["wn_3112_config_resize"] = "Janela de configuração: a janela /tm agora pode ser redimensionada arrastando seu canto inferior direito e escalada com um novo controle deslizante de 70-130% em Geral — tamanho padrão aumentado para 1240x820, com um botão para redefinir ambos com um clique.",
    -- =====================
