    -- 3.2.0
    ["wn_320_gsearch"] = "Janela de configuração: a busca na barra lateral agora é global — ela encontra opções correspondentes em todas as categorias e abas, não apenas na página visível, e clicar em um resultado leva direto até ele com um flash de destaque.",
    ["wn_320_panelcache"] = "Janela de configuração: alternar entre as abas de categoria agora é instantâneo após a primeira visita — os painéis são armazenados em cache em vez de serem reconstruídos toda vez.",
    ["wn_320_configlocale"] = "Janela de configuração: todos os rótulos em francês que ainda estavam fixos nos painéis de configurações agora são totalmente traduzíveis.",
    ["cfg_tab_cdforge"]           = "Cooldowns",

    -- 3.2.1
    ["wn_321_cdf_intro"] = "Novo — CooldownForge: crie barras de cooldown personalizadas por classe, rastreando feitiços, itens, predefinições (poções, pedra de cura...), bugigangas ou sua habilidade racial, na nova aba Cooldowns (categoria Combate).",
    ["wn_321_cdf_movers_io"] = "As barras do CooldownForge agora podem ser arrastadas pelo gerenciador de movimentação unificado, e compartilhadas entre personagens com uma string de importação/exportação por classe.",

    -- 3.2.2
    ["wn_322_studio_intro"] = "Novo — Cooldown Studio: um editor em tela cheia dedicado às barras do CooldownForge, com abas por barra de Layout/Estilo/Feitiços/Visibilidade/Compartilhamento, acessível pela aba Cooldowns.",
    ["wn_322_studio_fix"] = "Cooldown Studio: corrigido o problema em que a janela nem sempre era exibida acima de outras janelas, e seus widgets nem sempre herdavam a cor de destaque correta.",
    ["wn_322_studio_visibility"] = "Cooldown Studio: adicionada visibilidade condicional por barra — mostrar ou ocultar uma barra conforme o estado de combate, instância, grupo ou raide, com menus simples Indiferente/Sim/Não na aba Visibilidade.",
    ["wn_322_studio_finestyle"] = "Cooldown Studio: adicionados ajustes finos de estilo na aba Estilo — opacidade, cor/espessura da borda, uma cor personalizada do temporizador e um alternador de sombra projetada.",
    ["wn_322_forge_internal"] = "Interno: a lógica compartilhada do CooldownForge e do Cooldown Studio foi extraída para uma nova biblioteca interna Forge, preparando o terreno para futuros módulos de edição profunda — nenhuma mudança visível ao usuário.",
    ["wn_322_studio_fixes2"] = "Cooldown Studio: corrigido o problema em que os botões da barra lateral (Nova/Duplicar/Renomear/Excluir/modelos) às vezes não respondiam a cliques e transbordavam da linha, corrigido o Escape que fechava a janela causando um erro de corrupção (taint), e corrigida a aba selecionada que era reiniciada em vez de lembrada ao trocar de barra.",
    ["wn_322_studio_talents"] = "Cooldown Studio: a biblioteca de feitiços agora também inclui seus talentos ativos e talentos heróicos, não apenas feitiços do grimório, para que você possa rastreá-los também nas barras de cooldown.",
    ["wn_322_talent_scan_fix"] = "Cooldown Studio: corrigido o escaneamento de talentos/talentos heróicos da biblioteca que não encontrava nada no jogo — agora apenas os talentos realmente escolhidos são considerados, usando o campo de API correto para ler sua escolha selecionada.",
    ["wn_322_diag_taintown"] = "Diagnóstico: corrigidos relatórios fantasmas de ADDON_ACTION_FORBIDDEN (UseToy, SetNote...) atribuídos a addons aleatórios — o Diagnóstico agora assume posse exclusiva dos eventos de corrupção (taint) em vez de deixar o próprio tratamento da Blizzard repropagá-los.",
    ["wn_322_actionbars_discover"] = "Barras de ação: o texto informativo da aba Gerenciamento de barras agora também menciona que expandir uma barra revela seus controles de tamanho de botão e escala, tornando essa opção mais fácil de encontrar.",
    ["wn_322_tracker_editmode"] = "Rastreador de objetivos: corrigido o rastreador travando ao arrastá-lo enquanto o Modo de Edição nativo da Blizzard estava ativo.",
    ["wn_323_studio_preview"] = "Cooldown Studio: a aba Estilo agora mostra uma pré-visualização de ícones ao vivo (mesma renderização das barras reais) alternando entre pronto/em cooldown, para ver as mudanças de estilo instantaneamente.",
    ["wn_323_studio_copystyle"] = "Cooldown Studio: adicionado um botão \"Copiar estilo de...\" na aba Estilo para copiar apenas o estilo visual de outra barra sem alterar feitiços, posição ou layout.",
    ["wn_323_studio_create"] = "Cooldown Studio: \"+ Nova\" agora pede o nome da barra desde o início em vez de criar um espaço reservado que depois precisa ser renomeado, e os pop-ups de renomear/criar agora aparecem de forma confiável acima da janela com o campo de nome focado automaticamente.",
    ["wn_323_slider_entry"] = "Controles deslizantes de configuração: clique com o botão direito em um valor para digitar um número exato, Ctrl+clique para redefinir para o padrão, com uma dica na tooltip para ambos.",
    ["wn_323_petbar_editmode"] = "Barras de ação: as barras de Mascote e Formas agora podem ser selecionadas e arrastadas no Modo de Edição mesmo quando ocultas em repouso (sem mascote/formas).",
    ["wn_324_studio_real_icons"] = "Cooldown Studio: a pré-visualização da aba Estilo agora usa ícones reais — primeiro os feitiços da própria barra, depois o grimório e os talentos da sua classe — em vez de três ícones de demonstração fixos de classes sem relação.",
    ["wn_324_chat_contacts"] = "Chat: a barra lateral do chat ganhou um botão Contatos que abre a lista de amigos da Blizzard com um clique, restaurando um acesso que havia sumido porque o visual oculta o botão social nativo.",
    ["wn_324_editbox_scrollbar"] = "Configuração: as caixas de texto de várias linhas (importar/exportar, notas...) não mostram mais a barra de rolagem dourada da Blizzard — agora usam a barra fina com a cor de destaque do addon e funcionam com a roda do mouse.",
    ["wn_325_friends_window"] = "Contatos: a janela de amigos agora está totalmente estilizada em vez de ser um trabalho pela metade — corpo escuro e plano, borda de destaque desenhada sobre a lista, título reestilizado e um simples botão de fechar de destaque.",
    ["wn_325_friends_tabs"] = "Contatos: as abas inferiores e as subabas Amigos / Aliados recentes / Recrute um amigo perderam suas placas douradas, e agora mostram um sublinhado e um rótulo de destaque na selecionada.",
    ["wn_325_friends_buttons"] = "Contatos: todos os botões da janela (Adicionar amigo, Enviar mensagem, os botões da aba Quem, Converter em raide, Info de raide, Entrar na fila) agora compartilham um mesmo estilo plano de destaque que clareia ao passar o mouse, e os dois botões de contato dividem igualmente a linha inferior.",
    ["wn_325_friends_toggle"] = "Contatos: desativar o visual nas configurações agora restaura o aspecto da Blizzard imediatamente, sem precisar recarregar.",
    ["wn_325_cdf_radial"] = "CooldownForge: as barras de recarga agora podem dispor seus ícones em círculo em vez de em linha — ajuste o raio, o ângulo inicial, a amplitude do arco e o sentido pelo novo modo de disposição.",
    ["wn_325_cdf_spacing"] = "CooldownForge: o espaçamento dos ícones agora são dois valores separados — ao longo da linha e entre linhas quebradas — e o máximo foi elevado de 16 para 64 px.",
    ["wn_325_cdf_glow"] = "CooldownForge: o brilho agora pode ser acionado conforme uma condição à escolha — quando a magia está pronta, enquanto um bônus está ativo em você (com um ID de bônus opcional para berloques/talentos), ou sempre — configurável por barra ou por magia.",
    ["wn_325_cdf_hidecd"] = "CooldownForge: uma barra agora pode ocultar cada ícone enquanto ele está em recarga, com os ícones restantes fechando a lacuna; ela se reorganiza apenas quando o conjunto de magias prontas muda.",
    ["wn_326_whatsnew_stuck"] = "Novidades: fechar esta janela com Esc deixava a tela escurecida e o mouse morto, e a versão sem marcação, então ela voltava no login seguinte. Todas as formas de fechar (X, botão, Esc) passam agora por um único ponto que remove o escurecimento e memoriza a versão.",
    ["wn_326_whatsnew_escape"] = "Novidades: o Esc agora é capturado pela própria janela em vez de passar pelo UISpecialFrames da Blizzard, o que elimina um caminho de taint pelo menu do jogo; todas as outras teclas continuam passando.",
    ["wn_326_whatsnew_gates"] = "Novidades: a janela agora espera um momento livre — nunca por cima de uma cinemática, um vídeo ou um combate — e pula totalmente o primeiro login de um personagem, para não te receber no meio da sequência de introdução.",
    ["wn_326_tracker_empty"] = "Rastreador de objetivos: quando nada está sendo rastreado, não sobra mais um painel escuro cobrindo quase toda a tela — ele agora se reduz ao seu cabeçalho, e «Ocultar quando vazio» vem ativado por padrão (perfis existentes são atualizados uma vez; se você desativar de novo, fica desativado).",
    ["wn_326_tracker_drag"] = "Rastreador de objetivos: o painel pode ser arrastado para baixo novamente — a fixação à tela era aplicada ao quadro superdimensionado da Blizzard, cuja borda inferior já ficava fora da tela, então todo movimento para baixo era recusado.",
    ["wn_326_repbar_drag"] = "Barra de reputação: corrigido o caso em que a barra mostrava sua borda de desbloqueio no modo Disposição mas não podia ser agarrada — o mouse nunca foi habilitado nela, então o arrasto não conseguia começar.",
    -- Suportes do Cooldown Manager (Movers / modo disposição)
    ["mover_cdm"]                        = "Cooldown Manager",
    ["cdm_drag_hint"]                    = "Arraste para mover",
    ["cdm_preview_aura"]                 = "Aura",

    ["wn_326_suite_card"] = "Config: o painel inicial ganhou um cartão «Suíte Tomo» apresentando o TomoBoss (temporizadores de chefes com avisos falados) — um atalho para as opções dele se estiver instalado, ou um endereço copiável e um «Não mostrar novamente» definitivo caso contrário.",

    ["wn_330_cdf_unusable"] = "CooldownForge: um ícone agora pode se tingir quando a magia não está em recarga mas não pode ser conjurada no momento — sem fúria, forma errada, reagente ausente. Três opções: nenhum efeito (padrão), esmaecer, ou esmaecer com um tom azul quando o que bloqueia é justamente o recurso; configurável por barra e por magia.",
    ["wn_330_cdf_glow_usable"] = "CooldownForge: o brilho ganhou uma condição «quando a magia é utilizável» — pronta *e* conjurável, para que uma magia sem recurso pare de brilhar enquanto espera, em vez de convidar a um toque que falharia.",
    ["wn_330_cdf_hide_unusable"] = "CooldownForge: uma barra também pode ocultar por completo um ícone enquanto faltar o recurso, ao lado do filtro «ocultar durante a recarga» já existente. Os dois são independentes e acumuláveis, e os ícones restantes fecham o vão.",
    ["wn_330_cp_charged"] = "Barras de recursos: os pontos de combo sobrecarregados agora são mostrados como tais — o espaço carregado é marcado esteja ele cheio ou não, para você ver onde está a carga antes de gastá-la. A cor é escolhida em CD & Recursos → Cores, vermelho por padrão.",
    ["wn_330_colorpicker"] = "Configuração: o seletor de cor abria atrás da janela de ajustes e do Cooldown Studio, o que parecia que a amostra não fazia nada. Agora ele abre acima delas, bem ao lado da amostra que você clicou em vez do centro da tela.",
    ["wn_330_locale_escapes"] = "Localização: as opções da Bússola mostravam códigos de escape crus no lugar dos acentos — «BxC3xBAssola», «direxC3xA7xC3xA3o», «Amplo (xC2xB190xC2xB0)». Esses textos usavam uma sintaxe de escape que o Lua do jogo não entende e imprimia literalmente; voltaram a ficar legíveis, nos seis idiomas.",
    ["wn_330_diag_filters"] = "Diagnóstico: estar enraizado no lugar e tentar enviar pelo correio um item vinculado eram registrados como erros no relatório. Ambos são respostas normais do jogo e agora são filtrados como o resto.",
    ["wn_330_tracker_delve_place"] = "Rastreador de objetivos: com «Ocultar se vazio» desativado o painel continuava lá, mas o bloco da expedição nunca era posicionado dentro dele — o caso vazio saía antes da passagem que o posiciona. Os módulos de cenário e de expedição agora são posicionados primeiro, seja o que for que esteja sendo rastreado.",
    ["wn_330_tooltip_info"] = "Dica: as dicas de unidade trazem enfim uma verdadeira camada de informação — cargo de guilda, alvo atual da unidade, pontuação Mítica+, montaria, velocidade de movimento e localização, além dos ícones de marcador de raide, função e classe na linha do nome. Cada linha tem seu próprio interruptor em Skins → Dica.",
    ["wn_330_tooltip_inspect"] = "Dica: passar o mouse sobre um jogador agora mostra o nível de item equipado e a especialização dele. Ambos exigem inspecionar, então só aparecem dentro do alcance; o nível de item é colorido pela diferença para o seu, em vez de limiares de temporada que vencem a cada patch.",
    ["wn_330_tooltip_border"] = "Dica: a borda pode assumir a cor da unidade — cor de classe para um jogador, hostil / neutro / amigável para um NPC — e a linha de nível é recolorida por dificuldade, em vermelho para um chefe ou uma unidade «??».",
    ["wn_330_tooltip_bar"] = "Dica: a barra de vida agora fica oculta por padrão, já que a camada de informação a substitui. Os perfis existentes são atualizados uma vez; desmarcar a opção traz a barra de volta e isso permanece.",
    ["wn_330_pf_leader"] = "Quadros de grupo: o líder do grupo agora é marcado com uma coroa acima do quadro dele, com interruptor e controle de tamanho próprios.",
    ["wn_330_stance_bar"] = "Barras de ação: classes sem formas de metamorfose ficavam com uma barra de posturas de dez casas vazias, e desmarcar «mostrar espaços vazios» fazia a barra inteira sumir. Ela só aparece agora se você realmente tiver formas, com exatamente tantos botões quanto formas.",
    ["wn_330_leveling_panel"] = "Barra de nível: passar o mouse abre agora um painel estilizado no lugar de uma dica, com nível, XP, XP restante, progresso, descanso, XP/h, tempo para subir, XP ganha desde o último nível e a contribuição da última missão. Ele vai para baixo da barra quando não há espaço acima.",
    ["wn_330_bags_click"] = "Bolsas: desencantar, moer ou prospectar pela skin de bolsas exigia duas tentativas — o clique pressionado consumia o cursor de alvo e a soltura pegava o item no lugar. Funciona de primeira agora, e arrastar não foi afetado.",
    ["wn_330_bags_layout"] = "Bolsas: o layout «Categorias» foi removido, restando Grade combinada e Bolsas separadas. Um perfil ainda configurado nele é movido uma vez para a grade combinada.",
    ["wn_330_chat_copy"] = "Bate-papo: o ícone de cópia por mensagem colocava um glifo de espaço reservado à frente de cada linha, porque sua textura nunca era resolvida. A opção foi removida e é limpa uma vez para quem a tinha ativada.",

    ["wn_331_tooltip_secret"] = "Dica: toda a camada de informações de unidade adicionada na 3.3.0 nunca aparecia no Midnight — sem rank de guilda, alvo, pontuação Mítica+, montaria, velocidade, localização, nível de item, especialização ou ícones na linha do nome. A camada relê o identificador de unidade a partir da dica, o jogo agora o devolve como um valor protegido e a proteção o rejeitava: nada era escrito.",
    ["wn_331_tooltip_border"] = "Dica: a borda com a cor da unidade estava desligada pelo mesmo motivo — lia o identificador pela sua própria proteção e desistia, então cada unidade caía na cor de borda configurada, o que parecia exatamente a opção não fazer nada.",
    ["wn_331_tooltip_target"] = "Dica: a linha do alvo sumia para qualquer jogador cujo nome volta protegido, ou seja, a maioria. O nome não é mais envolvido em um código de cor — montar essa string equivale a ler o nome — e a cor passa pelos argumentos de cor da própria dica. Idêntico na tela, e agora funciona.",
    ["wn_331_tooltip_guards"] = "Dica: as próprias proteções podiam levantar um erro. Uma comparava o valor com uma string vazia antes de verificar se ele era protegido, então quebrava justamente nos valores que deveria interceptar, e cerca de vinte testes de sim/não (a unidade existe, é um jogador, pode ser inspecionada…) eram comparados sem proteção. Tudo é verificado na ordem certa agora.",
    ["wn_331_inspect"] = "Dica: nível de item e especialização voltam junto com o resto — o motor de inspeção fazia as mesmas comparações desprotegidas em cada teste de elegibilidade e desistia diante de um valor protegido antes mesmo de enviar uma requisição.",
    ["wn_330_tracker_delve"] = "Rastreador de objetivos: dentro de uma expedição o rastreador não mostrava nada — nem etapa, nem critérios, nem progresso. «Ocultar se vazio» contava apenas blocos de missão, enquanto uma expedição registra seu progresso no módulo de cenário, que essa contagem deixa de fora de propósito, então o painel inteiro ficava oculto. Expedições, cenários e objetivos bônus agora contam como conteúdo, e o painel se ajusta ao tamanho deles quando estão sozinhos na tela.",
    ["wn_327_tracker_progressbars"] = "Rastreador de objetivos: as barras de progresso das missões (contagens de abates, forças inimigas, critérios de cenário e de expedição) voltaram — uma barra não é mais descartada como órfã quando seu bloco só é alcançável por uma âncora, ela sobrevive a recolher e reabrir seu grupo, e as que permanecem finalmente adotam o tema do resto do rastreador.",
    ["wn_327_tracker_position"] = "Rastreador de objetivos: um rastreador movido pelo Modo de Edição da própria Blizzard voltava ao lugar anterior no recarregamento seguinte — essa posição nunca era gravada no banco de dados do addon. Agora ela é salva ao encerrar a sessão do Modo de Edição, e um rastreador com escala diferente de 100% não desliza mais um pouco a cada recarregamento.",
    ["wn_327_minimap_indicators"] = "Minimapa: o indicador de dificuldade de instância continuava visível fora das instâncias, porque reancorar os indicadores nativos também os forçava a ficar visíveis e anulava a regra da Blizzard. Eles voltam a seguir a visibilidade da Blizzard — e o botão de expansão não fica mais invisível para sempre depois de ser desativado e reativado.",
    ["wn_327_resourcebar_frozen"] ="Barras de recursos: a barra de poder centralizada ficava travada no valor que tinha ao ser construída — 0 de fúria, 0 de energia — em todas as especializações cujo único recurso é o principal (Guerreiro, Sacerdote, Mago de Fogo, Tecelão de Névoa, Havoc...), enquanto o quadro de unidade mostrava o valor real bem ao lado. Ela volta a se atualizar como qualquer outra barra.",
    ["wn_327_profile_rename"] ="Perfis: renomear ou duplicar um perfil não fazia absolutamente nada — a reescrita das janelas pop-up na 11.2 removeu o campo de onde o nome digitado era lido. Ambos voltam a funcionar, e Enter agora confirma como o botão de aceitar.",
    ["wn_327_cds_rename"] = "Cooldown Studio: a mesma correção para as janelas «Renomear barra» e «+ Nova» — o nome digitado era ignorado, então renomear não fazia nada e toda barra nova saía chamada «Nouvelle barre».",
    ["wn_327_popup_layer"] = "Pop-ups: o aviso de recarregamento, as janelas de importar / exportar e todas as confirmações de perfil eram desenhados atrás da janela de configuração e do Cooldown Studio, parecendo que nada acontecia. Agora eles sobem acima da janela do TomoMod que estiver aberta.",
    ["wn_327_profile_refresh"] = "Perfis: criar, excluir, renomear ou duplicar um perfil agora atualiza a lista na tela em vez de deixar a anterior servida pelo cache das páginas.",
    ["wn_327_import_perf"] = "Perfis: importar está bem mais rápido — a string decodificada para a pré-visualização é reaproveitada na confirmação em vez de ser decodificada uma segunda vez, o que era a maior parte do travamento ao clicar em Importar.",
    ["wn_327_gui_split"] = "Config: Perfis e Diagnósticos voltam a ser categorias separadas na barra lateral em vez de agrupadas sob Ferramentas, cada uma com seu ícone e sua descrição; links antigos para Ferramentas continuam funcionando.",

