    ["wn_300_minimap"]                    = "Botão do minimapa — acesso rápido às funções e configurações do TomoMod.",
    ["wn_300_buttonbag"]                  = "Button Bag — agrupa e gerencia seus botões de ação de forma eficiente.",
    ["tab_qol_rare_alert"]                = "Alerta de raros",
    ["section_rare_alert"]                = "Alerta de raros",
    ["opt_rare_alert_enable"]             = "Ativar os alertas de proximidade de raros",
    ["opt_rare_alert_sound"]              = "Reproduzir um som de alerta",
    ["opt_rare_alert_duration"]           = "Duração do banner (s)",
    ["btn_reset_rare_alert_pos"]          = "Redefinir a posição do banner",
    ["rare_alert_info"]                   = "Avisa você quando um NPC raro está por perto. Clique no banner para alvejá-lo, colocar o marcador de caveira e definir um ponto de rota. Clique com o botão direito para dispensar. Use /tm layout para mover o banner.",
    ["rare_alert_tooltip"]                = "Clique esquerdo: alvejar + caveira + ponto de rota. Clique direito: dispensar.",
    ["wn_305_rare_alert_marker"]          = "Clique no banner de um raro para alvejá-lo, colocar o marcador de caveira e definir um ponto de rota. Som e duração configuráveis; arrastável no modo de layout.",
    ["wn_305_tm_fix"]                     = "Corrigido — clicar em um alerta de raro do RareScanner não abre mais a configuração do TomoMod (a colisão do comando /tm foi resolvida).",

    -- =====================
    -- 3.3.2 — Novidades
    -- =====================
    ["wn_332_perf_auras"] = "Desempenho: o rastreador de auras e o estilo dos bônus agora só escutam as suas próprias mudanças de auras. Eles nunca agiram sobre mais ninguém, mas eram acordados por cada unidade cujas auras mudavam — mais de vinte membros da raide e cada placa visível, sem parar — apenas para conferir a unidade e descartá-la. O jogo as filtra agora, antes que qualquer código nosso seja executado.",
    ["wn_332_perf_castbar"] = "Desempenho: o mesmo para o monitoramento de latência da barra de conjuração, que era acordado por cada conjuração de cada unidade visível — um grupo inteiro de lacaios em habilidades — quando só as suas próprias conjurações importavam.",
    ["wn_332_perf_gc"] = "Desempenho: o rastreador de auras era a maior fonte de lixo de memória da interface. Sua varredura e seu arranjo rodavam várias vezes por segundo em combate e descartavam uma pilha de tabelas temporárias a cada passagem; agora reutilizam as mesmas tabelas de trabalho. Nada muda na tela.",
    ["wn_332_aura_order"] = "Rastreador de auras: duas auras aplicadas com a mesma conjuração e a mesma duração podiam trocar de lugar visivelmente entre atualizações, porque nada definia a ordem delas. Agora é estável.",
    ["wn_332_skyride_leak"] = "Voo dracônico: /tm skyride construía uma segunda cópia da barra a cada uso. A antiga permanecia na tela, sem ligação com mais nada e impossível de ocultar, porque o jogo nunca recupera um quadro. A barra é construída uma única vez e o comando apenas reaplica as suas configurações nela.",
    ["wn_332_skyride_ticker"] = "Voo dracônico: o mesmo comando também deixava para trás, a cada vez, uma atualização permanente a 4 Hz que não havia mais como parar. Elas não se acumulam mais, e a atualização para quando o módulo é desativado em vez de consultar uma barra oculta.",
    ["wn_332_tooltip_incombat"] = "Dica: o nível de item e a especialização sumiam de todas as dicas assim que um combate começava, e voltavam ao terminar. A verificação de alcance com que o motor de inspeção terminava é uma das que o jogo se recusa a responder para addons em combate: assim, cada unidade era considerada fora de alcance durante todo o grupo — enquanto o registro de contaminação se enchia com uma chamada bloqueada por passagem do mouse. Agora ele usa uma verificação que funciona em combate.",
    ["wn_332_tooltip_backoff"] = "Dica: a verificação de alcance substituta é menos precisa (enxerga bem mais longe do que uma inspeção realmente alcança), então um jogador distante demais para responder passa a ser lembrado e deixado de lado por vinte segundos em vez de ser consultado a cada dica. Só pode haver uma inspeção em andamento por vez, e um jogador fora de alcance ocupava essa vaga repetidamente. Uma dica que nunca recebeu resposta também não fica mais presa em «carregando».",
    ["wn_332_diag_nopath"] = "Diagnóstico: investir por cima de um vão, saltar para uma saliência ou mandar um lacaio para onde ele não consegue andar era registrado como erro no relatório. «Nenhum caminho disponível» é um retorno normal do jogo, e agora é filtrado nos seis idiomas.",
    ["wn_332_locale_castbar"] = "Configuração: a caixa principal do painel Barras de conjuração aparecia como «Ativar a barra de consumíveis» em todos os idiomas — duas opções diferentes compartilhavam a mesma chave de tradução e a dos consumíveis vencia. Agora cada uma tem a sua.",
    ["wn_332_locale_translations"] = "Localização: 173 textos por idioma traduzidos para alemão, espanhol, italiano e português — configurações avançadas e de visibilidade do gerenciador de recargas, categorias de missões do rastreador de objetivos, interface do bate-papo, movedores e texturas de cursor —, além dos 49 textos da interface do bate-papo em francês. Eles recorriam silenciosamente ao inglês em vez de mostrar um erro, então ninguém os havia relatado.",
    ["wn_332_locale_search"] = "Configuração: a caixa de busca mostrava o texto bruto «gs_no_results» em vez de «Nenhuma opção correspondente» quando não havia resultados. A mensagem já está definida nos seis idiomas.",
    ["wn_332_package"] = "Empacotamento: o download não inclui mais as suítes de testes, exemplos, documentação gerada e arquivos readme das bibliotecas incluídas. Nada disso era carregado pelo addon.",
    ["wn_332_companion_panel"] = "Lembrete de mascote: o módulo que avisa quando seu mascote está ausente ou morto finalmente tem um painel de configurações, em QOL. A ativação, o tamanho, a escala, a exibição de ícone, texto ou ambos e a posição na tela só podiam ser alterados editando um arquivo à mão.",
    ["wn_332_companion_travel"] = "Lembrete de mascote: ele podia ficar na tela, com quatro vezes o tamanho, durante um voo inteiro. Só verificava se você estava voando em momentos em que ainda estava no chão, e depois nada conseguia ocultá-lo. Agora fica oculto durante voo, em rotas de voo e em veículos — e também em montaria terrestre, o que você pode desativar.",
    ["wn_332_companion_locale"] = "Lembrete de mascote: «Mascote ausente» e «Mascote morto» apareciam em inglês qualquer que fosse o idioma do cliente. Ambos estão traduzidos, assim como todo o novo painel.",

    -- =====================
    -- 3.3.3 — Novidades
    -- =====================
    ["wn_333_summon_stuck"] = "Quadros de grupo e de raide: o ícone de invocação ficava no quadro até recarregar a interface. Depois de aceitar ou recusar, o jogo continua devolvendo o último estado da invocação em vez de limpá-lo, então o ícone descrevia algo que tinha deixado de existir minutos antes. Agora ele verifica se realmente há uma invocação em aberto antes de mostrar qualquer coisa.",
    ["wn_333_summon_roster"] = "Quadros de grupo e de raide: ao mudar a composição, um ícone de invocação podia ficar em um quadro que já pertencia a outro jogador. O estado é relido a cada mudança de composição e após cada troca de zona, e é atualizado junto com o resto do quadro em vez de apenas quando o jogo anuncia uma mudança.",
    ["wn_333_defensives_party"] = "Quadros de grupo: as recargas defensivas ativas em cada membro agora são exibidas. Isso só existia nos quadros de raide, e lá era um único ícone, sem duração e sem indicar do que se tratava.",
    ["wn_333_defensives_categories"] = "Quadros de grupo e de raide: as defensivas são divididas em externas (conjuradas neste jogador — Casca de Ferro, Casulo Vital, Supressão da Dor), de raide (Grito de Reunião, Escuridão, Zona Antimagia) e pessoais (Escudo Divino, Bloco de Gelo, Pele de Árvore), cada uma com sua própria opção. Cinquenta magias, ordenadas para que as externas venham primeiro, com o tempo restante e uma borda colorida por categoria.",
    ["wn_333_defensives_defaults"] = "Quadros de grupo e de raide: por padrão apenas as externas são exibidas. Uma defensiva de raide acende todos os quadros ao mesmo tempo — justamente quando estão menos legíveis — e as pessoais são constantes. Ambas podem ser ativadas.",
    ["wn_333_defensives_size"] = "Quadros de raide: o controle deslizante do tamanho dos ícones defensivos só tinha efeito após recarregar. Agora se aplica enquanto você o arrasta.",
    ["wn_333_hots_drift"] = "Quadros de grupo e de raide: os dois conjuntos de quadros discordavam sobre quais curas ao longo do tempo mostrar. Bênção do Verão, Totem de Aguaceiro e Sopro Envolvente apareciam nos quadros de grupo mas não nos de raide — o mesmo bônus, no mesmo jogador, visível em um e não no outro. Agora há uma única lista, cobrindo as seis classes curandeiras.",
    ["wn_333_dispel_border"] = "Quadros de grupo e de raide: a espessura da borda do destaque de dissipação agora é ajustável, de 1 a 6. Ela cresce para fora, então uma borda mais grossa nunca invade a barra de vida, e o valor padrão aparece exatamente como antes.",
    ["wn_333_stance_grid"] = "Barras de ação: com «mostrar espaços de botão vazios» desativado, a barra de posturas ainda podia colocar dez quadrados vazios na tela, e eles ficavam lá até você trocar de postura. A passagem que revela os espaços vazios enquanto você arrasta uma magia também percorria as barras de posturas e de lacaio, cujos botões não são espaços de ação — então ela julgava todos vazios e os mostrava, enquanto a passagem que os esconde de novo pula deliberadamente essas duas barras, de modo que não sobrava nada para colocá-los de volta.",
    ["wn_333_diag_display"] = "Diagnóstico: os relatórios agora incluem sua resolução, modo de exibição e escala da interface — e sinalizam o caso em que a escala foi definida por algo que não as opções do jogo. Acima de 1200 pixels de altura o cliente não reduz a escala o suficiente sozinho, de modo que configurações de alta resolução acabam redimensionadas à mão ou por outro complemento, e isso era invisível em um relatório.",
    ["wn_333_diag_scalechange"] = "Diagnóstico: uma mudança de escala ou de resolução durante a sessão é registrada com seus valores antes e depois, para que um redimensionamento apareça ao lado dos erros que ele pode ter causado. Esse redimensionamento é reaplicado após cada tela de carregamento, que é justamente quando ele quebra coisas.",
    ["wn_333_diag_perf"] = "Diagnóstico: os relatórios agora trazem a taxa de quadros (atual, além do mínimo, da média e do máximo da sessão) e a latência, e cada erro capturado registra a taxa de quadros no momento em que ocorreu. Um erro que só aparece em um cliente travando é um problema de sincronia e não um recurso quebrado, e nada em um relatório permitia distinguir os dois.",
    ["wn_333_diag_scale_expected"] = "Diagnóstico: o relatório afirmava que a escala da sua interface tinha sido definida por uma macro ou por outro complemento em quase toda configuração. Quando a opção de escala da interface do próprio jogo está desligada, o valor com que ele comparava não é o que o jogo está usando, então uma configuração perfeitamente comum era sinalizada. Agora ele calcula qual escala é esperada para a sua resolução e as suas configurações, imprime esse valor e só avisa quando há uma diferença real.",
    ["wn_333_diag_settle"] = "Diagnóstico: a escala que o jogo aplica por conta própria durante o login era registrada em todo relatório como um redimensionamento no meio da sessão. A captura de exibição agora espera quatro segundos até o cliente se estabilizar antes de fazer uma leitura, de forma que a única entrada de escala que resta em um relatório é aquela que realmente precisa de explicação.",
    ["wn_333_diag_mode"] = "Diagnóstico: quando o relatório não consegue determinar seu modo de exibição, ele agora imprime os valores brutos que o jogo forneceu em vez de apenas um ponto de interrogação — esses nomes de configuração mudam de uma expansão para outra, e um «?» sozinho não podia ser diagnosticado sem voltar a perguntar. Tela cheia em janela e janelas maximizadas são reconhecidas em mais casos, e as versões dos complementos não aparecem mais como «vv1.2.3».",
    ["wn_333_shared"] = "Interno: os quadros de grupo e de raide mantinham duas cópias das mesmas 250 linhas — a lógica de invocação, a lista de curas ao longo do tempo, o rastreamento de defensivas. Os três problemas acima vêm daí: uma correção aplicada a uma cópia e não à outra. Agora eles compartilham uma única implementação.",
    -- =====================
    -- 3.6.2 — What's New
    -- =====================
    ["wn_362_vault_types"] = "Correção — A prévia da Grande Câmara no Mythic Hub agora lê suas linhas de Raides, Masmorras e Abismos a partir dos tipos de recompensa oficiais da Blizzard, em vez de deduzi-los do que a API de recompensas semanais retornasse, então a linha de Abismos não aparece mais vazia nem preenchida com as atividades de outra linha.",
    ["wn_362_vault_progress"] = "Correção — A prévia da Grande Câmara não força mais uma atualização da própria janela de Recompensas Semanais da Blizzard antes de ler o seu progresso. Essa atualização zera o progresso das atividades enquanto uma recompensa anterior ainda não foi coletada, o que fazia masmorras, chefes de raide e abismos já concluídos aparecerem como 0.",
    ["wn_362_vault_slots"] = "Correção — Cada linha da Grande Câmara agora pede ao jogo as suas próprias atividades e as ordena por nível de recompensa, de modo que as entradas extras que a API retorna ao lado das linhas reais (recompensas bônus e de recuperação) não podem mais ocupar um espaço visível.",
    ["wn_362_ab_release"] = "Correção — Os botões de ação voltam a responder ao soltar o clique. Aos botões do próprio TomoMod faltava o atributo seguro de liberação que a Blizzard instala em seus botões de ação: com “Conjurar ao pressionar” desativado nada era conjurado, e as magias de manter pressionado, como as magias potencializadas do Evocador, podiam ser iniciadas mas nunca liberadas.",
    ["wn_362_ab_release_gse"] = "Correção — Um botão que foi usado para uma sequência do GSE agora volta ao comportamento normal de pressionar e soltar de uma ação comum assim que sua ação muda, em vez de manter o contrato do GSE até o próximo recarregamento.",
    ["wn_362_ab_counts"] = "Correção — Os contadores de cargas e acúmulos das barras de ação não provocam mais uma atualização completa de todos os botões a cada evento de aura ou de carga. Em pulls grandes na Mítica+ esses eventos chegam em rajadas; em combate o trabalho agora é agrupado algumas vezes por segundo, o que mantém as teclas responsivas. Fora de combate nada é limitado.",
    ["wn_362_ab_glow"] = "Correção — A passagem de segurança que limpa os brilhos de proc remanescentes não reexamina mais todos os botões de ação visíveis a cada evento de brilho. O botão que perde o brilho continua sendo atualizado na hora, e a verificação completa agora roda no máximo dez vezes por segundo, então combates com muitos procs não custam mais latência de entrada.",
    ["wn_362_ab_assist_rotation"] = "Alterado — O Combate Assistido agora localiza seus botões de ação pela API dedicada de espaços de Combate Assistido do jogo, em vez de percorrer todas as barras procurando a magia sugerida no momento, de modo que uma troca de sugestão não toca mais em botões não relacionados.",
    ["wn_362_ab_assist_load"] = "Correção — Uma troca de sugestão do Combate Assistido não atualiza mais todos os botões de ação do TomoMod, e o TomoMod não engancha mais uma função de destaque da Blizzard que pode ser chamada na cadência da rotação durante o combate. Juntos, esses eram a maior fonte de trabalho extra enquanto a rotação de Um Botão estava ativa.",
    ["wn_362_ab_assist_highlight"] = "Correção — O destaque do Combate Assistido agora é limpo quando o jogo para de sugerir uma magia, e alternar a opção de destaque assistido da Blizzard passa a valer imediatamente, em vez de exigir um recarregamento.",
    -- =====================
    -- 3.6.1 — What's New
    -- =====================
    ["wn_361_assist"] = "Correção — O quadro de rotação de Combate Assistido da Blizzard agora é exibido e atualizado corretamente nos botões de ação do TomoMod, em vez de travar no campo de ação Lua não sincronizado do botão.",
    ["wn_361_keydown"] = "Correção — A configuração “Conjurar ao pressionar” do TomoMod agora permanece sincronizada com a CVar de entrada da própria Blizzard, corrigindo uma primeira pressão após o login que podia ser ignorada silenciosamente.",
    ["wn_361_safewindow"] = "Correção — As ligações de override adiadas por combate após um /reload em combate agora são reproduzidas de forma confiável após o combate, em vez de depender de uma janela de segurança que podia ela mesma permitir ações bloqueadas.",
    ["wn_361_strata"] = "Correção — Os botões da Barra de Ação 1, Ajudante e Postura não são mais renderizados acima de painéis em tela cheia da Blizzard, como o Mapa Mundial.",
    ["wn_361_flyouts"] = "Correção — Flyouts de magia como Portal/Teletransporte de Mago voltam a abrir e conjurar corretamente; o TomoMod não redimensiona mais os botões de flyout nativos de uma forma que pudesse contaminar (taint) o flyout seguro.",
    ["wn_361_flyouts_cast"] = "Correção — Os botões popup nativos do flyout não são mais interceptados (hook) nem modificados de forma alguma, já que até alterações cosméticas podiam contaminar (taint) o caminho protegido CastSpellByID/CastSpellByName da Blizzard.",
    ["wn_361_flyout_secure"] = "Correção — Os botões de ação do TomoMod agora atualizam seu flyout de magias pelo próprio UpdateFlyout da Blizzard dentro de uma chamada segura, e os métodos de popup substitutos do TomoMod foram removidos dos botões próprios. A seta do flyout, o popup que ela abre e a conjuração seguinte permanecem inteiramente no caminho protegido da Blizzard.",
    ["wn_361_bar6_quarantine"] = "Correção — Os flyouts de magias na Barra 6 não correm mais o risco de ficar proibidos de serem conjurados: essa barra agora usa o flyout seguro próprio do TomoMod em vez do nativo da Blizzard, já que o flyout nativo ainda podia ser contaminado especificamente ao ser aberto pela Barra 6. Todas as outras barras continuam usando o flyout nativo da Blizzard.",
    ["wn_361_flyout_keybind"] = "Correção — Pressionar um atalho de teclado atribuído para abrir ou fechar um botão de flyout do TomoMod agora funciona corretamente; antes apenas o clique do mouse era reconhecido.",
    ["wn_361_flyout_discovery"] = "Correção — O TomoMod agora também verifica os slots de ação reais da barra em quarentena para encontrar seus flyouts, em vez de depender apenas da enumeração do livro de magias, para que os flyouts colocados ali sempre mostrem os ícones corretos de slot conhecido/desconhecido.",
    ["wn_361_vehicle_mover"] = "Novo — Sair do Veículo agora tem seu próprio quadro de posicionamento no modo de layout, podendo ser colocado em qualquer ponto da tela em vez de ficar fixo acima da Barra de Ação 1. A posição é salva com o perfil e, por padrão, o botão continua logo acima da Barra 1 até ser movido.",
    ["wn_361_vehicle_state"] = "Alterado — O botão Sair do Veículo agora é exibido quando você realmente pode sair do veículo, em vez de sempre que uma interface de veículo está na tela, portanto ele não aparece mais em veículos dos quais não é possível sair.",
    ["wn_361_vehicle_taxi"] = "Correção — O botão Sair do Veículo da própria Blizzard agora só é ocultado enquanto o substituto seguro do TomoMod estiver utilizável, mantendo um controle de saída funcional em voos de táxi e em veículos que não permitem saída antecipada.",
    ["wn_361_tracker"] = "Correção — Blocos de missão ignorados durante o combate no Rastreador de Objetivos agora terminam de se organizar automaticamente ao fim do combate, em vez de permanecerem sobrepostos até um evento de missão não relacionado.",
    ["wn_361_buttonbag"] = "Correção — O coletor de botões de addon do minimapa não esquece mais os botões já reunidos ao fazer uma nova varredura: os addons que registram seu botão mais tarde agora abrem uma nova linha em vez de se empilharem sobre a primeira.",
    ["wn_361_trackdupe"] = "Correção — O painel de Rastreamento não lista mais a mesma entrada duas vezes (“Banqueiro” aparecia em duas linhas). Os filtros de rastreamento que o jogo retorna com o mesmo nome são unidos em uma única linha que os alterna em conjunto.",
    ["wn_361_micromenu_native"] = "Correção — O TomoMod não cria mais seu próprio contêiner, não reassocia botões nem interfere no layout do Micro Menu da Blizzard; o antigo módulo independente de Microbarra foi removido por completo.",
    ["wn_361_micromenu_gui"] = "Alterado — O painel de opções de Bolsa e Micro Menu agora mostra uma seção compacta para o olho do localizador de grupo no lugar do antigo construtor de Microbarra, com apenas um alternador liga/desliga e um controle deslizante de tamanho.",
    ["wn_361_lfgeye_fix"] = "Correção — O olho do localizador de grupo não desaparece mais quando o Micro Menu esmaece ao passar o mouse; agora ele tem seu próprio controle de visibilidade e tamanho, atualizado automaticamente ao entrar no mundo, entrar numa fila ou quando uma masmorra/campo de batalha é encontrada.",
    ["wn_361_validation"] = "Testado — Combate Assistido, conjuração ao pressionar, ligações após reload em combate, o posicionamento de Barra 1/Ajudante/Postura perto do Mapa Mundial, os flyouts de magia, o adiamento de combate do Rastreador de Objetivos e o olho do localizador de grupo durante o esmaecimento do Micro Menu e eventos de LFG foram validados em jogo.",
    -- =====================
    -- 3.6.0 — What's New
    -- =====================
    ["wn_360_foundation"] = "Alteração — As barras de ação agora usam um modelo de propriedade sem taint: os botões do TomoMod ficam fora do broadcaster nativo da Blizzard e o estado protegido das barras Blizzard continua sob controle da Blizzard.",
    ["wn_360_nativebars"] = "Correção — As barras de ação padrão da Blizzard continuam ativas para o paging seguro, mas ficam visualmente ocultas, exibindo apenas as barras TomoMod sem congelar o estado dinâmico.",
    ["wn_360_specialvisuals"] = "Correção — As barras Blizzard de postura, ajudante e possessão continuam funcionais em segundo plano enquanto texturas, textos, GCD, efeitos de autocast, bordas ativas e flashes duplicados são mascarados.",
    ["wn_360_stance"] = "Correção — Os botões de postura do TomoMod agora usam ações de magia seguras e independentes e continuam clicáveis para formas de Druida, auras de Paladino e posturas de Guerreiro.",
    ["wn_360_pet"] = "Correção — Os botões de ajudante do TomoMod agora usam ações seguras e independentes; comandos, habilidades e alternância de autocast com clique direito continuam funcionando sem depender da barra Blizzard visível.",
    ["wn_360_possess"] = "Correção — Estados de possessão e veículo continuam pelo paging seguro da Barra de Ação 1 em vez de exigir que o TomoMod manipule a PossessActionBar da Blizzard.",
    ["wn_360_paging"] = "Correção — A Barra de Ação 1 lê diretamente seu slot de ação seguro atual, mantendo o paging de formas, veículo, override e possessão ativo sem congelá-lo em uma cópia Lua.",
    ["wn_360_formsafe"] = "Correção — Mudanças de Druida Humano/Felino/Urso agora atualizam corretamente a Barra de Ação 1 dentro e fora de combate, sem erros de ação protegida ou cooldown secreto observados nos testes.",
    ["wn_360_extra"] = "Correção — Ação Extra mantém o comportamento seguro da Blizzard enquanto o TomoMod fornece o botão visível, seu próprio GCD/cargas e uma área de clique limpa sem hitbox nativa invisível roubando a entrada.",
    ["wn_360_zone"] = "Correção — Habilidade de Zona mantém ícones dinâmicos, GCD e cargas, desaparece quando deixa de estar ativa e preserva o comportamento de clique nativo exigido por certas habilidades de missão.",
    ["wn_360_vehicle"] = "Correção — Sair do Veículo continua como uma ação segura do TomoMod com o visual comum das barras, enquanto o comportamento de táxi da Blizzard permanece disponível quando necessário.",
    ["wn_360_gcd"] = "Correção — Restos do GCD nativo de formas, auras e posturas são mascarados visualmente sem tocar nos valores de cooldown da Blizzard nem no estado protegido dos botões.",
    ["wn_360_petvisuals"] = "Correção — As bordas de estado ativo, flashes e overlays de autocast restantes da barra de ajudante Blizzard agora ficam ocultos enquanto o estado real do ajudante continua totalmente funcional.",
    ["wn_360_skin"] = "Alteração — Ação Extra, Habilidade de Zona e Sair do Veículo agora usam o mesmo pipeline de visual dos botões de ação TomoMod que o restante das barras.",
    ["wn_360_flyouts"] = "Correção — Os flyouts de habilidades voltam a abrir corretamente nas barras de ação do TomoMod, incluindo portais de Mago e armadilhas de Caçador.",
    ["wn_360_installer"] = "Correção — O instalador de primeiro uso agora carrega de forma confiável em instalações novas e espera o fim de cinemáticas, vídeos e combate antes de aparecer.",
    ["wn_360_rolesafe"] = "Correção — Quadros de grupo/raide, placas de nome, TomoScore, chat e tooltips agora lidam com segurança com os dados de função restritos do Midnight em vez de gerar erros de valores secretos.",
    ["wn_360_mythiccombat"] = "Correção — MythicHub e os comandos do TomoScore agora esperam o fim do combate antes de abrir ou atualizar controles protegidos e continuam automaticamente depois.",
    ["wn_360_profiles"] = "Correção — As janelas de Importar/Exportar perfis agora tratam Escape com segurança em combate sem causar ações de entrada do teclado bloqueadas.",
    ["wn_360_validation"] = "Testado — Barras padrão, paging Humano/Felino/Urso, postura, ajudante, possessão, botões especiais, mouse/teclado e combate foram validados em jogo sem novos erros de taint das ActionBars.",
    -- =====================
    -- 3.5.9 — What's New
    -- =====================
    ["wn_359_visibility"] = "Novo — As barras de ação agora têm um Motor de Visibilidade Segura com regras compatíveis com combate para estado de combate, tipo de grupo, instâncias, montarias, alvos, modo oculto e condições seguras personalizadas.",
    ["wn_359_gcd"] = "Alteração — O swipe do GCD continua visível onde deve, mas um GCD puro não mostra mais uma contagem fracionária poluída; o texto numérico fica reservado para a recarga real da ação.",
    ["wn_359_editmode"] = "Correção — O Modo de Edição da Blizzard agora abre sem os erros protegidos TargetUnit/FocusUnit ou as falhas de valores secretos dos quadros compactos de grupo que antes podiam ser atribuídas ao TomoMod.",
    ["wn_359_dormancy"] = "Novo — Barras ocultadas de forma segura agora entram em repouso e deixam de fazer trabalho visual desnecessário. Os atalhos continuam ativos e a barra faz uma atualização completa assim que volta a aparecer.",
    ["wn_359_nativeglow"] = "Novo — O TomoMod agora usa seu próprio motor de brilhos nativo em vez do LibCustomGlow, removendo o antigo caminho de erro AnimateTexCoords e centralizando as animações de proc.",
    ["wn_359_conditional"] = "Correção — Habilidades condicionais como Toque da Morte do Monge agora atualizam usabilidade e proc pelas notificações de ação da Blizzard. Uma habilidade inutilizável permanece escurecida em vez de ser substituída incorretamente pelo vermelho de alcance.",
    ["wn_359_specialbars"] = "Correção — As barras de ajudante, postura e possessão da Blizzard permanecem totalmente sob controle da Blizzard para segurança contra taint, mas são filtradas com o roleset alwaysBlocked do 12.1, evitando barras nativas duplicadas sem trazer de volta os erros do Modo de Edição.",
    ["wn_359_paging"] = "Novo — O Paging Seguro da Barra de Ação 1 adiciona páginas Alt/Shift/Ctrl, páginas para Alvo Amigável/Hostil e paging opcional de formas e voo dinâmico, tudo configurável no TomoMod_Options.",
    ["wn_359_priority"] = "Alteração — A prioridade do paging mantém Veículo/Override/Possessão como estados principais, enquanto páginas manuais e por modificador têm prioridade sobre páginas automáticas de forma ou voo dinâmico quando apropriado.",
    ["wn_359_formsafe"] = "Correção — As mudanças de forma do Druida em combate agora são confiáveis, sem erros de ação protegida ou recarga secreta ao alternar entre Humano, Felino e Urso.",
    ["wn_359_zoneability"] = "Correção — Os botões de Habilidade de Zona agora mantêm ícone, GCD e cargas sincronizados, mudam corretamente com o estado da missão e desaparecem quando a habilidade deixa de estar disponível.",
    ["wn_359_extragcd"] = "Correção — Os botões de Ação Extra agora espelham o GCD e a recarga de cargas no visual do TomoMod sem ler nem modificar o widget de recarga nativo da Blizzard.",
    ["wn_359_specialbuttons"] = "Alteração — Ação Extra, Habilidade de Zona e Sair do Veículo mantêm o comportamento seguro da Blizzard enquanto o TomoMod fornece os controles visuais, preservando missões, veículos e táxis.",
    ["wn_359_specialskin"] = "Alteração — Ação Extra, Habilidade de Zona e Sair do Veículo agora usam exatamente o mesmo visual dos demais botões de ação do TomoMod; áreas clicáveis invisíveis da Blizzard não roubam mais cliques nem dicas.",
    ["wn_359_validation"] = "Testado — Formas, botões especiais, cliques do mouse, GCD/cargas, visibilidade, brilhos nativos, Modo de Edição e paging seguro foram validados em jogo sem novos erros de taint nas ActionBars.",

    -- =====================
    -- 3.5.8 — What's New
    -- =====================
    ["wn_358_input"] = "Correção — A entrada das barras de ação agora responde imediatamente: interrupções, habilidades instantâneas, ações com/sem GCD, spam rápido de teclas e atalhos com Shift/Ctrl não sofrem mais o atraso percebido anteriormente.",
    ["wn_358_state"] = "Correção — Mover, substituir ou limpar uma ação, trocar especialização ou talentos, página, forma, veículo ou voo dinâmico agora atualiza os botões corretamente, sem ícones, recargas, brilhos, estados cinza ou cargas antigas.",
    ["wn_358_range"] = "Alteração — No Midnight 12.1, a coloração de alcance agora usa as notificações nativas da Blizzard, enquanto mana e usabilidade são atualizados por eventos. A varredura periódica antiga permanece apenas como fallback de compatibilidade.",
    ["wn_358_glowflyout"] = "Correção — Os brilhos de proc acompanham melhor feitiços base e transformados, brilhos antigos são removidos e flyouts abertos em barras ocultas por mouseover permanecem visíveis e voltam ao fade normal ao fechar.",
    ["wn_358_taintstate"] = "Interno — Estados personalizados antes armazenados diretamente em frames da Blizzard foram movidos para weak tables externas, reduzindo o estado do addon anexado a objetos protegidos.",
    ["wn_358_registry"] = "Correção — Os botões do TomoMod são isolados dos registros e broadcasters nativos da Blizzard quando necessário, impedindo o controlador de executar botões nativos retirados por caminhos contaminados.",
    ["wn_358_secretcooldown"] = "Correção — Em combate, o log podia ser inundado por erros quando a Blizzard tentava aplicar valores secretos de recarga a botões nativos retirados. Esses caminhos agora estão isolados.",
    ["wn_358_stancepossess"] = "Correção — StanceBar e PossessActionBar agora permanecem totalmente sob controle da Blizzard. Isso elimina o erro protegido da MainActionBar reproduzido ao invocar um companheiro temporário de Monge em combate.",
    ["wn_358_blizzbars"] = "Correção — As barras de ação padrão da Blizzard voltam a ser ocultadas pelo caminho visual seguro validado para 12.1, deixando apenas as barras do TomoMod visíveis sem reintroduzir o taint do controlador.",
    ["wn_358_validation"] = "Testado — O novo caminho das barras de ação foi validado em combates intensos, reloads, mudanças de talentos/especialização, formas, veículos, voo dinâmico, feitiços transformáveis, cargas, flyouts, procs e companheiro de Monge sem erros de ActionBar.",


    -- =====================
    -- 3.5.7 — Novidades
    -- =====================
    ["wn_357_talkingheadfix"] = "Correção — Ocultar Talking Head podia deixar a locução de um talking head tocando por baixo de um quadro oculto. Os quadros de talking head gerenciam sua própria visibilidade, então simplesmente ocultar o quadro ao ser exibido deixava o estado de reprodução e seu temporizador de finalização em execução — e pulava cada linha após a primeira em um talking head de várias linhas, já que o quadro já estava visível para essas. O TomoMod agora se conecta à função de reprodução real e fecha cada talking head da mesma forma que o próprio Blizzard faz, o que interrompe de forma confiável o temporizador e a locução juntos.",
    ["wn_357_talkingheadcleanup"] = "Interno — Uma chamada para parar o som emitida no mesmo instante em que uma locução começa é ocasionalmente ignorada pelo motor de som, então Ocultar Talking Head agora insiste novamente uma fração de segundo depois para garantir que realmente pare.",
    ["wn_357_queueeyedb"] = "Correção — A posição do olho da fila na verdade nunca era salva. Faltava sua entrada na tabela de configurações padrão, então o manipulador de salvamento ignorava silenciosamente a gravação de uma nova posição toda vez que você o arrastava — o olho se movia bem na tela, mas esquecia onde você o colocou no próximo login. A entrada ausente está de volta, e o caminho de salvamento agora a cria na hora se suas configurações salvas ainda não a tiverem, de modo que um salvamento desatualizado não custa mais do que uma tabela extra.",
    ["wn_357_queueeyeposition"] = "Correção — A posição padrão do olho da fila era um palpite às cegas que caia em um lugar diferente a cada resolução — totalmente fora da tela em um monitor ultrawide, foi assim que isso foi descoberto. Agora ela fica por padrão ao lado do minimapa, onde o olho realmente vive.",
    ["wn_357_lfgeyesurvive"] = "Novidade — O olho do localizador de grupo desaparecia completamente ao ocultar o micromenu da Blizzard, já que ele vive dentro desse mesmo contêiner. Agora ele permanece no lugar — o status da fila do localizador de grupo está sempre visível, onde quer que você o tenha posicionado, esteja o micromenu nativo oculto ou não.",
    ["wn_357_lfgeyeoptions"] = "Novidade — Duas novas opções da microbarra permitem desativar completamente o olho do localizador de grupo ou redimensioná-lo, ao lado da opção que oculta o micromenu da Blizzard.",
    ["wn_357_lfgeyescale"] = "Correção — O controle deslizante de tamanho do olho do localizador de grupo não fazia nada a menos que a microbarra estivesse totalmente ativada com «ocultar o micromenu da Blizzard» também ativado — caso contrário, a escala era silenciosamente redefinida para o normal a cada atualização. Agora ela se aplica de qualquer forma.",
    ["wn_357_roletaintguard"] = "Correção — Um erro de placa de nome ainda podia ocorrer ao comparar uma função não legível diretamente, mesmo com a proteção já existente. Essa comparação agora é verificada duas vezes, então uma função ilegível é tratada como nenhuma função em vez de gerar um erro.",
    ["wn_357_cooldowntaint"] = "Correção — Alguns botões da barra de ação podiam acumular um erro ao atualizar sua animação de recarga quando o jogo não permitia ler o valor diretamente, mesmo em barras com a skin desativada. Essa atualização agora é ignorada com segurança em cada botão afetado e em cada recarga que ele carrega, em vez de gerar um erro.",
    ["wn_357_mainbartaint"] = "Correção — Um erro raro podia aparecer ao tentar reexibir a barra de ação padrão depois de montar ou entrar em um veículo. Agora ele é silenciado da mesma forma que casos semelhantes.",
    ["wn_357_mailiconcrash"] = "Correção — O ícone de correio do minimapa podia gerar um erro toda vez que você recebia uma correspondência nova. Isso não acontece mais, e o ícone se comporta exatamente como antes.",
    ["wn_357_buggrabber"] = "Novidade — Se você também usa o !BugGrabber, o Diagnostics agora se apoia nele também, capturando erros que ele viu antes de o próprio rastreamento do TomoMod começar nesta sessão. Nada muda se você não o tiver instalado.",
    ["wn_357_shieldenchant"] = "Correção — O aviso de encantamento de arma da ficha de personagem podia marcar um escudo ou um item segurado na mão esquerda (grimórios, enfeites, etc.) como sem encantamento, mesmo que nenhum dos dois possa ser encantado — tanques com escudo e conjuradores segurando um item na mão esquerda viam um aviso vermelho para algo que nunca foi encantável. O aviso agora só aparece em um slot que contém uma arma realmente encantável.",
    ["wn_357_inspectiteminfo"] = "Novidade — Inspecionar outro jogador agora mostra o mesmo detalhamento por item da sua própria ficha de personagem: nível de item, nível de melhoria, texto de encantamento (ou um aviso de encantamento ausente) e encaixes de gema ao lado de cada item equipado, em vez de apenas um número médio no topo.",
    ["wn_357_inspectiteminfotoggle"] = "Novidade — Uma nova caixa de seleção permite desativar as informações de item/encantamentos/gemas da janela de inspeção de forma independente das configurações da sua própria ficha de personagem.",
    ["wn_357_enemybuffgrid"] = "Novidade — O rastreador de Buffs inimigos nos seus quadros de alvo e foco (as auras benéficas lançadas sobre quem você está mirando) agora tem seus próprios menus suspensos de Direção (direita/esquerda) e Próxima linha (cima/baixo), além de um controle deslizante de Ícones por linha — antes era fixo em 3 por linha, crescendo para cima, sem forma de mudar nenhum dos dois. O limite do controle deslizante de quantidade também passou de 8 para 12, e qualquer pilha é limitada a 3 linhas, ocultando o restante em vez de crescer indefinidamente.",
    ["wn_357_aurasgrid"] = "Novidade — As Auras normais (buffs, debuffs, ou ambos, em jogador/alvo/foco) agora usam a mesma grade de ícones por linha que os Buffs inimigos: um controle deslizante de Ícones por linha (6 por padrão) substitui a antiga quebra de linha em pixels, com o mesmo limite de 3 linhas.",
    ["wn_357_auradirectionfix"] = "Correção — As configurações de direção tanto de Auras quanto de Buffs inimigos antes não faziam nada silenciosamente: a atualização ao vivo do motor de auras só reaplicava a direção de crescimento quando o tamanho ou a quantidade de ícones também mudavam na mesma atualização, e mesmo assim um canto de ancoragem fixo fazia com que \"crescer para cima\" deixasse a pilha de ícones flutuando algumas linhas acima da barra de vida em vez de encostada nela. Ambos estão corrigidos — as mudanças de direção e de ícones por linha agora se aplicam imediatamente, e a pilha cresce exatamente de onde deveria, sem nada flutuando.",
    ["wn_357_aurasliverefresh"] = "Correção — Várias opções de Auras/Buffs inimigos (quantidade, direção, tipo) antes precisavam de um `/reload` para realmente serem aplicadas, mesmo parecendo que deveriam atualizar instantaneamente. A maioria agora atualiza; as duas que ainda realmente precisam disso — Ativar e o menu suspenso de tipo buff/debuff/ambos — agora indicam isso diretamente no painel.",
    ["wn_357_microbarcombatfade"] = "Correção — Passar o mouse sobre um botão da Micro Bar em combate podia gerar um erro de ação bloqueada em vez de simplesmente esmaecer a barra. O esmaecimento ao passar o mouse agora vai direto para o valor final em vez de animar durante o combate, o que evita completamente a chamada bloqueada.",

    -- =====================
    -- 3.5.5 — Novidades
    -- =====================
    ["wn_355_barhoverblocked"] = "Correção: o simples passar do mouse sobre um botão da barra de ação durante um combate produzia um erro de ação bloqueada, todas as vezes. A própria atualização de botão da Blizzard roda ao passar o mouse e termina escrevendo diretamente uma configuração de pressionar e segurar — uma escrita que não é permitida em combate e que é atribuída ao TomoMod porque os botões são nossos. Uma entrada por passagem do mouse: foi assim que uma única sessão acumulou 127 delas. O TomoMod agora escreve essa configuração pelo seu próprio caminho seguro, onde ela já estava sendo escrita corretamente, e ignora a versão redundante da Blizzard.",
    ["wn_355_barpingblocked"] = "Correção: essa mesma passagem do mouse executava uma segunda escrita proibida duas linhas adiante, desta vez pertencente ao sistema de pings. Os pings se destinam às barras da própria Blizzard e nunca se aplicaram aos botões do TomoMod, então essa chamada também passou a ser ignorada. Nenhuma das duas chegou a quebrar algo na tela — mas elas soterravam os erros reais sob ruído e faziam o complemento parecer o responsável por qualquer outra coisa que desse errado no mesmo combate.",
    ["wn_355_escapekeyblocked"] = "Correção: com uma janela do TomoMod aberta em combate, cada tecla pressionada produzia um erro de ação bloqueada — manter uma tecla de movimento pressionada bastava para encher o registro de erros sozinha. A verificação de combate já estava lá, apenas rodava uma linha tarde demais, depois da chamada protegida que deveria evitar. Agora ela roda primeiro.",
    ["wn_355_microportrait"] = "Correção: no micromenu personalizado, o botão da ficha de personagem aparecia como um quadrado colorido vazio, enquanto todos os outros botões estavam corretos. Ele é o único cuja arte não é um ícone fixo — é o retrato do seu personagem — e o TomoMod copiava uma referência de textura que simplesmente não se reproduz em nenhum outro lugar. Agora ele pede ao jogo que desenhe o seu retrato diretamente no botão e toma emprestada a mesma máscara arredondada e a mesma sombra que a Blizzard usa no seu próprio botão de personagem — assim ele mostra o seu personagem com a mesma forma e a mesma profundidade dos botões ao lado, em vez de um quadrado chapado.",
    ["wn_355_perftooltip"] = "Novidade: a dica de memória do micromenu personalizado agora abre com um bloco de Desempenho: seus quadros por segundo, sua latência local e mundial e a CPU total dos complementos. A linha de CPU só significa algo quando o jogo a está registrando, o que vem desativado por padrão e exige recarregar — então, em vez de mostrar zeros que pareceriam uma medição real, ela indica «criação de perfil desativada» até você ativá-la.",
    ["wn_355_micronative"] = "Correção: em alguns clientes, marcar «ocultar o micromenu da Blizzard» não fazia absolutamente nada: a caixa continuava marcada e a barra continuava na tela. O TomoMod procurava o menu da Blizzard por um único nome, que mudou ao longo das atualizações, e desistia assim que não o encontrava — sem sequer ocultar os botões, que era a parte que teria funcionado. Agora ele reconhece todos os nomes já usados pela Blizzard e trata os botões de qualquer forma. Se nada responder no seu cliente, ele passa a avisar uma vez no chat em vez de falhar em silêncio — relate com a versão do seu cliente se vir essa mensagem.",
    ["wn_355_queueanchor"] = "Novidade: o olho da fila — o pequeno ícone que gira enquanto você espera por uma masmorra ou campo de batalha — agora pode ser movido. A Blizzard o prende ao minimapa e não lhe dá alça alguma no modo de Edição, o que fazia dele o único elemento da interface que você simplesmente não conseguia posicionar. Ele agora aparece entre as âncoras móveis de `/tm sr`, e movê-lo durante o combate é aplicado assim que a luta termina, em vez de ser recusado.",
    ["wn_355_escapepropagate"] ="Interno: a propagação de teclado dessas janelas agora é estabelecida uma única vez, na construção da janela, em vez de ser redefinida a cada tecla pressionada. Nunca foi necessário: é uma propriedade persistente do quadro, e a única coisa que a desliga é fechar a janela com Esc, o que não pode acontecer em combate.",

    -- =====================
    -- 3.5.4 — Novidades
    ["wn_354_preyfix"] = "Correção — A barra de progresso do Prey Tracker ficava travada permanentemente em 0%. `GetPreyWidgetInfo` mantinha apenas o booleano retornado por `pcall`, não os dados reais do widget, então ler `.progressPercent` dele lançava um erro a cada segundo e interrompia a atualização antes que ela pudesse recorrer à contagem do objetivo da missão. A chamada agora mantém os dois valores de retorno, então um campo de widget ausente é tratado silenciosamente e o progresso real — lido da contagem de objetivo da caçada — aparece corretamente.",
    ["wn_354_extranudge"] = "Mudança — As sobreposições de movimento do Botão de Ação Extra e da Habilidade de Zona perdem as quatro setas de ajuste fino que as cercavam em `/tm layout`. Arrastar a sobreposição com o mouse continua a reposicioná-la exatamente como antes; apenas os botões extras desapareceram.",
    ["wn_354_perflocale"] = "Interno — Carregar um idioma que não fosse inglês construía e descartava imediatamente quase 2900 entradas de tradução, cinco vezes seguidas, a cada `/reload` — o arquivo era compilado por inteiro antes que o complemento pudesse decidir que não era necessário. Cada arquivo de idioma não ativo agora interrompe antes de construir sua tabela, e a verificação de mesclagem do idioma base (que não fazia nada silenciosamente por uma peculiaridade da metatabela) foi corrigida para verificar apenas o que deveria verificar.",
    ["wn_354_perfrangeticker"] = "Mudança — O temporizador de verificação de alcance dos quadros de grupo e raide, uma rede de segurança para casos que o próprio evento de alcance do jogo não cobre, rodava duas vezes por segundo por quadro, independentemente do tamanho do grupo. Agora roda a cada dois segundos — ainda mais rápido que qualquer transição que precise captar — reduzindo esse custo em três quartos.",
    ["wn_354_perfaura"] = "Interno — Escanear as auras defensivas de uma unidade abria uma nova chamada protegida para cada benefício verificado, até quarenta vezes por atualização de aura por unidade rastreada. Agora há apenas uma chamada protegida em torno de toda a varredura, com o mesmo comportamento de reserva caso algo dê errado no meio do caminho.",
    ["wn_354_perfpartylookup"] = "Interno — Os quadros de grupo abandonam uma busca linear de quadro em favor de uma tabela de busca direta, e agora se desinscrevem completamente dos eventos de vida/recurso/aura em raide — onde esses quadros ficam ocultos e os quadros de raide cuidam das atualizações — em vez de continuar processando-os silenciosamente à toa.",
    ["wn_354_perfcdf"] = "Interno — O evento de atualização do Cooldown Forge podia disparar várias vezes no mesmo quadro durante uma rajada de mudanças de recarga, cada uma repintando sozinha todas as barras e ícones. Essas rajadas agora são agrupadas em uma única repintura por quadro.",
    ["wn_354_perfmisc"] = "Interno — Algumas limpezas adicionais em caminhos críticos: a sondagem dos quadros de chefe não constrói mais novas strings a cada ciclo, a passagem de layout adiada do rastreador de objetivos e sua varredura recursiva de conteúdo não alocam mais tabelas descartáveis a cada nó, e os cálculos de velocidade do Skyriding não reconstroem mais uma closure a cada ciclo.",
    ["wn_354_optionslod"] = "Mudança — O painel de opções — Config, 28 arquivos e cerca de 17.900 linhas — agora carrega sob demanda em vez de no login. Foi movido para seu próprio complemento TomoMod_Options e só carrega na primeira vez que é realmente aberto; cada botão e comando slash que antes o alcançava diretamente agora o carrega de forma transparente no primeiro uso.",
    ["wn_354_optionsfallback"] = "Interno — As cores de pontuação Mítica+, antes lidas uma única vez no login a partir de uma tabela de tema que agora vive no complemento de opções sob demanda (e que, portanto, ainda não existia), agora são lidas de forma preguiçosa — elas se resolvem corretamente assim que o painel de opções é aberto uma vez, em vez de ficarem congeladas em um valor de reserva vazio durante toda a sessão.",
    ["wn_354_escapefix"] = "Correção — As janelas Resumo de Morte, Resumo de Corrida, Detalhamento de Feitiço e Detalhamento de Alvo do Medidor de Dano podiam deixar o Esc incapaz de fechar o menu do jogo depois de usadas, porque fechá-las do jeito antigo passava por uma função cujas chamadas protegidas são recusadas assim que o caminho é contaminado. As quatro agora usam o mesmo manipulador seguro de fechamento com Esc que todas as outras janelas do TomoMod.",

    -- =====================
    -- 3.5.3 — Novidades
    ["wn_353_brezvisual"] = "Melhoria — O HUD do Contador de Battle Rez recebeu uma atualização visual inspirada nos padrões de design do Tui. O frame agora apresenta um pano de fundo multicamadas profissional com efeitos de sombra interna, espaçamento aprimorado e tipografia refinada para melhor legibilidade durante o combate.",
    ["wn_353_brezglow"] = "Novo — Um efeito de brilho opcional agora se ativa quando as ressurreições de combate estão disponíveis, fornecendo melhor feedback visual e tornando o contador mais perceptível de relance.",
    ["wn_353_brezcolors"] = "Mudança — A paleta de cores do Contador de Battle Rez foi atualizada com cores de acento teal inspiradas em Tui e melhor contraste entre estados ativo (verde) e cooldown (vermelho) para uma indicação de status mais clara.",
    ["wn_353_brezlayers"] = "Interno — O layout do frame do Contador de Battle Rez foi refatorado com ordenação apropriada de camadas: fundo, sombra interna, textura do ícone, varredura de cooldown e sobreposições de texto. Melhor geometria e posicionamento em todos os elementos da UI.",
    ["wn_353_preytracker"] = "Novo — Rastreador de Presa: Uma barra de progresso móvel exibindo o progresso ativo da caçada Prey (recurso exclusivo da expansão Midnight). Mostra o nome da caçada, nível de dificuldade e percentual de progresso em tempo real com um design visual suave que corresponde ao Contador de Battle Rez.",
    ["wn_353_preyconfig"] = "Novo — O Rastreador de Presa está desabilitado por padrão (conteúdo exclusivo de Midnight) e pode ser habilitado em Configuração → QOL → Combate → Rastreador de Presa. Ele se oculta automaticamente quando nenhuma caçada Prey está ativa e mostra uma visualização no modo de posicionamento.",
    ["wn_353_preylayout"] = "Novo — O Rastreador de Presa está totalmente integrado ao sistema unificado de mover de layout do TomoMod. Arraste para posicioná-lo junto com outros elementos HUD usando `/tm layout`, com comportamento de bloqueio/desbloqueio sincronizado e visualizações consistentes do modo de posicionamento.",
    ["wn_353_preyapi"] = "Interno — O Rastreador de Presa lê as APIs C_QuestLog e C_UIWidgetManager para detectar quests Prey ativas e rastrear o progresso em tempo real com uma taxa de atualização de 1 segundo, fornecendo informações de status precisas durante as caçadas.",
    ["wn_353_brezcrash"] = "Correção — O Contador de Battle Rez podia falhar totalmente ao carregar em algumas versões do cliente: um método de cooldown que não existe mais, e uma chamada de nível de frame feita em uma textura em vez de um frame, ambos travavam a inicialização do módulo. Ambos corrigidos, junto com um efeito de brilho que travava assim que precisava reaparecer após ter sido ocultado uma vez.",
    ["wn_353_preyevent"] = "Correção — O Rastreador de Presa registrava um evento que não existe neste cliente, causando um erro na inicialização. Corrigido, e todo registro de evento agora está protegido para que um evento ausente não possa mais travar o módulo.",
    ["wn_353_preygui"] = "Novo — O Rastreador de Presa agora tem uma seção de configurações real: Configuração → QOL → Automações, com uma caixa de ativação e controles deslizantes de largura/tamanho de fonte. Antes não havia como ativá-lo pelo jogo.",
    ["wn_353_abmover"] = "Correção — A entrada \"Action Bars\" em `/tm layout` não fazia absolutamente nada. O código das barras de ação portado do Tui roda em um ambiente isolado que nunca se expunha ao resto do TomoMod, fazendo o modo de posicionamento falhar silenciosamente ao ativar. Agora ele alcança as barras corretamente.",
    ["wn_353_abflash"] = "Correção — Pressionar um botão de ação deixava o ícone totalmente branco, e a primeira tentativa de correção, mais cedo nesta mesma versão, não funcionou. A textura envolvida não é uma forma recortada que precisasse de outro modo de mesclagem, é um quadrado branco sólido — mesclá-la de outra maneira continuava pintando-a por cima do ícone, e a mudança fazia outras três texturas, que estavam bem o tempo todo, saírem mais claras do que deveriam. O efeito ao pressionar agora escurece o ícone em vez de cobri-lo, que é o que sempre deveria fazer.",
    ["wn_353_abpressopt"] = "Novo — Você escolhe o que um botão faz enquanto o mantém pressionado. Config → Barras de ação → Geral tem uma opção «Efeito ao pressionar» com três escolhas: o clarão da própria Blizzard, agora o padrão, o escurecimento do TomoMod, ou nada. Aplica-se assim que você escolhe, sem recarregar.",
    ["wn_353_abposition"] = "Correção — Uma barra de ação arrastada voltava à posição padrão a cada `/reload`. A posição salva nunca era realmente gravada, e o caminho de restauração nunca a relia mesmo quando estava. Ambos corrigidos — as posições das barras agora persistem corretamente.",
    ["wn_353_abcolor"] = "Mudança — A sobreposição do modo de movimento para as barras de ação e os botões de ação extra/habilidade de zona agora usa a cor teal da marca TomoMod em vez do azul original do Tui, correspondendo a todas as outras sobreposições de `/tm layout`.",
    ["wn_353_abextramover"] = "Correção — Os suportes do Botão de Ação Extra e da Habilidade de Zona tinham sua própria sobreposição de movimento separada que nunca foi conectada ao `/tm layout` — sempre visível na tela mas impossível de arrastar pela ferramenta de layout unificada. Ambos agora têm uma entrada própria de «Botão Extra» no `/tm layout`.",
    ["wn_353_brezicon"] = "Correção — O ícone do Contador de Battle Rez era exibido como um quadrado preto sólido: o caminho de textura usado não existe neste cliente. Agora exibe corretamente o ícone de Renascimento.",
    ["wn_353_nameplaterole"] = "Correção — As placas de nome podiam gerar uma enxurrada de erros de contaminação ao ler a função de grupo de uma unidade em conteúdo restrito, porque a função pode retornar como um valor secreto que não pode ser comparado diretamente. Agora está protegido e tratado como desconhecido em vez de gerar um erro.",
    ["wn_353_abmicrodefer"] = "Correção — Os botões do micromenu podiam sumir pelo resto da sessão. Quando precisam voltar ao lugar e há um combate em andamento, o movimento espera o combate terminar — mas a parte que deveria acordá-lo depois nunca existiu, então ele esperava indefinidamente, em silêncio e sem nada no registro de erros indicando isso. Agora ele roda no instante em que você sai de combate.",
    ["wn_353_abpaging"] = "Correção — Quando a barra mudava sob seus pés — um veículo, uma barra de possessão, uma postura, uma página de voo livre — os botões mantinham a aparência da página que você acabara de deixar, ou não mostravam mais nada, e só uma reconstrução completa ou um /reload resolvia. O redesenho que deveria seguir uma troca de página dependia de uma função da Blizzard que não existe mais no cliente atual, então ele nunca chegou a rodar. As barras agora se redesenham sozinhas quando trocam de página.",
    ["wn_353_aboverride"] = "Correção — A barra de substituição simplesmente nunca era observada. É a barra em que um veículo, uma montaria de voo livre ou a Forma de voo de um druida coloca você e, como nada avisava as barras de que isso havia acontecido, elas continuavam mostrando as ações da página anterior. Agora ela é acompanhada como qualquer outra troca de página: os espaços são relidos e os botões redesenhados.",
    ["wn_353_totembar"] = "Novo — Uma barra de totens. Mostra os totens que você tem no chão, na ordem de prioridade da sua própria classe, com o tempo restante escrito em cada ícone e uma varredura percorrendo-o. Clique com o botão direito em um ícone para dispensar aquele totem; a barra sai sozinha da tela quando não sobra nenhum. O quadro de totens do próprio jogo recua enquanto ela está ativa e é devolvido intacto no instante em que você a desliga.",
    ["wn_353_totemconfig"] = "Novo — A barra de totens é ligada em Config → Barras de ação → Geral, na seção Totens, e passa a valer na hora, sem recarregar. Vem desligada por padrão. Tamanho do ícone, espaçamento, borda, zoom, direção de crescimento e a aparência do texto de duração e da varredura são todos ajustáveis.",
    ["wn_353_totemlayout"] = "Novo — Posicione-a pelo `/tm layout` como qualquer outro elemento da interface. Ali ela continua visível e rotulada mesmo sem nenhum totem no chão, então dá para colocá-la antes de conjurar o primeiro, em vez de ter de plantar um totem, correr até a ferramenta de disposição e torcer para ele ainda estar de pé.",
    ["wn_353_petstancelayout"] = "Novo — A barra do familiar e a de posturas enfim podem ser dispostas. A orientação, o número de botões e as colunas haviam sido retiradas delas na suposição de que o jogo governava sua forma — e não governa: elas passam exatamente pelo mesmo código de disposição das oito barras principais, e sempre passaram, de modo que os ajustes estavam ativos esse tempo todo sem nada na tela que os alcançasse. Os três controles agora estão presentes nas duas, com teto de dez espaços em vez de doze. Definir a barra de posturas acima do número de formas da sua classe é inofensivo: o valor é limitado para você.",
    ["wn_353_loots17"] = "Novo — As tabelas de saque estão em dia para a temporada 17. A rotação de masmorras mudou por completo, então as oito novas estão lá — Descanso dos Reis, Templo de Sethraliss, Piscinas da Vida Rubi, O vale Ofuscante, Arena da Cicatriz do Vazio, Covil de Nalorakk, Beco do assassinato e Altar das Presas — junto das duas novas raides, Gruta Presa às Marés e Abismo Venenoso, e das restrições de classe de cada item que elas soltam. As tabelas da temporada anterior são aposentadas em vez de mantidas ao lado: nada em nenhuma das rotações aponta mais para elas.",
    ["wn_353_mplusteleports"] = "Novo — O rastreador de Mítica+ conhece os teletransportes da nova rotação. As cinco masmorras da rotação chegam com suas magias de teletransporte, e o Descanso dos Reis e o Templo de Sethraliss enfim têm as suas — ambos estavam vazios embora façam parte da rotação, de modo que o rastreador não tinha nada a oferecer para nenhum dos dois.",
    ["wn_353_keysync"] = "Correção — `/tmt keysync` enfim faz alguma coisa. O diagnóstico de sincronização de chaves estava escrito, e a nota logo acima até nomeava o comando a que ele deveria responder, mas nada no manipulador levava até lá — de modo que a única ferramenta para distinguir uma sincronização que falha em silêncio de outra que simplesmente não achou nada para casar ficava inalcançável de dentro do jogo. Agora ele aparece em `/tmt help` nos seis idiomas.",
    ["wn_353_totemport"] = "Interno — A barra de totens é um port, não uma reescrita: trazida do Tui como estava escrita, com cada linha alterada marcada, de modo que se atualizar com o original mais adiante seja repetir um punhado de marcas em vez de reler o arquivo inteiro. Seus tempos de recarga recusam de saída os valores secretos em vez de adivinhá-los — é assim que o resto do código portado já trata o conteúdo restrito — e toda escrita segura espera o fim do combate em vez de ser tentada no meio da briga.",
    ["wn_353_abemptyslot"] = "Correção — E com «ocultar espaços vazios» ativado, essas mesmas trocas deixavam a barra em branco em vez de desatualizada: os botões estavam lá, mas invisíveis, e desmarcar a opção fazia o problema sumir — foi justamente isso que entregou a causa. O redesenho rodava um quadro cedo demais, enquanto os botões ainda apontavam para os espaços da página que você havia deixado, então todos eram considerados vazios e esmaecidos — sem nada voltando a verificar depois. Agora ele roda uma segunda vez no quadro seguinte, quando os botões já se atualizaram.",

    -- 3.5.2 — Novidades
    -- =====================
    ["wn_352_icons"] = "Correção — Os ícones das barras de ação voltavam pretos. A verificação que deveria detectar um espaço vazio esperava que o ícone chegasse como um caminho de arquivo, que é como o jogo respondia antigamente e não responde mais há anos: agora ele devolve um número. Assim, todo ícone de verdade era reprovado num teste escrito para pegar os que faltavam, era apagado e deixava um quadrado vazio no lugar da sua magia. Tanto o caminho normal quanto o de reserva aceitam agora qualquer uma das duas respostas.",
    ["wn_352_tint"] = "Correção — Fora de alcance, sem mana e ação inutilizável deixavam de aparecer depois de um recarregamento ou de uma troca de barra, e bastava passar o mouse sobre o botão para trazê-los de volta. O TomoMod tingia o ícone exatamente no mesmo lugar em que a Blizzard o tinge, então aquele dos dois que rodasse por último decidia o que você via. A tintura é agora uma camada própria do TomoMod colocada sobre o ícone, que o sombreia exatamente como antes sem que os dois se sobrescrevam — e quando não há nada a sinalizar, ela simplesmente não está lá.",
    ["wn_352_scope"] = "Correção — Com as barras de ação desligadas, a aparência continuava sendo aplicada mesmo assim. Ela recorre a procurar os botões pelo nome, e esses nomes são os dos botões da Blizzard, tenha o TomoMod assumido o controle deles ou não — desligar as barras deixava, portanto, a aparência repintando quadros que não lhe diziam respeito. Agora ela confere se as barras estão de fato em funcionamento antes de alterar qualquer coisa.",
    ["wn_352_move"] = "Interno — As barras de ação mudaram de casa. Estavam guardadas junto com as comodidades de uso porque foi ali que a aparência começou, e deixaram de ser uma comodidade no momento em que a versão anterior fez delas um sistema próprio, com um motor, cinco camadas e botões próprios. Agora ficam com os quadros de unidade, de grupo e de raide, que é o lugar delas, e são carregadas do mesmo jeito. Nada mudou nelas no caminho — as três correções acima vieram junto.",
    ["wn_352_tui"] = "Interno — Alicerce, e nada que você possa ver ainda. Parte do que está planejado para as barras já existe em outro addon, e reescrever isso linha por linha para encaixar aqui seria demorado e introduziria erros que não estão no original. Existe agora, portanto, uma camada fina cuja única função é deixar um desses arquivos rodar aqui sem ser tocado. Onde o TomoMod já tem sua própria versão de alguma coisa — a ancoragem, o modo de mover — a camada aponta para ela em vez de arrastar uma segunda cópia junto, e é por isso que quatro funções substituem mil e seiscentas linhas daquilo. Nada chama nada disso ainda; está sendo posto no lugar de propósito por conta própria, antes que alguma coisa dependa dele.",
    ["wn_352_port"] = "Interno — E então aquilo para o qual essa camada foi construída. O módulo de barras de ação do outro addon está agora aqui por inteiro: quatorze arquivos, pouco mais de oito mil linhas, trazidos como foram escritos em vez de redigitados para encaixar. Cada ponto em que uma linha precisou mudar está marcado, de modo que, quando o original seguir em frente, colocar-se em dia será repetir um punhado de marcas em vez de reler tudo torcendo para notar o que se moveu. Está carregado, está conferido e está desligado de propósito: pousar algo deste tamanho e ligá-lo na mesma versão é o caminho para não saber dizer qual dos dois quebrou suas barras.",
    ["wn_352_portlayers"] = "Interno — O que há dentro, para o dia em que a chave for virada. Primeiro os menus suspensos: a versão passada entregou os botões próprios do TomoMod e teve de dizer com franqueza que um portal de mago ou uma armadilha de caçador não abririam numa barra que os usasse, porque o jogo recusa o caminho comum num botão fabricado por um addon e o contorno são algumas centenas de linhas que ninguém escreve duas vezes. Essas linhas vieram com a conversão, junto de um reestilo combinando do menu do próprio jogo para os botões que continuam sendo da Blizzard. O botão de ação adicional e a habilidade de zona ganham um lugar só deles, de onde o jogo não pode tirá-los sem avisar. As recargas, o brilho e o esmaecimento do que você não pode lançar chegam cada um como sua própria camada. Nada disso está ligado ainda.",
    ["wn_352_switch"] = "Mudança — A chave foi virada: as barras de ação rodam agora sobre o módulo convertido, e o sistema que as movia antes foi removido em vez de ficar ali desligado, porque dois sistemas convencidos cada um de possuir os mesmos botões não é um estado que se entregue para ver no que dá. As três últimas peças vieram junto: a aparência, que tira de um botão a arte do próprio jogo e o desenha do zero, até o nome da macro e o número de cargas; o esmaecimento de uma barra até você passar o mouse por cima, uma barra por vez, com a barra mantida visível enquanto seu grimório está aberto; e as sobreposições que você vê quando vai mover uma barra. O Masque também é suportado agora, se você o usa, e simplesmente ausente se não.",
    ["wn_352_bindings"] = "Mudança — Suas teclas continuam valendo, e há 106 coisas a menos para atribuir. A versão anterior entregava uma atribuição para cada botão de cada barra, então colocar os botões próprios do TomoMod numa barra obrigava a atribuí-la uma segunda vez na janela de atalhos do jogo, sob um cabeçalho do TomoMod, ao lado da atribuição que você já tinha. Os botões novos não pedem isso: eles leem o que você atribuiu aos próprios comandos de barra de ação do jogo e tomam essas teclas para si. Uma barra que você já tinha configurado continua funcionando sem que você mexa em nada, e uma tecla já ocupada por outra coisa fica exatamente onde está.",
    ["wn_352_settings"] = "Mudança — A página de opções das barras de ação voltou, e há uma coisa que convém saber antes de atualizar. Quando as barras trocaram de sistema, mais cedo nesta mesma versão, a página ficou reduzida a uma única mensagem, porque cada controle dela escrevia num sistema que não existia mais. Agora ela foi reconstruída sobre o que as barras realmente leem: cinco abas — os botões em si, o texto escrito sobre eles, os indicadores de fora de alcance, de recurso insuficiente e do que você não pode lançar, o desaparecimento gradual de uma barra até você apontar para ela, e uma aba por barra para quantos botões ela leva e para que lado cresce. O que convém saber: seus ajustes antigos de barras não são aproveitados. O jeito antigo de guardá-los e o novo não dão o mesmo nome a nada, e os poucos nomes parecidos não querem dizer a mesma coisa, então transferi-los significaria adivinhar — e um palpite errado deixa você com uma disposição que nunca escolheu e da qual não dá para rastrear nada. Os ajustes antigos são apagados uma única vez, no seu primeiro login após a atualização, e as barras sobem com valores padrão limpos, para você acertar como quiser.",
    ["wn_352_chatcopy"] = "Novo — A cópia de texto do chat foi refeita. A janela que aparece agora se parece com o resto do chat em vez de uma simples caixa cinza: o texto já vem selecionado e rolado até a última linha assim que abre, você pode redimensioná-la, e ela guarda 500 linhas onde antes parava em 128. Há também um botão de copiar na própria janela do chat — sempre visível, só quando você aponta para o chat, ou nunca, como preferir, em Skins, Janela de chat. E a janelinha que oferece copiar o endereço de um link agora combina com todo o resto em vez de ser o diálogo do jogo.",

    -- =====================
    -- 3.5.1 — Novidades
    -- =====================
    ["wn_351_engine"] = "Interno — As barras de ação eram repintadas por inteiro cinco vezes por segundo, cada botão, tivesse mudado algo ou não. É o formato que uma aparência acaba assumindo quando cresce até virar um conjunto de recursos sem que nunca lhe tenham dado um lugar onde guardar alguma coisa. Agora existe uma única peça dona da pergunta — em que estado está este botão — e é o jogo que a avisa quando algo acontece, em vez de ela conferir num temporizador; e ela só repassa a notícia quando um valor de fato mudou. O alcance é a exceção, porque o jogo não tem como anunciá-lo: essa conferência continua num temporizador, e apenas enquanto você tem um alvo. Ela também nunca supõe que o botão embaixo pertença à Blizzard, que é justamente o que tornou possível todo o resto desta versão.",
    ["wn_351_render"] = "Novo — Ícones e recargas passaram a ser ajustáveis. Os números da recarga e seu tamanho, a cor e a opacidade da varredura, a borda e o brilho, o texto de cargas e acúmulos com seu tamanho, o nome da macro, o esmaecimento de uma ação que você não pode usar, e o quanto o ícone é recortado — até não recortar nada. Soma-se a escolha de quem desenha a recarga: a Blizzard, que mantém a própria varredura e apenas a reestiliza, ou o TomoMod, que a desenha. A Blizzard segue sendo o padrão e, por ora, a mais segura das duas; a do TomoMod é o que os novos botões mais abaixo precisam, e está ali para poder se provar antes que algo dependa dela.",
    ["wn_351_glow"] = "Novo — Dois brilhos nas barras, e ambos podem estar acesos ao mesmo tempo. Um é o destaque clássico de um proc; o outro segue a sugestão de rotação que o próprio jogo faz. Cada um tem seu estilo — Pixel, Autolançamento, Botão, Proc ou Blizzard — sua cor, e na variante de pixel o número de linhas, sua espessura e a velocidade da animação. Eles convivem em vez de se revezar, porque cada um mantém a própria pega sobre o botão. A correspondência é feita pela magia, então uma macro que acaba lançando algo brilha exatamente como a magia sozinha, e um talento que renomeia uma magia também é acompanhado. O brilho de rotação vem desligado e exige que o recurso exista no seu personagem.",
    ["wn_351_hotkeys"] = "Novo — O texto de atalho nos botões agora é seu: mostrar ou não, o tamanho, a cor, em que canto ele fica, o quanto é deslocado, se é abreviado e se aparece sequer numa casa vazia. Ele é deduzido da própria atribuição em vez de copiado do rótulo da Blizzard, e isso importa porque um botão feito pelo TomoMod não tem rótulo algum a copiar — o da Blizzard fica como reserva, para que uma mudança inesperada num patch futuro signifique um texto um pouco pior e não texto nenhum. Soma-se um modo de atribuição: você liga, passa o mouse sobre um botão, aperta uma tecla. Clique direito ou Esc apaga uma. Ele não abre em combate.",
    ["wn_351_special"] = "Novo — Coisas que as barras sabiam e nunca lhe mostraram. Numa barra com aparência aplicada você não conseguia ver em que postura estava, qual encantamento de arma estava equipado, nem qual habilidade do familiar estava em autolançamento: a aparência remove os marcadores da Blizzard e desbota o destaque dela. Agora há um anel para a ação ativa e para itens equipados, cada um com sua cor e uma espessura comum, num único anel com uma ordem de precedência para que dois estados nunca se empilhem numa confusão. O autolançamento do familiar ganha seu próprio cintilar, que convive com os dois brilhos acima. A barra do familiar pode se esconder quando você não tem familiar. As posturas não têm equivalente — não há como perguntar ao jogo se uma classe tem formas, e os próprios botões de postura da Blizzard já somem sozinhos quando não há nada a mostrar.",
    ["wn_351_ownbuttons"] = "Novo — O TomoMod agora pode fabricar seus próprios botões de ação em vez de tomar emprestados os da Blizzard. Está desligado em todo lugar, liga-se uma barra por vez e desfaz-se desmarcando a opção e recarregando. Tudo o que está acima funciona neles sem mudança. Leia os limites antes de ligar, porque eles são reais: menus suspensos não abrem numa barra convertida — portais de mago, armadilhas de caçador, frascos invocados. Barras de veículo e de substituição ainda acompanham a troca de página, mas o botão de saída específico e sua arte não vêm junto. O destaque de rotação do jogo não é desenhado neles; use o brilho de rotação acima no lugar. As barras de familiar e de postura ficam inteiramente nos botões da Blizzard. Está marcado como experimental porque é.",
    ["wn_351_bindings"] = "Novo — Os botões novos vêm com 106 atribuições já declaradas, então aparecem na janela de atalhos do próprio jogo, sob um cabeçalho TomoMod com uma seção por barra. Eles são vinculados por um clique dedicado em vez de um clique esquerdo comum, e é isso que faz o lançamento ao apertar a tecla se comportar direito — é uma armadilha conhecida, e o Bartender4 fez a mesma mudança anos atrás pelo mesmo motivo.",
    ["wn_351_keybound"] = "Novo — As barras do TomoMod se juntam ao modo de atribuição compartilhado que Dominos, Bartender4 e Bagnon usam: uma única passada atribui as suas barras e as deles juntas, em vez de cada addon insistir no próprio. A biblioteca que arbitra isso agora vem incluída, então o modo compartilhado está lá quer você use um desses addons ou não. Um detalhe que vale registrar para quem for atualizá-la da próxima vez: ela precisa vir de uma versão empacotada, nunca do espelho no GitHub, que calcula a própria versão a partir de uma marca que só é preenchida dentro de uma cópia de trabalho do código — copiada para qualquer outro lugar, ela falha assim que é carregada.",
    ["wn_351_tabs"] = "Mudança — A página de opções das barras de ação tem agora cinco abas em vez de duas: Aparência, Botões, Brilho, Atalhos e Barras. Até agora toda novidade caía numa única coluna longa da aba de aparência, e três das cinco camadas desta versão teriam ido parar lá também.",

    -- =====================
    -- 3.4.6 — Novidades
    -- =====================

    ["wn_346_probe_secret"] = "Correção — Os ícones de benefício no Estúdio de recargas, que a 3.4.5 tinha acabado de ensinar a manter a contagem em combate, geravam um erro no primeiro ícone que vigiava um benefício. Ao marcador invisível preso a cada ícone se perguntava se ele estava na tela, partindo do princípio de que essa é uma pergunta sobre um pedaço da interface e não sobre o benefício — e não é. Que um ícone de aura esteja na tela é exatamente o fato de o benefício estar ativo, que é justamente o que o jogo está retendo: o sim-ou-não devolvido estava ele próprio retido, e consultá-lo era o que falhava. Proteger a chamada nunca poderia ajudar: a chamada funcionava perfeitamente, e a falha vinha uma linha depois, ao olhar para a resposta.",
    ["wn_346_probe_cooldown"] = "Mudança — Então a pergunta é feita a outra coisa. Cada ícone já tem a sua própria varredura, aquela que o jogo move diretamente, e essa peça pertence ao TomoMod e não ao jogo: a varredura aparece enquanto o benefício está ativo e some quando ele acaba, e nada impede o addon de ler isso. Ela dá a mesma resposta, do lado da fronteira em que ler ainda é permitido. O marcador do próprio jogo fica atrás dele como segunda opinião, agora consultado com segurança, e se nenhum dos dois responder o ícone simplesmente não contribui com nada naquele quadro e segue movendo a varredura — que sempre foi a maior parte da sua função.",

    -- =====================
    -- 3.4.5 — Novidades
    -- =====================

    ["wn_345_class_secret"] = "Correção — As barras de vida geravam um erro a cada atualização para qualquer jogador cuja classe o jogo agora esconde: 399 vezes numa única sessão no relato que motivou isto. O patch 12.1 ampliou o que um addon não pode ler, e um valor escondido não está simplesmente ausente: ele está lá, e falha assim que se faz qualquer coisa com ele — compará-lo, procurar algo com ele, juntá-lo a um texto ou até perguntar se ele é verdadeiro. Então a verificação precisa vir antes; depois não há nada a recuperar. Dezesseis pontos do TomoMod liam cada um a classe de uma unidade e procuravam a cor da mesma forma; agora todos passam por um mesmo conjunto de auxiliares que pergunta se um valor pode ser lido antes de tocá-lo. Cada ponto decide por si o que significa uma classe desconhecida, porque a resposta certa não é a mesma em todo lugar: o lembrete de classe presume que alguém pode precisar do benefício em vez de pulá-lo, o tom de conjurador nas placas hostis fica de fora em vez de ser adivinhado, e a lista de chaves e o TomoScore simplesmente aparecem sem cor. A coroa de líder de grupo é da mesma família — quem lidera o grupo também pode estar escondido agora, e nesse caso a coroa continua oculta, pois mostrá-la sobre um jogador que talvez não seja o líder é pior do que não mostrar nenhuma.",
    ["wn_345_class_passthrough"] = "Novo — E então as cores de classe voltaram. Recorrer a uma cor de facção quando a classe não pode ser lida está correto, mas numa masmorra isso é absolutamente todo o grupo: os quadros teriam ficado com a cor errada em caráter permanente, e não de vez em quando. Acontece que o jogo ainda colore uma unidade para você mesmo quando não quer dizer a classe: a classe entra numa das funções do próprio jogo e a cor sai direto de outra, para a barra, sem que o addon leia qualquer uma das duas. As barras de vida dos quadros de unidade, das placas, dos quadros de grupo e de banda seguem esse caminho primeiro e mantêm suas cores de classe. Só que isso funciona apenas onde a cor é aplicada como está — qualquer coisa que precise escurecê-la ou misturá-la tem de ler os números, e aí a cor de facção continua sendo a resposta.",
    ["wn_345_nameplate_auras"] = "Correção — As placas de nome inimigas sumiam quando você girava a câmera. Não as auras delas: a placa inteira. Ler as auras de uma unidade é mais uma coisa que o patch 12.1 pode recusar agora, e a recusa vinha no meio do desenho da placa: tudo o que vinha depois — a barra de vida, o nome, a barra de conjuração — simplesmente não acontecia, e a placa parecia apagada. Girar a câmera disparava isso porque é o que traz placas novas para a tela. Cada leitura de aura numa placa agora é protegida por si só: uma recusa custa àquela única aura o seu ícone ou a sua contagem regressiva, e nada mais. Duas das proteções escritas para isso acabaram não protegendo nada, por um motivo que vale conhecer se você escreve Lua: uma proteção colocada em volta de uma chamada não cobre outra chamada passada a ela como argumento, porque o argumento roda primeiro. Uma das duas envolvia exatamente a chamada que falhava.",
    ["wn_345_aura_probe"] = "Interno — Onze partes diferentes do TomoMod leem as auras de uma unidade: as auras nos quadros e nas placas, o realce de dissipação, a fileira de cura contínua, o ícone de bênção de grupo, os ícones defensivos, o monitoramento de bênçãos do CooldownForge. Cada uma percorria até quarenta posições de aura uma a uma, protegendo cada passo, para descobrir só no fim que o jogo não ia responder nada. Agora elas perguntam uma única vez, e a resposta vale pelo resto do quadro: quarenta quadros de grupo custam uma pergunta em vez de mil e seiscentos passos protegidos. A pergunta é feita de propósito pelo caminho mais permissivo de ler uma aura, então um não significa que todos os outros caminhos já estavam fechados e que nada capaz de aparecer está sendo pulado. Dali saiu um bug de verdade: o CooldownForge esvaziava a própria lista de bênçãos monitoradas sempre que uma releitura era recusada, e depois não monitorava nada até o jogo permitir uma leitura. Vale dizer o limite com clareza: isso deixa tudo mais barato, não mais completo. Um ícone cuja leitura não obtém nada continua apagando, exatamente como antes.",
    ["wn_345_aura_engine"] = "Novo — As auras sumiam durante boa parte de um combate, e nada avisava: nenhum erro, nada na placa nem no quadro, só um vazio onde deveria estar o que você queria ver. Todo o resto desta versão torna inofensiva uma leitura de aura recusada; nada disso faz a aura voltar, porque o jogo não a entrega enquanto há luta. Então o TomoMod para de perguntar. Agora ele descreve o que quer — estas auras, esta quantidade, dispostas assim, com esta aparência — e o jogo procura e ordena sozinho, devolvendo os ícones prontos. Do lado do TomoMod nada mais lê uma aura, então não sobra nada a recusar. Toda fileira de auras do addon funciona assim agora: penalidades e bênçãos das placas, auras e bênçãos de alvo nos seus quadros, ícones de cura contínua do grupo, penalidades e curas contínuas da banda. As fileiras de cura contínua exigiram um passo a mais: elas funcionavam reconhecendo magias específicas, e a magia é justamente o que fica oculto — então a lista de magias a vigiar é entregue ao jogo de antemão, e ele faz a escolha. O aviso de dissipação foi o mais difícil de resolver, e muda de forma ao fazer isso. Era uma borda colorida em volta do quadro de um jogador, acesa comparando cada efeito nocivo com o que você sabe remover — e como nenhuma das duas coisas pode mais ser consultada, ela só acendia fora de combate, o oposto de quando um curandeiro precisa dela. Agora é um ícone pequeno no canto do quadro, e o próprio jogo escolhe qual efeito mostrar: dá para perguntar a ele diretamente se você pode dissipar algo, e ele responde sem deixar ninguém ler nada. Duas coisas a saber: sangramentos nunca aparecem, porque nenhuma habilidade de classe os remove, e o controle de grupo fica de fora de propósito porque tem a própria exibição. Quatro bugs apareceram no caminho: um erro toda vez que uma placa sumia, ícones criados em pleno combate que saíam sem tamanho e ficavam invisíveis para sempre, as chaves de mostrar penalidades ou curas contínuas que deixavam de fazer efeito até recarregar, e um controle deslizante de tamanho que havia parado de comandar qualquer coisa.",
    ["wn_345_aura_layout"] = "Correção — As fileiras de auras deixaram de quebrar linha e cresciam sempre no mesmo sentido, dissessem o que dissessem os ajustes. Entregar a exibição ao jogo significava informar o tamanho de um ícone, e isso não incluía nem o sentido da fileira nem onde ela deve dobrar — ambos pertencem à própria fileira e simplesmente nunca eram transmitidos. Os dois sentidos voltam a funcionar, horizontal e vertical de forma independente, junto com o espaçamento entre ícones. Na mesma linha: uma fileira configurada para oito auras podia desenhar dezesseis quando mostrava bênçãos e penalidades ao mesmo tempo, já que são duas listas distintas e cada uma recebia a cota inteira. Agora a cota é dividida. O outro lado é que uma fileira de oito não pode mais ser preenchida só com penalidades quando não há bênçãos a mostrar — as duas listas não podem emprestar espaço uma à outra.",
    ["wn_345_cdf_probe"] = "Novo — Os ícones de bênção no Cooldown Studio mantêm a contagem regressiva em combate. O studio é a única exibição que não pode ser entregue ao jogo por inteiro: ele coloca tempos de recarga e bênçãos na mesma fileira, noção que o jogo não tem, e o que ele realmente precisa é mais estreito de qualquer forma — esta bênção está ativa, e quanto falta — ou seja, exatamente o que ele não pode mais olhar. Então ele pergunta sem deixar o jogo desenhar: um marcador invisível é preso a cada ícone, vigiando apenas aquela bênção, e o jogo move diretamente a varredura do ícone. Saber se a bênção está ativa se resolve perguntando a esse marcador se ele está na tela, uma pergunta sobre um pedaço de interface e não sobre a bênção. Uma consequência a saber: apenas uma coisa por vez pode escrever a varredura, porque duas se alternando eram a causa da tremulação.",
    ["wn_345_dm_dropdowns"] = "Correção — Na página de opções do Medidor de dano, as listas suspensas de tema e de textura das barras abriam com o número certo de linhas e nenhum texto em nenhuma delas. O medidor rótula suas listas de um jeito e a lista suspensa do TomoMod espera outro, e ao contrário dos demais controles esta não tem valor de reserva, então cada linha era desenhada vazia. A página do Medidor de dano também já tem ícone próprio no menu: ela dividia o de Diagnósticos, de modo que duas entradas levavam a mesma imagem.",

    -- =====================
    -- 3.4.4 — Novidades
    -- =====================

    ["wn_344_damagemeter"] = "Novo — O TomoMod agora tem um medidor de dano. DPS e HPS, dano recebido, dano evitável, dano causado aos inimigos, absorções, interrupções, dissipações e mortes, divididos em Dano, Cura e Ações que você percorre pelo cabeçalho, com uma sessão Atual e uma Global e um cronômetro de combate. Vale saber como ele funciona, porque isso explica o que ele pode e o que não pode fazer: ele lê os dados de combate da própria Blizzard em vez de ouvir o registro de combate e somar tudo por conta própria. Isso significa nenhum muro de eventos para filtrar, e números idênticos aos do medidor da Blizzard porque são os mesmos números. Um cliente sem esses dados diz isso claramente em vez de mostrar uma janela vazia. Ele atende a /tdm e pode reportar em dizer, grupo, raide, guilda, instância, sussurro, o canal adequado ao seu grupo, ou apenas para você mesmo.",
    ["wn_344_dm_windows"] = "Novo — Até cinco janelas de medidor ao mesmo tempo, cada uma com seu tipo, sua sessão, suas colunas e seu formato de números: acompanhar dano e cura lado a lado é o caso comum, e com uma janela só era preciso ficar alternando o combate inteiro. Arraste uma janela contra outra e elas se encaixam borda a borda — a partir daí se movem juntas e compartilham a borda que as une, de modo que redimensionar uma redimensiona a outra, e afastar uma a desprende. Vêm nove estilos — Tomo Dark, Tomo Neon, Minimal, Glossy, Ember, Frost, Terminal, Void e Parchment — junto com a textura das barras, a fonte e seu tamanho, a altura das barras, a cor de destaque ou as cores de classe, a transparência dentro e fora de combate, e uma opção para manter sua própria barra sempre à vista.",
    ["wn_344_dm_breakdowns"] = "Novo — Um número numa barra não diz o que o produziu. Clique esquerdo em qualquer barra para abrir suas magias ali mesmo, clique direito para lhes dar uma janela própria: totais, acertos, críticos e taxa de crítico por magia. Um detalhamento por alvo responde à outra metade da pergunta — não o que você lançou, mas sobre o que lançou — e cada pull pode ser lido sozinho como um segmento, em vez de apenas como parte do total corrente. Clicar em um jogador na lista de mortes abre um resumo do que o matou, que também pode abrir sozinho quando você morre; /tdm resetpos traz essa janela de volta ao centro se ela tiver parado em algum lugar pouco prático.",
    ["wn_344_dm_runrecap"] = "Novo — Um resumo ao fim de uma masmorra: dano, cura, interrupções, mortes e dano evitável recebido de todo o grupo, que abre sozinho ao término da corrida ou volta com /tdm recap. Ele se constrói ao longo do caminho em vez de ler tudo no final, e isso não é preferência: exatamente quando uma chave termina, o jogo deixa de permitir que um addon leia esses valores, de modo que um resumo escrito da maneira óbvia não conseguiria nem ordenar o grupo. Em vez disso, um instantâneo discreto é tirado toda vez que você sai de combate, cerca de quinze vezes numa chave, a um custo que você não vai notar. O que estiver ilegível naquele momento é deixado como está em vez de sobrescrito, então o último número válido de um jogador nunca se perde.",
    ["wn_344_dm_standalone"] = "Observação — O medidor também é publicado separadamente como TomoDamageMeter. Se você o tiver instalado, a cópia embutida no TomoMod se afasta ao carregar e avisa uma vez no login, em vez de dois medidores disputarem as mesmas janelas, ajustes e sessões de combate. Quem cede é sempre a cópia embutida: instalar o addon independente é uma escolha deliberada, e as versões dele que já estão em circulação não têm como saber que deveriam se afastar sozinhas.",
    ["wn_344_cds_window"] = "Correção — No Cooldown Studio, a coluna de botões de barras à esquerda era desenhada por cima do botão do modo de edição na parte de baixo da janela, e os rótulos transbordavam dos botões que os continham: «Import : Buffs suivis» era simplesmente mais largo que a caixa em que estava. A coluna havia ultrapassado o espaço reservado a ela quando os botões de importação foram acrescentados, e nada nesta interface corta um elemento que transborda: ele apenas se desenha por cima do que está embaixo. O espaço agora é calculado a partir do que precisa conter, os botões são largos o bastante para o próprio texto, e a janela é maior para acomodá-los. Ela também deixa de pedir mais espaço do que sua tela tem: só lhe haviam dito para permanecer na tela, o que não adianta nada para uma janela maior que o próprio monitor — numa tela menor, toda a coluna da esquerda podia ficar além da borda. Agora ela se ajusta ao espaço disponível, e é justamente isso que torna seguro aumentá-la. O AstralForge se apoia na mesma janela e recebe o mesmo tratamento. No painel inicial, o cartão do Cooldown Studio também subiu para junto do cartão da Suite Tomo, já que ambos levam para fora.",
    ["wn_344_changelog_popup"] = "Correção — A página de Novidades não conseguia dispor as notas que exibia: ao abrir uma versão, seus parágrafos ficavam uns por cima dos outros. O motivo: um bloco de texto precisa ser medido antes de a janela ter definido sua largura, então um parágrafo que ocuparia seis linhas era medido como uma só, e tudo o que vinha abaixo era colocado no espaço que essa única linha teria ocupado. Em vez de ensinar a página a medir texto, ela agora entrega a versão escolhida a esta mesma janela, que sempre soube rolar. A página passa a ser um índice: cada versão como um botão com o número de notas que contém, quatro por linha, da mais recente à mais antiga — cinquenta e nove numa única coluna davam muita rolagem para chegar a algo antigo. Acompanham duas coisas menores. Ler uma versão antiga não conta mais como ter lido a atual: ir ver por curiosidade o que mudou na 3.2.1 não vai mais engolir o aviso de uma atualização que você ainda não viu. E a barra de rolagem desta janela mantinha as duas setas douradas da Blizzard nas duas pontas de uma trilha no restante verde; elas sumiram, e a barra usa o espaço que elas ocupavam.",
    ["wn_344_dm_config"] = "Novo — Os ajustes do medidor são agora uma verdadeira página de Medidor de dano nas opções do TomoMod, e não mais um botão que levava a outra janela. O tema, a textura das barras, a fonte e seu tamanho, a altura das barras e o destaque com a cor da classe; a opacidade do fundo, fora de combate e nos painéis de detalhe; ocultar os reinos, manter a sua própria barra à vista, as dicas nas barras, o cronômetro de combate e de que lado ele fica, reiniciar ao entrar numa instância, encaixar as janelas; os resumos automáticos de masmorra e de morte, e quantas linhas um relatório envia. Por baixo, esta página e a janela do próprio medidor passam agora por uma única descrição do que precisa ser atualizado quando um ajuste muda — do contrário haveria duas cópias disso, e elas divergiriam na primeira vez que qualquer uma fosse editada. Se uma atualização falhar, o ajuste é salvo mesmo assim, em vez de mostrar um erro e desfazer em silêncio o que você acabou de mudar. Colunas, adicionar janelas e o filtro por categoria ficam de propósito na janela do medidor, já que agem sobre uma janela específica e não sobre tudo; a página diz isso e leva você até lá. Essa janela também abria atrás das opções em vez de à frente, o que está corrigido.",
    ["wn_344_aura_secret"] = "Correção — As auras dos quadros de unidade geravam uma enxurrada de erros no patch 12.1 — 189 numa única sessão no relato que motivou isto. Antes o jogo simplesmente não devolvia nada quando um addon pedia as auras de uma unidade num estado que ele não aprovava; agora recusa o pedido de forma direta, e essa recusa não estava sendo capturada, então disparava a cada evento de aura. Agora é capturada, e a recusa tem uma saída: as auras passam a ser lidas uma a uma, o que é mais lento, mas é o único caminho que restou, e uma aura que ainda aparece vale mais do que uma que produz um erro. O monitoramento de bênçãos do CooldownForge tinha o mesmo problema pelo outro lado: a atualização de auras enviada pelo jogo pode agora chegar completamente ilegível, e só verificar se era uma atualização completa já bastava para falhar, outras 38 vezes numa sessão. Uma atualização ilegível é agora tratada como completa e tudo é simplesmente relido, que é a única maneira de ficar em dia quando o detalhe não pode ser consultado.",

    -- =====================
    -- 3.4.3 — Novidades
    -- =====================
    ["wn_343_changelog"] = "Novo — Uma página de Novidades nas opções, com todas as versões que o TomoMod já lançou. Até agora as notas de versão só apareciam na janela que segue uma atualização, e essa janela mostra apenas a versão para a qual você acabou de passar: uma vez fechada, o texto se perde. A nova página lista todas as versões, da mais recente à mais antiga, e clicar em uma abre suas notas. Ela lê exatamente as mesmas notas da janela, então não existe uma segunda lista que possa ficar para trás.",
    ["wn_343_cdf_resync"] = "Novo — Cooldown Studio: uma barra criada a partir do gerenciador de recargas da Blizzard já pode ser realinhada com ele. Essas barras estavam corretas no dia em que você as criava e depois não tinham como voltar: uma reformulação de classe obrigava você a comparar listas na mão. Ressincronizar relê a categoria: as habilidades que a Blizzard acrescentou desde então chegam, as que ela removeu são removidas. Tudo o que você fez na barra sobrevive — uma magia que continua na lista mantém sua entrada exatamente como você a ajustou, incluindo condição de brilho, visibilidade por especialização e efeitos por entrada — e o que você acrescentou não é jamais tocado nem removido, faça o que fizer a lista da Blizzard. Uma magia que você tinha acrescentado à mão e que a Blizzard passa a incluir na categoria continua sendo sua em vez de ser adotada, de modo que uma ressincronização posterior nunca poderá apagar uma entrada que você criou.",
    ["wn_343_cds_icons"] = "Cooldown Studio: a lista do que uma barra acompanha mostrava Sort 384100 — exato e sem nenhuma utilidade. Cada entrada agora mostra seu ícone e seu nome, com o identificador entre parênteses em seguida. Enquanto o cliente não tiver a magia em cache você continua vendo só o número, que é a resposta honesta em vez de uma linha em branco.",
    ["wn_343_cds_scale"] = "Novo — Cooldown Studio: um controle de escala dos ícones, nas duas disposições. Aumentar uma barra significava mover um controle de largura e depois levar o de altura exatamente ao mesmo ponto; agora é um controle só. É uma vista sobre o tamanho que você já tinha e não um ajuste novo, então continua havendo um único número por baixo e nada a manter em sincronia. Um botão devolve os ícones ao formato quadrado mantendo o tamanho que você tinha diante de si em vez de saltar para o padrão. Assim que você separa de propósito a largura e a altura, o controle de escala fica esmaecido — escalar por 1,2 deixa de ter uma resposta única nesse ponto — e é esse botão que o traz de volta.",
    ["wn_343_iconsize_range"] = "Correção — Cooldown Studio: um tamanho de ícone abaixo de 24 ou acima de 64 parecia aceito e não estava. A barra era desenhada no tamanho que você pedia e o mantinha, até que alguma ação posterior — uma ressincronização, uma importação, uma duplicação — o revertia em silêncio, sem nada que ligasse essa mudança a algo que você tivesse feito. Enquanto isso os ajustes separados de largura e altura aceitavam de 8 a 128, de modo que o mesmo ícone pequeno era alcançável por um controle e recusado pelo outro. Agora há um único intervalo, de 8 a 128, para os três. Ele é mais amplo do que antes e não mais estreito: nenhuma barra que você já tenha muda de tamanho.",
    ["wn_343_studio_shortcut"] = "Novo — Um botão do Cooldown Studio no painel inicial, para que abrir o estúdio não exija mais passar antes pelo painel do CooldownForge.",

    -- =====================
    -- 3.4.2 — Novidades
    -- =====================
    ["wn_342_astralforge"] = "Novo — AstralForge, um editor em tela cheia para as peças de um quadro de unidade. Até agora cada parte de um quadro ficava onde o TomoMod tinha decidido que ficasse, e tudo o que você recebia era um controle deslizante que a empurrava alguns pixels dali: mover o nome para o outro lado não era um ajuste, era um número grande o bastante para empurrá-lo até lá. Agora você arrasta cada peça para onde quiser: qual canto do elemento se prende, e a que ele se prende — o quadro, a barra de vida, a barra de recurso, a barra de informações. Ele se alinha a uma grade fina, se encaixa com os outros elementos quando você passa por eles, e segurando Shift você solta onde bem entender. Os controles deslizantes continuam ali para um acerto de dois pixels, e ambos escrevem a mesma coisa. Abre-se pelas opções de Quadros de unidade e, como o Cooldown Studio, só carrega quando você pede. O que você arrasta é uma cópia de pré-visualização, nunca um quadro real: o jogo protege esses durante o combate, e editá-los diretamente é justamente o que causa os problemas de interface que o TomoMod passou duas versões removendo.",
    ["wn_342_af_nameplates"] = "Novo — As placas de nome ganham o mesmo editor, e para elas é terreno totalmente novo: fora o marcador de raide, nada em uma placa tinha qualquer ajuste de posição. O nome, o valor e a porcentagem de vida, o nível, o ícone e o texto de classificação, a barra de conjuração com seu ícone, seu nome, seu cronômetro e seu escudo, e o ícone de missão podem ser posicionados um a um onde você quiser. Sua posição do marcador de raide é mantida como está, e todo o resto começa exatamente onde já estava. Duas coisas propositalmente não são arrastáveis: as auras, cuja posição é calculada a partir do lugar delas na fileira em vez de definida, e as peças presas ao preenchimento de uma barra — uma alça sobre essas alegaria mover algo que não pode mover.",
    ["wn_342_af_props"] = "Novo — Opacidade, escala e uma forçagem do tamanho do texto, por elemento. A forçagem começa em zero, ou seja «mantenha o tamanho que o módulo calculou», então nada muda até você mandar. Só aparecem os ajustes que aquela peça realmente consegue honrar: opacidade faz sentido em um texto, escala não, e uma imagem simples não aceita nenhuma das duas — você recebe os que se aplicam ao que selecionou, em vez de uma fileira fixa de controles em que metade não faz nada.",
    ["wn_342_af_customtext"] = "Novo — Texto escrito por você. Adicione até seis textos personalizados em um quadro de unidade e quatro em uma placa de nome, escreva algo como «[name] - [level]» e posicione como qualquer outro elemento. Os marcadores são nome, nível, classe, raça e guilda em um quadro, e nome, nível, classe, raça e classificação em uma placa. Vale saber por que isso não é simplesmente o complemento colando palavras: no Midnight o jogo entrega o nome e o nível de uma unidade em uma forma que um complemento não tem permissão de ler, então algo tão comum quanto juntar um nome a um traço falharia. Seu modelo é transformado em um padrão, os valores passam sem serem tocados e é o próprio jogo que monta tudo.",
    ["wn_342_af_presets"] = "Novo — Predefinições de disposição e textos de compartilhamento. Salve com um nome toda a disposição do que você está editando — cada posição, cada opacidade e escala, cada texto próprio —, aplique de volta mais tarde, ou passe para alguém como um texto que a pessoa cola. Tudo o que entra é verificado do mesmo jeito, seja seu ou de um desconhecido: valores que o complemento não reconhece são descartados, uma ancoragem impossível é recusada antes de chegar ao jogo, e uma disposição que se refere a si mesma em círculo é quebrada. O pior que um texto colado pode descrever é uma disposição.",
    ["wn_342_af_migration"] = "Seus quadros não se mexem. Cada posição que você tinha ajustado é convertida para a nova forma junto com a ancoragem contra a qual o motor a aplicava, de modo que um perfil convertido e um recém-criado desenham exatamente o mesmo quadro. Um ajuste antigo é descartado em vez de convertido: um deslocamento de auras que o motor parou de ler na 3.0.5. Ele está sem efeito há várias versões, e convertê-lo agora moveria auras que estão exatamente onde você as colocou. Os contêineres de auras também deixam de guardar sua posição em um segundo lugar só deles: arrastá-los no jogo, posicioná-los no editor e ajustá-los pelos controles agora escrevem no mesmo lugar, então não podem mais se contradizer.",
    ["wn_342_af_secret"] = "Correção — Abrir o AstralForge sobre uma unidade que realmente estava ali podia deixar você com uma janela vazia. A pré-visualização que ele constrói era alimentada com dados reais, e no jogo atual qualquer peça da interface cujo conteúdo vem de informações protegidas — um valor de vida, por exemplo — também esconde dos addons a própria posição e o próprio tamanho. Medir isso é justamente todo o trabalho do editor: a primeira medição falhava e levava a pré-visualização junto. Agora a pré-visualização funciona com dados inventados: um nome fictício, um valor de vida fictício, que nada impede de medir e que se parecem exatamente com aquilo que você está organizando. Vêm com ela duas proteções: o que mesmo assim não puder ser medido fica simplesmente sem alça em vez de travar tudo à sua volta, e se a pré-visualização não puder ser construída de jeito nenhum, a janela abre mesmo assim com sua lista de elementos, seu inspetor e suas predefinições, em vez de abrir vazia.",
    ["wn_342_keysync_realm"] ="Mítica+: a lista de chaves do grupo aparecia vazia para todo mundo do seu próprio reino. A chave dessas pessoas era recebida e guardada o tempo todo — apenas não conseguia mais ser encontrada. Quando o complemento de alguém envia a chave para você, o jogo identifica a pessoa como «Alice-Varimathras», sendo ou não esse o seu reino: cada chave fica arquivada sob um nome completo. Mas quando o TomoMod pergunta ao jogo sobre a pessoa que está ao seu lado no seu próprio reino, ele recebe «Alice» sem reino, e isso não corresponde a nada. Isso surgiu com o novo compartilhamento de chaves da 3.4.1, porque a biblioteca que ele substituiu escondia essa diferença dentro do próprio código. Um nome sem reino agora é tentado de novo com o seu, então uma chave do mesmo reino volta a ser encontrada — e isso é feito uma única vez, onde as chaves ficam guardadas, em vez de ser algo que cada tela que as lê precise lembrar de fazer.",
    ["wn_342_escape_keys"] = "Correção — Enquanto uma das janelas do próprio TomoMod estava aberta, suas teclas não faziam nada: você não conseguia se mover e suas habilidades não saíam. Qualquer janela que fecha com Esc precisa pedir o teclado ao jogo, e uma janela que segura o teclado fica com todas as teclas para si a menos que repasse o resto de propósito — o que ela só fazia de tabela, ao receber uma tecla que não lhe interessava, e nunca em combate, que é justamente quando perder as teclas custa mais caro. Agora todas as teclas passam direto; a janela fica só com Esc, e apenas fora de combate. Junto vem a outra metade do problema: uma janela segura o teclado somente enquanto está de fato na tela. Uma fechada com Esc mantinha a pegada depois disso, então o problema sobrevivia à janela que o causou e a janela seguinte que você abrisse o herdava. Isso vale para todas as janelas do addon que fecham com Esc: as opções, o instalador, a janela de saque, o hub de Mítica+, o TomoScore, o assistente de profissões, o visual das bolsas, a janela de cópia do chat e o Cooldown Studio.",
    ["wn_342_keysync_debug"] ="Novo — /tmt keysync. Ele mostra por qual canal o compartilhamento está passando, se você está em uma guilda, todas as chaves que estão guardadas naquele momento e, em seguida, cada membro do seu grupo indicando se a chave dele é realmente encontrada. Essa última linha é o ponto principal: uma chave guardada mas não encontrada é um problema diferente de uma chave que nunca chegou, e pela lista do grupo as duas parecem exatamente iguais — por isso o problema acima demorou mais para ser identificado do que para ser corrigido. O comando termina pedindo as chaves ao grupo, então executá-lo de novo um segundo depois diz se alguém respondeu.",
    ["wn_342_cdf_viewer"] = "Novo — Cooldown Studio: monte uma barra a partir do próprio gerenciador de recargas da Blizzard com um clique. Três botões — Essenciais, Utilidades e Bônus monitorados — criam uma barra já preenchida com as habilidades que a Blizzard seleciona para a especialização em que você está, na ordem dela, e os bônus monitorados chegam como bônus e não como recargas: aparecem enquanto estão ativos e descontam o que resta deles. A lista é lida no momento em que você clica e nunca é guardada: a Blizzard mantém essas três categorias em dia ao longo das reformulações de classe, então uma barra importada acompanha o jogo em vez de congelar uma cópia que estaria certa por um patch e silenciosamente errada a partir do seguinte. Onde um talento substituiu uma habilidade por outra, é a substituta que vai parar na barra, para que o ícone corresponda ao do seu grimório. É um ponto de partida, não uma amarra: o que você recebe é uma barra comum que pode reordenar, enxugar e reestilizar. E se o seu cliente não tiver o gerenciador de recargas, ou a Blizzard não selecionar nada para a especialização em que você está, o estúdio avisa em vez de entregar uma barra vazia.",

    -- =====================
    -- 3.4.1 — Novidades
    -- =====================
    ["wn_341_style"] = "Rastreador Mítica+: era a última tela do TomoMod com cores próprias. A versão anterior alinhou o placar de fim de chave e dizia que o rastreador que você vê durante a chave só combinaria quando recebesse o mesmo tratamento — é este. Agora usa o mesmo verde, o mesmo texto e as mesmas bordas de qualquer outro painel, sobre um fundo quase preto com um tom de menta. Vem junto um ajuste de tamanho de fonte, de 0,70 a 1,60: aumenta o texto sem aumentar o painel.",
    ["wn_341_segments"] = "Rastreador Mítica+: o cronômetro agora são três segmentos, um por baú, cada um contando o tempo que falta antes de perder aquele baú. Até agora o painel mostrava o tempo decorrido e a diferença para o limite total, e «quanto falta para perder o +2» era uma conta que você fazia de cabeça entre um pull e outro. Os segmentos são dimensionados pelos tempos reais de baú da masmorra, leem-se menta, amarelo e vermelho da esquerda para a direita — a janela em curso se anuncia sozinha pela cor — e um segmento gasto escurece em vez de sumir, para que a barra continue sendo o histórico da chave. Se você prefere ler a barra pela forma e não pela cor, um ajuste pinta os três do mesmo verde.",
    ["wn_341_presets"] = "Rastreador Mítica+: um painel fixo virou três aparências. Painel é o que você já tinha. HUD tira o fundo e o bloco de cabeçalho e lista os objetivos como texto simples, um pouco maior, numa fonte condensada. Mínimo são três linhas e nada mais — informações, cronômetro, lacaios — a lista de chefes some e sua contagem sobe para o cabeçalho: você continua sabendo que está em 2 de 4 sem gastar quatro linhas para dizer isso. Tudo o que uma predefinição define também é um interruptor próprio: fundo, bloco de cabeçalho, nome da masmorra, lista de chefes, disposição do cronômetro, cores dos segmentos, tamanho do texto. Mude um na mão e a predefinição passa a dizer «personalizado» em vez de fingir que você ainda está nela.",
    ["wn_341_forces"] = "Rastreador Mítica+: a barra de lacaios podia mentir em vez de admitir que não enxergava. O jogo esconde cada vez mais valores em combate, e a barra fazia contas com eles do mesmo jeito — uma contagem ilegível saía como zero, e uma barra que se esvazia no meio de um pull não parece dado faltando, parece um reset. Agora ela guarda o último número que realmente conseguiu ler e recua por etapas: contagens exatas, depois só a porcentagem, depois congelada. Também mostra o que falta matar em vez de 730 / 1000, e informa o momento em que a contagem foi concluída.",
    ["wn_341_bossnames"] = "Rastreador Mítica+: os nomes dos chefes vinham de uma tabela escrita à mão que vence a cada temporada. A Blizzard adiciona masmorras e reaproveita entradas do diário entre elas, então uma lista dessas está errada no dia em que o patch sai e nada te avisa: os nomes simplesmente degradam para «Chefe 1». Os nomes agora são resolvidos ao vivo pelo jogo, de três formas e nessa ordem: o mapa em que você está, depois o nome da masmorra comparado ao diário, e depois o texto bruto do objetivo se nada mais funcionar. O que ele encontra fica guardado por masmorra: é aprendido e não escrito de antemão, portanto não pode vencer.",
    ["wn_341_splits"] = "Rastreador Mítica+: você não tinha nada com que comparar uma chave. Cada chave concluída passa a ser registrada por masmorra e por nível, e na tentativa seguinte cada chefe mostra o quanto você está à frente ou atrás do seu melhor. Os lacaios recebem o mesmo tratamento: a cada abate o rastreador anota onde a sua melhor tentativa estava naquele ponto e mostra a diferença. Uma chave estourada também é registrada — pode ser a sua única referência naquela masmorra, e uma lenta vale mais que nenhuma. Nada vem pré-carregado: uma tabela de «lacaios esperados no chefe 2» entregue por um addon seria a rota de outra pessoa e estaria errada no dia em que a masmorra fosse rebalanceada. Um botão nas opções apaga o que foi registrado.",
    ["wn_341_banner"] = "Rastreador Mítica+: o fim de uma chave passava sem comentário. Agora há um aviso — no tempo ou estourada, o tempo da tentativa, as melhorias e a margem entre parênteses. A margem é o número que todo mundo fala em voz alta quando a chave acaba, e era a única coisa que você tinha que reconstruir sozinho a partir de um cronômetro já parado.",
    ["wn_341_options"] = "Rastreador Mítica+: ele tinha uma segunda janela de opções própria, com os mesmos ajustes da página Mítica+ na configuração do TomoMod — dois lugares para mudar o mesmo valor, e eles divergiam. Ela sumiu: /tmt agora abre a configuração na página Mítica+. Todos os outros comandos /tmt continuam iguais.",
    ["wn_341_legibility"] = "Rastreador Mítica+: o texto escrito por cima de uma barra cheia era ilegível. Cada rótulo que o rastreador desenha tem um contorno preto, e aquele texto era quase preto também, então se dissolvia no próprio contorno — as marcas de baú no cronômetro e o rótulo da barra de lacaios eram borrões, enquanto o relógio branco ao lado continuava nítido. Agora são claros. Dois detalhes vieram junto: uma duração negativa podia aparecer como uma positiva grande, -3:40 saía como 56:20, e o primeiro chefe não repete mais o seu tempo de abate duas vezes na mesma linha.",
    ["wn_341_cds_taint"] = "Cooldown Studio: abri-lo podia impedir você de sair do jogo, por dois caminhos distintos. Uma linha escrevia numa tabela que pertence à Blizzard — sem mudar o valor, mas escrever nela já basta para o jogo desconfiar depois de qualquer janela construída a partir dessa tabela, inclusive a confirmação de saída. À parte disso, a janela «copiar o estilo de» tratava o Esc com uma cópia própria de um código que já existe em outro ponto do addon, e essa cópia tinha se desviado: perdera a verificação de combate e devolvia as teclas ao jogo de um jeito que impedia o menu de abrir. As duas coisas estão corrigidas, e a janela agora usa a implementação compartilhada em vez de manter uma só dela. Nenhuma das duas afetava uma sessão em que você não tivesse aberto o Studio, e é por isso que demoraram a ser identificadas.",
    ["wn_341_keysync"] = "O TomoMod se apontava como origem de problemas de interface dezenas de vezes a cada combate, sem ser. A causa era uma biblioteca embutida, a LibOpenRaid, que descobre se o jogo está escondendo um valor tentando lê-lo e capturando o erro — a resposta está certa, mas o jogo grava o nome do TomoMod no registro dele a cada tentativa, e isso acontece o tempo todo. A biblioteca não é mais distribuída. Ela estava ali só por quatro funções de pedras angulares, embora também sincronizasse recargas, equipamento, talentos e durabilidade — e é a parte das recargas que causava tudo. O compartilhamento de pedras angulares agora é do próprio TomoMod, num arquivo bem menor: a sua pedra vem direto do jogo, e o resto é trocado com o seu grupo e a sua guilda, e guardado até o reinício semanal. Uma coisa deve funcionar pela primeira vez: a lista de pedras do grupo se atualiza sozinha quando alguém troca a dele — o retorno antigo estava ligado de um jeito que a biblioteca nunca chegava a chamar.",
    ["wn_341_buffskin"] = "O visual de bênçãos e maldições foi removido — a função inteira, com a aba e os ajustes dela. Não dá para fazer funcionar no jogo atual: os botões que a Blizzard usa para auras agora escondem o próprio tamanho dos addons, e colocar uma borda em um deles levanta um erro dentro do código da Blizzard, não no do TomoMod, onde daria para capturá-lo. Some-se a isso que esses botões são refeitos em quase todo patch: só esta versão gastou cinco tentativas atrás deles. É manutenção sem fim, justamente na parte da interface em que a exibição da própria Blizzard já basta. A sua janela de bênçãos volta à do jogo, e os ajustes são apagados dos seus perfis porque não há para onde levá-los. Se um visual próprio para as bênçãos importa mesmo para você, um addon de auras dedicado é a resposta honesta.",
    ["wn_341_auratracker"] = "O rastreador de auras foi removido. O CooldownForge faz o mesmo trabalho e faz melhor, e manter duas camadas disputando o mesmo canto da tela não ia terminar de outro jeito. A aba dele, as predefinições, o movedor e os ajustes vão junto, e uma limpeza única tira dos seus perfis os ajustes que sobraram em vez de carregá-los para sempre. Se você tinha adicionado magias a ele na mão, elas não se perdem em silêncio: não dá para convertê-las automaticamente, então o TomoMod as lista uma vez no seu próximo login, com os nomes, e você pode recriar as que ainda importam no Cooldown Studio.",
    ["wn_341_cds_reload"] = "Cooldown Studio: fechá-lo agora pode recarregar a sua interface, e faz isso por padrão. O Studio só carrega quando você pede, mas o jogo não sabe descarregar um addon — um recarregamento é a única coisa que o libera, e é também o que limpa qualquer coisa que a sessão possa ter recolhido pelo caminho. O aviso espera um momento sensato: nunca em combate, nunca durante uma chave, nunca dentro de uma masmorra ou raide, e volta assim que você sai. Dá para desligar nas opções do CooldownForge. À parte disso, sair do Studio com as barras destravadas as deixava presas no modo de edição, com o botão de retomar flutuando na tela; agora as duas formas de fechar a janela arrumam tudo.",

    -- =====================
    -- 3.3.6 — Novidades
    -- =====================
    ["wn_336_cdf_active"] = "CooldownForge: um buff ativo ficava exatamente igual a uma magia recarregando. Desde que um ícone pode seguir um buff em vez de um tempo de recarga, os dois estados chegavam à tela como a mesma imagem simples, e o único jeito de distingui-los era ler o número em cima. Dois ajustes novos os separam: a varredura do tempo de recarga e a borda podem assumir cada uma a cor da sua classe, ou uma que você escolher, enquanto o buff seguido está ativo. Os dois vêm desligados em todo lugar, então nada do que você já montou muda, e só se aplicam a entradas que realmente seguem um buff.",
    ["wn_336_cdf_threshold"] = "CooldownForge: a contagem regressiva pode mudar de cor quando uma magia está quase de volta. Defina um limite em segundos, até 60, e escolha a cor que ela assume abaixo dele — ler uma cor em pleno combate é mais rápido do que decifrar um número. Zero desliga e é o padrão. Onde o jogo se recusa a dizer a um addon quanto falta, o que acontece em conteúdo restrito, o cronômetro mantém a cor normal em vez de chutar: uma contagem que erra seria pior do que uma que fica neutra.",
    ["wn_336_cdf_font"] = "CooldownForge: o texto dos seus ícones estava preso a uma única fonte. O ajuste existia em toda barra desde o lançamento do recurso e nada nunca o leu — a contagem, os acúmulos, o nome da magia e o cronômetro espelhado estavam todos fixados na Poppins do TomoMod. Agora você pode escolher qualquer fonte compartilhada pelos seus outros addons, optar por um contorno fino, grosso ou nenhum, e dar à contagem um tamanho próprio, independente do texto de acúmulos e nome, de modo que trocar de fonte não obriga mais a abandonar os tamanhos do seu preset. Os dois controles de tamanho vão agora de 8 a 28 pixels em vez de 9 a 20. Sem nenhum addon de fontes compartilhadas instalado, a lista contém apenas Poppins e avisa.",
    ["wn_336_cdf_glow_charges"] = "CooldownForge: o brilho pode esperar todas as cargas voltarem. Uma magia de duas ou três cargas estava pronta ou não do ponto de vista do brilho, então uma carga de três acendia igualzinho a três de três. A nova condição vem da própria recarga em vez de uma contagem — o jogo esconde o número atual durante um combate, e contar é justamente o que não dá para fazer lá. Uma magia sem cargas cai na disponibilidade simples, para a condição não ser silenciosamente inútil na maioria das suas entradas.",
    ["wn_336_cdf_glow_stacks"] = "CooldownForge: o brilho pode esperar um buff seguido chegar a um número de acúmulos, ajustável por barra e substituível por ícone. O jogo não publica um máximo para um buff, então o número é você quem dá — 2 a 20 numa barra, até 99 numa entrada. Se o número de acúmulos não puder ser lido, o brilho fica apagado em vez de disparar num palpite, já que um brilho é algo sobre o qual você age.",
    ["wn_336_escape_taint"] = "Janelas: apertar Esc podia deixar de abrir o menu do jogo por completo, sem uma forma normal de sair. Oito janelas do TomoMod fechavam com Esc inscrevendo-se numa lista que a Blizzard percorre a partir do código do próprio menu, e esse código faz três chamadas que o jogo recusa assim que algo perturba a sessão — então o menu nunca abria e o Esc não fazia nada. Essas janelas agora tratam o Esc por conta própria e não encostam mais no menu do jogo. Todas as outras teclas continuam passando. Uma consequência a saber: nessas oito janelas o Esc não fecha mais durante um combate, porque a chamada que permite isso é restrita em combate. O botão de fechar continua funcionando.",
    ["wn_336_statusbar2"] = "Novo — Ocultar a barra de status 2 da Blizzard, em QOL, Automações. A segunda barra de status do modo de edição fica ao lado da principal, e não dentro dela, de modo que a opção que oculta as barras de status da Blizzard nunca a alcançava e nada em lugar algum fazia isso. Ela é tornada invisível e não clicável em vez de removida, e é isso que evita erros: a barra continua sendo da Blizzard, portanto permanece no modo de edição dela e ali você ainda pode movê-la. Desmarcar a opção a traz de volta após um recarregamento.",
    ["wn_336_ab_empty_refresh"] = "Barras de ação: com os espaços vazios ocultos, arrastar uma magia para um deles deixava o botão em branco. A magia estava mesmo ali e era lançada ao clicar, mas nada era desenhado em cima até recarregar — e soltar sobre uma barra apagava os espaços vizinhos que acabavam de aparecer para o arraste. A forma de ocultar espaços vazios mudou na versão anterior para parar de causar erros nos botões da Blizzard, e o novo método deixava a barra sem saber que um espaço havia sido preenchido. Agora ela percebe, inclusive quando uma troca de página ou de postura muda para o que um botão aponta.",
    ["wn_336_uf_aura_growth"] = "Molduras de unidade: as auras só cresciam para baixo. O ajuste de direção cobria esquerda e direita, e a metade vertical da questão não tinha ajuste nenhum — então uma moldura posicionada na parte de baixo da tela mandava a segunda fileira de penalidades para fora da borda inferior, sem nada em lugar algum para impedir. Agora há uma direção vertical ao lado da horizontal na aba Auras de cada unidade, e as fileiras podem se empilhar para cima. Para baixo continua sendo o padrão e nada do que você já configurou se mexe; a moldura também não se move, é o bloco de auras que cresce no outro sentido.",
    ["wn_336_ts_palette"] = "Mythic+: o placar de fim de corrida era a única tela do TomoMod com cores próprias — um destaque ciano onde o resto do addon é verde, sobre um fundo azulado onde o resto é neutro. Vinha de antes de sua integração ao TomoMod e nunca havia sido alinhado, então parecia a janela de outro addon. Agora ele usa o mesmo tema de todo o resto. Duas cores permanecem inalteradas de propósito: a barra « no tempo » e seu texto mantêm o próprio verde, porque em um painel que já é verde em toda parte, uma marca « no tempo » do mesmo verde deixa de indicar qualquer coisa. O rastreador exibido durante a chave não foi tocado por enquanto, então os dois só vão combinar quando ele receber o mesmo tratamento.",
    ["wn_336_cdf_talent"] = "CooldownForge: um ícone pode ser ligado a um talento — exibido só quando ele está pego, ou só quando não está. A segunda metade é tão útil quanto a primeira: uma build que abre mão de um talento costuma ganhar outro no lugar, e agora os dois ícones podem ficar na mesma barra com só o pertinente na tela. Você informa a magia que o talento concede e não um número de nó: os nós são renumerados a cada revisão de talentos, as magias não, então a condição sobrevive a um patch. Ela também acompanha seus loadouts agora — trocar de build se anuncia de forma diferente de editar talentos, e só um dos dois sinais estava sendo ouvido, de modo que uma condição podia continuar respondendo com a build anterior até que algo não relacionado forçasse uma atualização.",

    -- =====================
    -- 3.3.5 — Novidades
    -- =====================
    ["wn_335_cdf_border"] = "CooldownForge: arrastar o controle de espessura da borda fazia a borda sumir em vez de engrossá-la. Cada ajuste de estilo era guardado como um bloco só, mas o editor escreve um campo por vez — então definir a espessura jogava fora o modo de borda que estava ao lado, e sem modo o ícone era desenhado sem borda nenhuma. Escolher uma cor fazia o mesmo, e escolher um modo reiniciava a espessura em silêncio. Esses ajustes agora preservam os campos que você não mexeu. Nenhuma barra muda sozinha; refaça o ajuste e você obtém o que pediu da primeira vez.",
    ["wn_335_cdf_border_paint"] = "CooldownForge: mesmo depois de parar de sumir, a borda mal aparecia, e 1 pixel ficava exatamente igual a 4. O contorno é desenhado logo por dentro da beirada do ícone, e a imagem do ícone o cobria por inteiro — a borda era pintada e escondida embaixo, e engrossá-la só enterrava mais. A imagem agora para antes da borda e deixa espaço para ela. Duas coisas a esperar: um ícone com borda mostra sua imagem um pouco menor, que é o que uma borda custa, e uma espessura definida quando o controle parecia não fazer nada fica visível de repente — então uma barra que ficou em 4 vai parecer bem mais pesada até você ajustá-la para o que realmente queria. Ícones sem borda não mudam.",
    ["wn_335_cdf_preset"] = "CooldownForge: mexer em qualquer ajuste fino transformava a sua barra numa barra Tomo sem avisar. Escolher uma cor de borda numa barra Net ou Verre mudava o estilo dela para «Personalizado», e Personalizado não era um estilo de verdade — então o ícone caía de volta em Tomo e a base que você tinha escolhido sumia. Qual predefinição uma barra usa e se ela tem ajustes finos agora são duas coisas separadas: trocar de predefinição mantém os seus ajustes finos por cima da nova, e mexer num ajuste fino não toca mais na predefinição. Barras já salvas como Personalizado viram Tomo com os ajustes preservados, que é como elas já eram desenhadas — nada muda na tela.",
    ["wn_335_cdf_thickness"] = "CooldownForge: o controle de espessura da borda vai até 10 em vez de 4. Quatro era um limite justo enquanto a borda era invisível; agora que ela é realmente desenhada, não é mais. Lembre que a borda tira a espessura dela da imagem do ícone: em 10, de um ícone pequeno quase não sobra nada.",
    ["wn_335_cdf_target"] = "CooldownForge: uma barra agora pode depender de você ter um alvo, ao lado das condições já existentes de combate, masmorra, grupo e raide, e com as mesmas três opções — indiferente, exigir, exigir o contrário. Para a barra que você só quer ver enquanto está realmente em cima de algo, ou a barra utilitária que deve sair do caminho assim que você seleciona um alvo.",
    ["wn_335_cdf_dim"] = "CooldownForge: uma barra cuja condição de visibilidade não é atendida agora pode se atenuar em vez de sumir. Escolha «reduzir a opacidade» no lugar de «ocultar» e ajuste o quanto ela deve desbotar, de 5 % a 95 %. A barra atenuada continua viva — segue acompanhando os tempos de recarga em vez de congelar — então «em combate = sim» com essa opção deixa você, fora de combate, com uma barra legível pela metade, em vez de uma que volta já desatualizada. Ocultar continua sendo o padrão e nada muda nas barras que você já configurou.",
    ["wn_335_cdf_iconwh"] = "CooldownForge: os ícones não precisam mais ser quadrados. Largura e altura agora têm um controle cada, de 8 a 128 pixels, em vez de um único tamanho para as duas — ícones largos e baixos para uma fileira no topo da tela, altos e estreitos para uma coluna ao lado dos seus quadros. As barras que você já montou não se mexem: os valores novos começam sem definição, e sem definição quer dizer «manter o antigo tamanho quadrado».",
    ["wn_335_cdf_aura"] = "CooldownForge: um ícone pode acompanhar um bônus em vez de um tempo de recarga. Mude uma entrada para «bônus monitorado» e ela fica fora da tela enquanto o bônus não estiver ativo, aparecendo com o tempo restante e os acúmulos enquanto durar — assim um proc pode ficar na mesma barra ao lado da habilidade que o concede. Você também pode indicar outro ID de bônus, para os procs concedidos por uma magia e aplicados como outra. Na Mítica+ o jogo esconde a maior parte do que um complemento consegue ler de um bônus; isso é tratado à parte mais abaixo.",
    ["wn_335_cdf_secret"] = "CooldownForge: um bônus monitorado sumia assim que um combate começava e voltava assim que ele terminava. Toda consulta passava pelo ID de magia do bônus, e no Midnight o jogo esconde esse número durante o combate — medido como totalmente legível fora de combate contra 6,5 % dentro dele, com todo bônus monitorado sumindo no mesmo quadro em que o pull começava. O jogo até entrega esse ID uma vez, no momento em que o bônus é aplicado, junto com uma referência àquela aplicação específica: o TomoMod agora guarda o par e passa a perguntar pela aplicação, o que o jogo continua respondendo. O tempo restante e os acúmulos também voltaram na Mítica+, lidos da mesma forma — a observação anterior de que bônus monitorados funcionam ali mas sem cronômetro não é mais exata.",
    ["wn_335_cdf_aura_sources"] = "CooldownForge: os bônus monitorados são encontrados agora por dois caminhos em vez de quatro. Cada um tinha sido acrescentado para cobrir um caso que o anterior deixava passar, e nada dizia qual deles realmente fazia o trabalho — então foram medidos ao longo de cerca de 12 700 buscas cada. Dois sustentavam a função inteira, e cobrem metades opostas dela: um funciona durante uma luta, o outro fora dela. Os dois que quase nada produziam foram removidos, e com eles uma varredura de todos os seus bônus que rodava a cada quadro e para cada barra. De quebra, outra lacuna se fecha: um bônus que apenas ganha um acúmulo é comunicado pelo jogo como uma atualização, não como um bônus novo, de modo que um proc percebido assim em plena luta nunca era registrado. O que resta é um limite do próprio jogo, que vale mais conhecer do que caçar: em combate ele só nomeia parte das auras. Um bônus já ativo quando a luta começa é monitorado normalmente; um aplicado no meio dela pode não ser identificável, e o seu ícone continua oculto. Não há ajuste nenhum para isso, e a opção de bônus monitorado agora diz isso ali mesmo.",
    ["wn_335_cdf_viewer_source"] = "CooldownForge: um proc que surge no meio de um combate agora também é monitorado — o limite descrito logo acima fica em boa parte suspenso. O jogo se recusa a dizer a um addon de qual benefício se trata, mas vem desenhando ele na sua tela o tempo todo: a própria exibição de benefícios monitorados da Blizzard não está sujeita às restrições que pesam sobre um addon. O TomoMod agora lê essa exibição — se o ícone está presente, o tempo restante, a quantidade de acúmulos — em vez de fazer uma pergunta que o jogo não responde durante um combate. Nada está fixado no código e nada protegido é tocado: ele lê a mesma imagem que você está vendo. Só cobre os benefícios que a exibição de benefícios monitorados da Blizzard realmente carrega: para todo o resto, os dois métodos anteriores respondem exatamente como antes, então isso soma casos sem tirar nenhum. Vale saber se você usa o novo ocultamento barra a barra: ocultar uma barra do Cooldown Manager não lhe custa essa fonte, porque o ocultamento funciona por transparência e a barra continua rodando por baixo. Um detalhe visual a esperar em combate: onde o jogo retém os números mas ainda assim desenha a contagem regressiva, o TomoMod copia esse valor para o seu ícone — você tem o tempo restante como número, sem a varredura atrás, e ele avança aos saltos em vez de continuamente, porque a barra se atualiza por eventos e não por um cronômetro.",
    ["wn_335_cdf_aura_timer"] = "CooldownForge: um bônus monitorado podia aparecer sem cronômetro e sem varredura mesmo quando o jogo tinha informado exatamente quanto faltava. Havia duas formas de colocar uma contagem regressiva no ícone, e a errada era a preferida: a que recebe um objeto de duração, que o jogo devolve num formato diferente do que o mostrador de recarga espera. Ela o aceitava, não desenhava nada e não relatava erro algum — então a rede de segurança feita justamente para pegar essa falha nunca disparava, e o caminho numérico, que teria funcionado, nunca era alcançado. Agora os números legíveis são usados primeiro, e o objeto só quando o jogo se recusa a fornecê-los. Se os seus bônus monitorados apareciam como um ícone pelado, eles recuperam o cronômetro e os acúmulos.",
    ["wn_335_cdf_glow_aura"] = "CooldownForge: a condição de brilho «enquanto um bônus estiver ativo em você» apagava durante toda a luta, e ninguém tinha ligado isso aos bônus monitorados. Ela perguntava ao jogo pelo seu bônus do mesmo jeito que os bônus monitorados faziam originalmente — o jeito que para de responder assim que o combate começa — então o brilho simplesmente parava, o que parece um brilho mal configurado e não um defeito. Agora ela encontra os bônus exatamente como os ícones de bônus monitorado, de forma que os dois não podem mais discordar sobre o que você está carregando.",
    ["wn_335_microbar"] = "Novo — Micro Barra: a fileirinha de botões de menu da Blizzard vira uma barra sua. Escolha quais botões aparecem e em que ordem, na horizontal ou na vertical, quantos por linha, o tamanho, o espaçamento, a escala e a opacidade deles, e posicione-a onde quiser pelo painel de Movimentação. Ela pode ficar sempre na tela, aparecer ao passar o mouse, ou aparecer ao passar o mouse e continuar visível durante o combate. Os ícones podem assumir a cor da sua classe, uma cor à sua escolha ou a aparência original, com dessaturação opcional e um zoom sob o cursor. Cada botão apenas repassa o seu clique para o da Blizzard: assim tudo continua funcionando em combate e nada quebra quando um painel novo é adicionado ao jogo. Os originais também continuam rodando por baixo, de modo que os alertas, os estados acinzentados e os atalhos deles podem ser espelhados nos seus botões — com quatro estilos de brilho de alerta à escolha, escurecimento do que está indisponível, e o atalho desenhado sobre o ícone.",
    ["wn_335_cdf_aura_gate"] = "CooldownForge: um bônus monitorado não precisa mais ser uma magia que você possa conjurar. Antes de mostrar qualquer ícone, a barra confere se a entrada se aplica a você, e para uma magia ela consultava o seu grimório — o que é certo para um tempo de recarga e errado para um bônus. Bônus de proc são concedidos por um talento ou aplicados por outra magia, então o seu grimório diz que você não os tem, e a entrada era descartada antes que qualquer coisa olhasse se o bônus estava mesmo ativo. O ícone nunca aparecia — que é a maior parte da razão de existir dos bônus monitorados. Um bônus monitorado agora é julgado pelo bônus.",
    ["wn_335_cdf_aura_link"] = "CooldownForge: acompanhar um proc não exige mais caçar o ID do próprio bônus. Uma habilidade e o bônus que ela concede quase nunca têm o mesmo ID, então digitar a habilidade — o que é óbvio fazer — vigiava um bônus que ninguém nunca tem, e o ícone simplesmente ficava fora da tela. Uma entrada agora também testa o que o jogo vincula ao ID que você digitou: o Cooldown Manager da Blizzard já resolve isso para o próprio visualizador de bônus monitorados, e o TomoMod lê essa mesma resposta. Nada está fixo no código, então isso acompanha sozinho uma atualização que remaneja um proc ou um talento que o troca. O campo opcional de ID de bônus continua funcionando e continua tendo prioridade, para os casos que o jogo não vincula.",
    ["wn_335_cds_reorder"] = "Cooldown Studio: as entradas de uma barra podem ser movidas para cima e para baixo. Reordenar seus ícones exigia remover uma entrada, adicioná-la de volta no fim e refazer tudo o que vinha depois. Se o painel de opções estiver aberto na entrada que você move, ele acompanha essa entrada em vez de ficar na posição — antes acabava editando aquela que tinha tomado o lugar dela.",
    ["wn_335_mplus_teleport_override"] = "Mítica+: um teletransporte de masmorra presente no seu grimório ainda podia ser informado como não aprendido — a linha acinzentada, a dica dizendo que não estava disponível, o clique sem efeito. Quando uma masmorra volta numa temporada posterior, a Blizzard reemite o teletransporte dela como outra magia: o de Skyreach agora é conjurado como «Voie des cieux», e não a magia de Warlords que a tabela do TomoMod lista. A verificação só perguntava pela magia listada, então ter a atual era indistinguível de não ter nenhuma. Agora ela também pergunta ao jogo qual magia substitui a que ele conhece, e aceita qualquer uma das duas — por número de magia e não por nome, de modo que funciona em qualquer idioma do seu cliente e vai acompanhar uma temporada futura que remaneje um teletransporte sem precisar de atualização.",
    ["wn_335_ab_taint"] = "Barras de ação: a opção «mostrar os espaços de botão vazios» era a origem de uma rajada de erros de ação bloqueada nos botões da barra inferior esquerda — erros que o jogo atribuía ao complemento que por acaso estivesse rodando naquele instante, o que ultimamente dava a impressão de que a culpa era do Cooldown Studio. Mostrar os espaços vazios era feito escrevendo no estado interno dos botões da Blizzard e forçando a exibição deles, algo em que o jogo depois se recusa a mexer. A opção agora usa o próprio ajuste do jogo «sempre mostrar as barras de ação», e as barras que não devem mostrar seus vazios ficam invisíveis e não clicáveis no lugar disso. A Blizzard mantém o controle dos botões dela. Duas coisas a saber: esse ajuste é global, então ele liga assim que uma única das suas barras quiser os espaços vazios, e se você o tinha ligado por conta própria nas opções da Blizzard, ele será desligado assim que nenhuma barra do TomoMod precisar dele. Soltar uma magia num espaço vazio continua funcionando exatamente como antes.",
    ["wn_335_cdm_viewers"] = "Cooldowns: as quatro barras do Cooldown Manager da Blizzard agora podem ser ocultadas uma a uma, no painel Cooldowns ao lado do botão do Cooldown Studio — Essential, Utility e os dois modos de exibição dos benefícios monitorados têm cada um sua caixa. Marcar uma tira aquela barra da tela e do modo de posicionamento do TomoMod, e deixa as outras três onde estão. Ela substitui uma caixa única que não ocultava nada: apenas interrompia o revestimento do TomoMod nessas barras, que continuavam na tela com a aparência original da Blizzard — uma caixa chamada «ocultar as barras do Cooldown Manager» que as deixava mais visíveis em vez de menos. Uma barra oculta fica invisível e não clicável, e não é apagada: continua sendo a barra da Blizzard, continua funcionando por baixo, e se ela existe ou não ainda se decide no modo de edição da Blizzard. Desmarcar a coloca de volta exatamente onde você a tinha posicionado. O interruptor em CD e Recursos não mudou e responde a outra pergunta — se o TomoMod reveste essas barras, e não quais delas você quer ver. Os dois agora também funcionam juntos: ocultar uma barra continua valendo quando o próprio módulo Cooldown Manager está desligado, que era a única combinação em que a caixa era salva e nunca aplicada a nada — e é exatamente o que vai tentar quem quer se livrar dessas barras.",
    ["wn_335_cdf_entry_spec"] = "CooldownForge: a especialização de uma entrada só podia ser escolhida no momento em que você a adicionava. Depois disso, nada em lugar nenhum permitia alterá-la — um ícone adicionado na especialização errada, ou adicionado antes de você decidir restringi-lo a uma só, tinha de ser removido e adicionado de novo, o que também lhe custava o lugar na barra. A lista suspensa fica agora na própria entrada, tanto no Cooldown Studio quanto na página de ajustes de Cooldowns.",
    ["wn_335_scrollbar_click"] = "Ajustes: a barra de rolagem da janela de ajustes agora aparece e funciona. Eram cinco pixels de cinza escuro sobre um painel escuro — quase impossível de acertar, e já difícil de perceber, de modo que a rodinha era na prática o único jeito de descer uma página longa. Clicar no trilho acima ou abaixo do cursor agora salta quase uma tela naquela direção, e o cursor pode ser agarrado sem precisar mirar com precisão. A aparência também muda, de propósito: um pouco mais larga, num cinza mais claro, com uma linha escura fina na borda interna para destacar do painel atrás. As caixas de texto das cadeias de importação e exportação têm a mesma barra, e agora combinam. Isso vale para todas as páginas dos ajustes, não só uma.",
    ["wn_335_cds_tabjump"] = "Cooldown Studio: mudar quase qualquer coisa jogava você em outra aba. Editar o estilo de um ícone largava você em Compartilhamento; marcar uma condição de visibilidade largava você em Disposição. O editor se reconstrói depois de quase toda mudança e reabria a aba que tinha memorizado — mas ele só memorizava uma aba na primeiríssima vez em que ela era construída, então ficava preso naquela que você tinha aberto por último pela primeira vez, e voltar a uma aba já visitada nunca o atualizava. Agora ele acompanha a aba em que você realmente está.",

    -- =====================
    -- 3.3.4 — Novidades
    -- =====================
    ["wn_334_studio_reasons"] = "Cooldown Studio: o botão «Abrir o Cooldown Studio» podia não fazer absolutamente nada. Todos os motivos possíveis para o editor não carregar eram anunciados com a mesma mensagem — «não instalado» — inclusive o mais comum de longe: ele está instalado e apenas desmarcado na sua lista de complementos. Agora cada motivo diz qual é e o que fazer a respeito.",
    ["wn_334_studio_enable"] = "Cooldown Studio: se o único problema é estar desmarcado na lista de complementos, clicar no botão o marca e abre o editor. Quando o jogo exige antes um recarregamento, ele diz isso em vez de mandar você procurar a opção por conta própria.",
    ["wn_334_studio_preflight"] = "Cooldown Studio: o cartão da aba Cooldowns avisa que o editor não pode abrir antes de você clicar, não depois. O botão continua clicável de propósito: para um complemento desmarcado, clicar nele é justamente o que resolve a situação.",
    ["wn_334_studio_init"] = "Cooldown Studio: um editor que carregava mas não conseguia iniciar engolia o seu clique sem dizer nada. Agora ele informa que carregou mas não conseguiu se inicializar, e por quê.",
    ["wn_334_studio_toc"] = "Cooldown Studio: o subcomplemento agora exibe o ícone do TomoMod, uma categoria e o número de versão real do complemento na sua lista. Ele ainda declarava 1.0.0 e nenhum ícone, o que o fazia parecer o complemento de outra pessoa que por acaso compartilha o nome.",
    ["wn_334_package_builder"] = "Empacotamento: o download passa a ser gerado por um script que se recusa a produzi-lo se o Cooldown Studio acabar dentro da pasta TomoMod em vez de ao lado dela. O WoW só olha o primeiro nível da pasta AddOns, então um Studio guardado um nível abaixo é um Studio que ninguém vê na própria lista de complementos — exatamente a situação que metade das correções acima existe para diagnosticar.",
    ["wn_334_diag_export"] = "Diagnóstico: a janela de exportação pedia que você copiasse o relatório e então colocava o endereço do rastreador no próprio título — um endereço que só dava para levar jogando fora o relatório recém-copiado. Agora ela alterna entre o relatório e o link, diz qual dos dois acabou de ir para a área de transferência e mostra o endereço em texto claro na tela, para que você possa simplesmente lê-lo.",
    ["wn_334_diag_reminder"] = "Diagnóstico: a janela agora informa que o seu relatório está salvo e pode ser reaberto a qualquer momento com /tmdiag tracker, de modo que pegar o link primeiro não custa nada. Ao fechá-la, o endereço também é impresso no chat, uma vez por sessão, caso você a tenha fechado rápido demais.",
    ["wn_334_presets_roles"] = "Presets: os presets Tanque, Curandeiro e DPS escreviam apenas três ou quatro ajustes cada um e tiravam todo o resto da base comum — três arquétipos que eram a mesma configuração com nomes diferentes. Agora cada um escreve uma configuração de função completa nos quadros de grupo e raide, nas placas de nome, nas auras do alvo, nos recursos, nas recargas e nas barras de conjuração: placas largas coloridas por ameaça e ameaça numérica para tanques, quadros bem maiores com HoTs, dissipações e escudos para curandeiros, barras de recurso mais altas e apenas seus próprios debuffs para o dano.",
    ["wn_334_presets_reset"] = "Presets: mudar de um para outro mantinha os ajustes do anterior. Um preset só escrevia as próprias alterações, então tudo o que ele não mencionava ficava como o último o deixou — passar de Tanque para Curandeiro fazia você curar com placas em modo tanque. A base comum agora contém um valor para cada ajuste que um preset possa tocar e é escrita primeiro sempre: aplicar um preset dá o mesmo resultado, qualquer que fosse o anterior.",
    ["wn_334_presets_cards"] = "Início: os presets agora são cartões em vez de quatro botões coloridos com apenas um nome. Cada um mostra o ícone da função, a frase de resumo e três pontos sobre o que muda de verdade, com a descrição completa ao passar o mouse — e o que você está usando aparece marcado como «Ativo», algo que aquele painel não indicava em lugar nenhum.",
    ["wn_334_role_badges"] = "Ajustes: as seções que importam a uma função específica agora trazem um pequeno ícone de tanque, curandeiro ou dano no cabeçalho — HoTs e dissipações, recargas defensivas, modo tanque, rastreio de interrupções, texto de ameaça e outros. Passar o mouse pelos ícones nomeia as funções.",
    ["wn_334_role_filter"] = "Ajustes: foi adicionada uma barra de foco de função no topo da barra lateral — Todos, Tanque, Curandeiro, DPS. Escolher uma mantém em destaque os ajustes daquela função e esmaece as demais. Esmaece em vez de ocultar de propósito: uma opção cuja localização você já conhece continua exatamente onde você a deixou, qualquer que seja o foco ativo. Sua escolha é mantida entre sessões.",
    ["wn_334_chat_history_settings"] = "Histórico do bate-papo: a única coisa que dava para fazer com ele era ligá-lo. Agora ele tem uma seção própria — por quanto tempo as mensagens são mantidas (de 1 hora a 3 dias, ou sem limite), quantas linhas são armazenadas (10 a 500) e um marcador de sessão exibido após as linhas restauradas, para que tudo abaixo dele seja claramente da sessão atual. O limite de armazenamento também estava deslocado em um: anunciava 128 linhas e guardava 127.",
    ["wn_334_chat_history_delay"] = "Histórico do bate-papo: as linhas restauradas apareciam exatamente no momento em que as mensagens de carregamento de addons e os erros de Lua chegam ao bate-papo, soterrando-os sob uma página inteira de repetição. O histórico agora espera alguns segundos antes de aparecer — ajustável, ou zero para o comportamento anterior.",
    ["wn_334_chat_history_channels"] = "Histórico do bate-papo: quais canais são mantidos — sussurros, guilda, oficial, grupo, raide, instância, canais, falar, gritar, emotes — era uma opção desde que o recurso existe e não aparecia em lugar nenhum da interface. Agora está no painel. Um canal desmarcado não é registrado de forma alguma, não é apenas omitido na restauração: remarcá-lo não traz de volta o que passou enquanto ele estava desligado.",
    ["wn_334_chat_history_clear"] = "Histórico do bate-papo: agora há um botão para apagar tudo o que está armazenado, protegido por uma confirmação, e desativar o recurso apaga o que já estava salvo em vez de deixar cada linha nas suas variáveis salvas. O painel avisa isso antes de você desmarcar a caixa — junto com o fato de que o histórico é salvo para toda a conta e, portanto, compartilhado por todos os seus personagens.",
    ["wn_334_roles_guides"] = "Funções: uma nova categoria Funções, com uma página guia para tanque, cura e dano. Cada uma explica o que realmente importa naquela função, e cada ponto traz um botão que abre o painel onde está o ajuste e o destaca. A página também aplica o preset da função e muda o foco de função da barra lateral com um clique.",
    ["wn_334_search_nested_tabs"] = "Busca da configuração: um resultado dentro de uma aba aninhada — os HoTs dos quadros de raide, as cores das barras de recurso, tudo o que um painel guarda atrás da sua própria segunda fileira de abas — abria a categoria certa e então parava na primeira aba dela, não naquela que continha o que você procurava. O índice só guardava o nome da aba mais interna, que a barra externa nunca conseguia reconhecer. Agora ele registra um nome por nível, e cada barra de abas lê o seu.",
    ["wn_334_search_index_all_tabs"] = "Busca da configuração: a maior parte dos ajustes nem sequer estava no índice. As páginas que você nunca abriu são construídas uma vez, fora da tela, para que a busca possa encontrá-las — mas um painel só constrói a sua primeira aba, então tudo o que fica atrás de uma segunda ou terceira sub-aba, ou seja, a maior parte da interface, não podia ser encontrado pela busca. Agora todas as abas são percorridas. Isso é muito mais para construir, então o trabalho acontece em segundo plano em fatias de poucos milissegundos em vez de travar o jogo na sua primeira busca, e uma lista de resultados já na tela se atualiza sozinha quando termina.",
    ["wn_334_search_index_duplicates"] = "Busca da configuração: os painéis que reaproveitam uma mesma página em várias abas — cada unidade da barra de conjuração, cada quadro de unidade — se reduziam a um único resultado. O índice guardava apenas o nome da aba mais interna, de modo que a barra do alvo e a do foco escreviam a mesma entrada sobre a mesma seção, e todas as cópias exceto a primeira sumiam. As entradas agora carregam o caminho completo, e as seções de cada unidade são listadas separadamente.",
    ["wn_334_roles_deeplink"] = "Funções: os botões das páginas guia abriam a categoria certa e depois deixavam você na aba que tinha usado por último. Eles procuravam o seu ajuste no índice de busca, e justamente esses ajustes — HoTs dos quadros de raide, defensivos do grupo, modo tanque — eram os que faltavam no índice. Cada botão agora declara a sua própria rota, aba por aba: ele chega na página certa e destaca a seção, tanto em um cliente recém-iniciado quanto sobre o que você estava vendo antes.",
    ["wn_334_cr_detection"] = "Lembrete de classe: ele lia a barra de posturas por posição. Felino era a casa 2, Urso a 1, Lua-Coruja a 4 — mas onde uma forma fica nessa barra depende dos seus talentos. Assim que mudava, o lembrete comparava a sua forma real com uma casa sem nenhuma relação: avisava que faltava uma forma enquanto você estava nela, ou ficava calado enquanto você estava fora. Agora as formas são reconhecidas por magia. Os guerreiros recuperam suas três posturas, uma por especialização, em vez de uma entrada cobrindo três casas em todas as especializações. E as auras de paladino eram procuradas entre as formas, onde nunca seriam encontradas — são bônus, e são verificadas como tais.",
    ["wn_334_cr_false"] = "Lembrete de classe: alguns avisos não havia como desligar. O evocador acompanhava um único bônus de Bênção do Bronze, e essa magia aplica um diferente a cada classe — então doze classes de treze ouviam que lhes faltava um bônus que estavam carregando, enquanto o módulo estivesse ativo. O mesmo com as versões de talento de Marca da Natureza, Intelecto Arcano, Forma de Lua-Coruja e Forma de Sombra: só a versão base era conhecida, de modo que quem jogava a variante era lembrado de um bônus que já tinha.",
    ["wn_334_cr_icons"] = "Lembrete de classe: era uma linha de texto pulsante no centro da tela nomeando o que faltava. Agora é uma fileira de ícones, um para cada bônus, forma, postura ou aura ausente, e fora de combate um clique esquerdo o conjura direto, em vez de você ler o nome e ir procurá-lo em alguma barra. O clique do meio descarta um lembrete até a próxima tela de carregamento, para o bônus que você decidiu não usar hoje. Em combate nada é clicável, de propósito: uma fileira que continuasse armada estaria mentindo sobre o que um clique faz.",
    ["wn_334_cr_options"] = "Lembrete de classe: tamanho do ícone, espaçamento, escala da fileira, opacidade, o rótulo e seu tamanho, e um brilho com cor própria. Os dois controles de posição sumiram — a fileira é posicionada pelo movedor, como tudo o que se move, e tem a sua própria entrada no painel de Movimentação. Se você a tinha deslocado pelos controles, essa posição é aproveitada uma vez.",
    ["wn_334_cr_panel"] = "Lembrete de classe: a página de ajustes abre com uma prévia viva da fileira, desenhada pelo próprio módulo, então cada controle move exatamente o que você está olhando. Clicar num ícone leva ao seu interruptor, no rótulo às opções de rótulo, no espaço em volta aos controles de tamanho. E a lista de classes suportadas — um parágrafo de texto por classe — virou uma grade, uma casa por bônus ou forma monitorados, colorida por classe, cada uma um interruptor que você pode desligar para aquilo sobre o que prefere não ser lembrado.",
    ["wn_334_cr_enchants"] = "Lembrete de classe: os encantamentos de arma não eram acompanhados de forma alguma. Língua de Fogo, Fúria do Vento, Terra Viva, Guarda do Chamamarés e Guarda de Golpe Trovão têm cada um o seu lembrete, e os dois ritos do Forjaluz dividem um só, já que se excluem mutuamente e basta ter qualquer um deles. Não são auras: o jogo nunca os anunciava como anuncia um bônus — agora eles somem assim que você aplica um, em vez de esperar por uma atualização sem relação nenhuma.",
    ["wn_334_cr_poisons"] = "Lembrete de classe: os venenos de ladino, um lembrete por categoria em vez de por veneno — letal e não letal. O que importa é que as vagas estejam preenchidas: conta-se quantos venenos daquela categoria estão ativos frente a quantos você realmente pode aplicar, um ou dois com Lâminas Temperadas em Dragão. Nenhuma lista de builds para manter, e nada a reconfigurar quando você troca de talentos.",
    ["wn_334_cr_shields"] = "Lembrete de classe: os escudos de xamã são acompanhados, e Órbita Elemental é levada em conta em vez de ignorada. Com o talento você carrega Escudo de Terra em si mesmo e um dos outros dois, então ambos são verificados; sem ele, um escudo qualquer basta. O lembrete nomeia a categoria e o seu ícone aponta para o escudo certo da sua especialização — água para Restauração, relâmpagos nas demais.",
    ["wn_334_cr_context"] = "Lembrete de classe: agora você escolhe onde ele aparece — em toda parte, apenas em masmorras e raides, ou apenas em grupo. Fica oculto em cidades e estalagens por padrão, porque é justamente ali que você vai reaplicar tudo, e ele se cala enquanto você está morto, num veículo ou voando em montaria: estados em que nada da fileira pode ser pressionado.",
    ["wn_334_cr_group"] = "Lembrete de classe: ele também pode vigiar o grupo. Ative «avisar também quando falta um bônus a um membro do grupo» e um bônus de grupo que você carrega continua disparando o lembrete enquanto alguém ao alcance estiver sem ele — o caso que sempre lhe escapava, porque tê-lo você não diz nada sobre o resto do grupo. Só contam os membros a quem o atributo interessa, e apenas fora de combate: as auras de outro jogador não podem ser lidas durante uma luta, e adivinhar deixaria um lembrete na tela o pull inteiro. Desligado por padrão, porque vigiar as auras de todo mundo não sai de graça.",
    ["wn_334_cr_perf"] = "Lembrete de classe: ele revarria suas auras e sua barra de posturas uma vez por segundo, indefinidamente, tendo mudado algo ou não. O jogo já anuncia um bônus ganho, perdido ou expirado, e a barra de posturas tem os próprios eventos: essa sondagem não servia para nada. Agora ele reage a eventos, e também percebe uma mudança de talentos ou de grimório — que é justamente quando o conjunto de formas envolvidas realmente muda.",
    ["wn_334_uf_preview_engine"] = "Quadros de unidade: a prévia dos ajustes era uma maquete. Ela desenhava suas próprias barras falsas a partir dos mesmos valores, mas com código próprio, e podia portanto divergir do que você obtinha no jogo — e divergia. Agora ela é construída pelas mesmas funções que constroem seus quadros reais: textura das barras, fontes, bordas, a barra de informações, os deslocamentos de elementos, a grade de auras, os bônus inimigos e a ameaça vêm todos do motor real, e a prévia não pode mais se afastar dele.",
    ["wn_334_uf_preview_live"] = "Quadros de unidade: a prévia mostra suas unidades reais. Quando a unidade existe — seu alvo, seu foco, seu ajudante — os quadros são alimentados com dados reais e marcados como REAL; caso contrário, recorrem a valores simulados marcados como SIM. Há também um alternador Ajustar / 1:1 para conferir os quadros no tamanho real em pixels em vez da faixa reduzida.",
    ["wn_334_uf_texture_live"] = "Quadros de unidade: mudar a textura das barras não fazia nada até você recarregar — ela só era lida na criação do quadro. O mesmo valia para os números de duração das auras. Ambos passam a valer enquanto você muda, nos seus quadros reais e não apenas na prévia.",
    ["wn_334_tmkeys"] = "Mítica+: /tm keys abre o placar com o seu grupo real — nome, classe, pontuação M+ e a pedra angular que cada um carrega. Até agora esse placar só aparecia sozinho no fim de uma corrida, e o único comando que o abria à mão mostrava dados de exemplo, não gente de verdade. A hora de decidir qual chave rodar era justamente aquela em que não dava para consultá-lo. Ele funciona fora da masmorra, que é onde faz falta.",
    ["wn_334_score_roleicon"] = "Mítica+: cada linha do placar agora mostra um ícone de função ao lado do ícone de especialização, nas mesmas cores dos presets de função e dos distintivos nas configurações. A especialização diz o que a pessoa trouxe, a função diz o que ela está fazendo com isso, e uma lista de chaves lida antes do pull quer as duas coisas.",
    ["wn_334_score_spec"] = "Mítica+: a sua própria especialização faltava na sua linha do placar — o jogo não a devolve pela mesma chamada que usa para todos os outros. Agora ela é lida diretamente. Jogadores que dividem a mesma função também saíam em ordem diferente a cada abertura do placar fora de uma corrida, já que o valor de dano que normalmente os separa ali é zero para todos; os empates agora caem para nível de chave, depois pontuação, depois nome.",
    ["wn_334_mplus_teleports"] = "Mítica+: os teletransportes de masmorra que você havia conquistado apareciam como não aprendidos. O painel e o placar deixavam a masmorra acinzentada, a dica dizia que o teletransporte não estava disponível, e clicar na linha imprimia «não aprendido» sem conjurar nada. A verificação usada só relata magias concedidas pela sua classe ou pelo seu ajudante, e os teletransportes de masmorra vêm de conquistas — então ela respondia não para todos, fosse o que fosse que estivesse no seu grimório. Relatado com Alcance Celeste, e valia para a lista inteira. Agora os teletransportes funcionam pelo painel.",
    ["wn_334_delete_confirm"] = "Confirmação de exclusão: a função que digita a palavra de confirmação por você ainda procurava uma peça daquela janela que a Blizzard removeu na 11.2, e só funcionava graças a um recurso reserva que adivinha o nome interno da janela. Agora ela pede o campo de texto ao jogo pelo caminho suportado, com as rotas antigas mantidas atrás — então continuará preenchendo a caixa faça a Blizzard o que fizer com essa janela em seguida.",
    ["wn_334_friends_removed"] = "Contatos: o visual da janela de contatos foi removido, junto com sua aba nas configurações. A Blizzard vai reconstruir essa janela na 12.1, e o visual funcionava buscando várias dezenas das peças dela uma a uma, pelo nome — nomes que essa reconstrução pode mover ou renomear à vontade. Isso não envelhece com suavidade: no dia da atualização sobra uma janela meio despida, na sua tela e não na nossa. O visual vinha desativado por padrão; se você o tinha ligado, a janela simplesmente volta à aparência original da Blizzard. O botão Contatos na barra lateral do chat não é afetado.",

    -- =====================
    -- QOL: Companion Status (lembrete de mascote)
    -- =====================
    ["tab_qol_companion"]             = "Lembrete de mascote",
    ["section_companion"]             = "Status do mascote",
